// src/lib/curriculum-candidate-search.ts
import crypto2 from "crypto";
import { superAdminDb as superAdminDb3 } from "@workspace/db";
import { sql as sql4 } from "drizzle-orm";

// src/config/growth-confidence-config.ts
var DEFAULT_CONFIDENCE_CONFIG_V1 = {
  version: "growth_conf_v1",
  reviewThreshold: 0.5
  // EXPERIMENTAL_V1 — NEEDS_VERIFICATION
};
function validateConfidenceConfig(cfg) {
  const t = cfg.reviewThreshold;
  if (typeof t !== "number" || isNaN(t) || t < 0 || t > 1) {
    throw new Error(
      `[GrowthConfidenceConfig] reviewThreshold must be a finite number in [0, 1], got: ${t}`
    );
  }
}

// src/lib/curriculum-confidence.ts
var MATCHING_ALGORITHM_VERSION = "token_overlap_v1";
function computeCurriculumConfidence(meaning, item, config) {
  validateConfidenceConfig(config);
  const keywords = [
    ...meaning.strokes,
    ...meaning.skills,
    ...meaning.issues
  ].filter((k) => typeof k === "string" && k.length >= 2);
  if (keywords.length === 0) return null;
  const target = [item.title, item.description ?? ""].join(" ").toLowerCase();
  const matched = keywords.filter(
    (k) => target.includes(k.toLowerCase())
  ).length;
  const score = matched / keywords.length;
  if (score < config.reviewThreshold) return null;
  return {
    confidence: Number(score.toFixed(4)),
    match_status: "PENDING_REVIEW",
    matching_algorithm_version: MATCHING_ALGORITHM_VERSION
  };
}

// src/lib/curriculum-candidate-search.ts
var productionCurriculumDb = {
  async verifyStudentRefs(refs, poolId) {
    if (refs.length === 0) return [];
    const result = await superAdminDb3.execute(sql4`
      SELECT id
      FROM students
      WHERE id = ANY(${refs}::text[])
        AND swimming_pool_id = ${poolId}
        AND deleted_at IS NULL
    `);
    return result.rows.map((r) => r.id);
  },
  async getAssignedVersions(studentIds, poolId) {
    if (studentIds.length === 0) return [];
    const result = await superAdminDb3.execute(sql4`
      SELECT DISTINCT sca.student_id, sca.curriculum_version_id
      FROM student_curriculum_assignments sca
      JOIN curriculum_versions cv
        ON cv.id = sca.curriculum_version_id
      WHERE sca.student_id          = ANY(${studentIds}::text[])
        AND sca.swimming_pool_id    = ${poolId}
        AND sca.is_active           = true
        AND sca.deactivated_at      IS NULL
        AND cv.is_active            = true
        AND cv.swimming_pool_id     = ${poolId}
        AND cv.archived_at          IS NULL
    `);
    return result.rows;
  },
  async getCurriculumItems(versionIds, poolId) {
    if (versionIds.length === 0) return [];
    const result = await superAdminDb3.execute(sql4`
      SELECT id, title, description, curriculum_version_id
      FROM curriculum_items
      WHERE curriculum_version_id = ANY(${versionIds}::text[])
        AND is_active              = true
        AND swimming_pool_id       = ${poolId}
      ORDER BY sort_order ASC NULLS LAST
    `);
    return result.rows;
  }
};
function newCandidateId() {
  return "cand_" + crypto2.randomBytes(16).toString("hex");
}
async function searchCurriculumCandidates(params, db63 = productionCurriculumDb) {
  const { requestedRefs, poolId, meaning, config } = params;
  if (requestedRefs.length === 0) return [];
  try {
    const verifiedIds = await db63.verifyStudentRefs(requestedRefs, poolId);
    if (verifiedIds.length === 0) return [];
    const assignments = await db63.getAssignedVersions(verifiedIds, poolId);
    if (assignments.length === 0) return [];
    const allVersionIds = [...new Set(assignments.map((a) => a.curriculum_version_id))];
    const items = await db63.getCurriculumItems(allVersionIds, poolId);
    if (items.length === 0) return [];
    const results = [];
    for (const ref of verifiedIds) {
      const assignedVersionIds = new Set(
        assignments.filter((a) => a.student_id === ref).map((a) => a.curriculum_version_id)
      );
      for (const item of items) {
        if (!assignedVersionIds.has(item.curriculum_version_id)) continue;
        const conf = computeCurriculumConfidence(meaning, item, config);
        if (!conf) continue;
        results.push({
          student_ref: ref,
          candidate_id: newCandidateId(),
          display_label: item.title,
          description: item.description,
          curriculum_version_id: item.curriculum_version_id,
          confidence: conf.confidence,
          match_status: "PENDING_REVIEW",
          // AUTO_ACCEPTED 금지
          matching_algorithm_version: MATCHING_ALGORITHM_VERSION,
          _curriculum_item_id: item.id
          // match_token 생성 전용, 응답 미포함
        });
      }
    }
    return results;
  } catch (err15) {
    const safeMsg = String(
      err15 instanceof Error ? err15.message : String(err15)
    ).replace(/sk-[A-Za-z0-9_-]+/g, "[REDACTED]");
    console.error(`[curriculum-candidate-search] DB_ERROR msg=${safeMsg}`);
    return [];
  }
}

