import { createHmac } from "crypto";
var API_HOST = "https://sens.apigw.ntruss.com";
function buildSignature(method, url, timestamp, accessKey, secretKey) {
  const message = `${method} ${url}
${timestamp}
${accessKey}`;
  return createHmac("sha256", secretKey).update(message).digest("base64");
}
async function sendSensSmS({
  phone,
  message
}) {
  const accessKey = process.env.NAVER_SENS_ACCESS_KEY;
  const secretKey = process.env.NAVER_SENS_SECRET_KEY;
  const serviceId = process.env.NAVER_SENS_SERVICE_ID ?? "";
  const senderPhone = process.env.NAVER_SENS_SENDER_PHONE ?? "";
  if (!accessKey || !secretKey || !serviceId || !senderPhone) {
    throw new Error(
      "SENS \uD658\uACBD\uBCC0\uC218 \uBBF8\uC124\uC815: NAVER_SENS_ACCESS_KEY / NAVER_SENS_SECRET_KEY / NAVER_SENS_SERVICE_ID / NAVER_SENS_SENDER_PHONE"
    );
  }
  const urlPath = `/sms/v2/services/${serviceId}/messages`;
  const timestamp = String(Date.now());
  const signature = buildSignature("POST", urlPath, timestamp, accessKey, secretKey);
  const body = {
    type: "SMS",
    contentType: "COMM",
    countryCode: "82",
    from: senderPhone.replace(/[-\s]/g, ""),
    content: message,
    messages: [
      { to: phone.replace(/[-\s]/g, "") }
    ]
  };
  console.log(`[SENS] SMS \uBC1C\uC1A1 \uC2DC\uB3C4 \u2192 ${phone.slice(0, 3)}****${phone.slice(-4)} | serviceId: ${serviceId} | from: ${senderPhone}`);
  const res = await fetch(`${API_HOST}${urlPath}`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      "x-ncp-apigw-timestamp": timestamp,
      "x-ncp-iam-access-key": accessKey,
      "x-ncp-apigw-signature-v2": signature
    },
    body: JSON.stringify(body)
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    const reason = data?.errorMessage ?? data?.error?.message ?? data?.message ?? `HTTP ${res.status}`;
    const errors = Array.isArray(data?.errors) ? data.errors.join(", ") : "";
    const detail = errors ? `${reason} (${errors})` : reason;
    console.error(`[SENS] \uBC1C\uC1A1 \uC2E4\uD328 [${res.status}]: ${detail}`);
    throw new Error(`SENS SMS \uBC1C\uC1A1 \uC2E4\uD328: ${detail}`);
  }
  const statusCode = data?.statusCode ?? data?.status ?? "";
  if (String(statusCode) !== "202") {
    const reason = data?.statusName ?? data?.errorMessage ?? data?.message ?? String(statusCode);
    console.error(`[SENS] \uBC1C\uC1A1 \uAC70\uBD80 [${statusCode}]: ${reason}`);
    throw new Error(`SENS SMS \uBC1C\uC1A1 \uAC70\uBD80: ${reason}`);
  }
  console.log(`[SENS] \uBC1C\uC1A1 \uC131\uACF5 \u2713 (requestId: ${data?.requestId ?? "N/A"})`);
}

// src/lib/sms/providers/coolsms.ts
import { createHmac as createHmac2, randomBytes } from "crypto";
var API_URL = "https://api.coolsms.co.kr/messages/v4/send";
function buildAuthHeader(apiKey, apiSecret) {
  const date = (/* @__PURE__ */ new Date()).toISOString();
  const salt = randomBytes(16).toString("hex");
  const signature = createHmac2("sha256", apiSecret).update(date + salt).digest("hex");
  return `HMAC-SHA256 apiKey=${apiKey}, date=${date}, salt=${salt}, signature=${signature}`;
}
async function sendCoolSms({
  phone,
  message,
  from
}) {
  const apiKey = process.env.SMS_API_KEY;
  const apiSecret = process.env.SMS_API_SECRET;
  if (!apiKey || !apiSecret) throw new Error("CoolSMS: SMS_API_KEY / SMS_API_SECRET \uBBF8\uC124\uC815");
  const res = await fetch(API_URL, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: buildAuthHeader(apiKey, apiSecret)
    },
    body: JSON.stringify({
      message: {
        to: phone.replace(/-/g, ""),
        from: from.replace(/-/g, ""),
        text: message,
        type: "SMS"
      }
    })
  });
  if (!res.ok) {
    const body = await res.json().catch(() => ({}));
    throw new Error(`CoolSMS \uBC1C\uC1A1 \uC2E4\uD328 [${res.status}]: ${body?.errorMessage ?? "\uC54C \uC218 \uC5C6\uB294 \uC624\uB958"}`);
  }
  const data = await res.json().catch(() => ({}));
  if (data?.errorCount && data.errorCount > 0) {
    const firstError = data.resultList?.[0];
    throw new Error(`CoolSMS \uBC1C\uC1A1 \uC2E4\uD328: ${firstError?.resultMessage ?? "\uBC1C\uC1A1 \uC624\uB958"}`);
  }
}

// src/lib/sms/providers/aligo.ts
async function sendAligoSms({
  phone,
  message,
  from
}) {
  const apiKey = process.env.SMS_API_KEY;
  const userId = process.env.SMS_USER_ID;
  if (!apiKey || !userId) throw new Error("\uC54C\uB9AC\uACE0: SMS_API_KEY / SMS_USER_ID \uBBF8\uC124\uC815");
  const params = new URLSearchParams({
    key: apiKey,
    user_id: userId,
    sender: from.replace(/-/g, ""),
    receiver: phone.replace(/-/g, ""),
    msg: message,
    msg_type: "SMS",
    testmode_yn: "N"
  });
  const res = await fetch("https://apis.aligo.in/send/", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: params.toString()
  });
  const data = await res.json().catch(() => ({}));
  if (String(data?.result_code) !== "1") {
    throw new Error(`\uC54C\uB9AC\uACE0 \uBC1C\uC1A1 \uC2E4\uD328: ${data?.message ?? data?.result_code ?? "\uC54C \uC218 \uC5C6\uB294 \uC624\uB958"}`);
  }
}

