router3.post("/unified-login", async (req, res) => {
  const { identifier, password } = req.body;
  if (!identifier || !password) return err(res, 400, "\uC544\uC774\uB514\uC640 \uBE44\uBC00\uBC88\uD638\uB97C \uC785\uB825\uD574\uC8FC\uC138\uC694.");
  const id = identifier.trim();
  console.log("[LOGIN_ROUTE] unified-login \uC694\uCCAD \uC218\uC2E0", { identifier: id });
  const DEMO_ID = "demo@swimnote.app";
  const DEMO_PW = "Demo2024!";
  if (id === DEMO_ID && password === DEMO_PW) {
    try {
      const demoUser = await superAdminDb8.execute(sql13`
        SELECT u.id, u.email, u.name, u.role, u.swimming_pool_id, u.roles
        FROM users u
        JOIN swimming_pools p ON p.id = u.swimming_pool_id
        WHERE u.role = 'pool_admin'
          AND p.approval_status = 'approved'
        ORDER BY u.created_at ASC
        LIMIT 1
      `);
      if (demoUser.rows.length > 0) {
        const user = demoUser.rows[0];
        const token = signToken({ userId: user.id, role: "pool_admin", poolId: user.swimming_pool_id });
        const roles = user.roles ?? ["pool_admin"];
        return res.json({
          success: true,
          available_accounts: [{ kind: "admin", token, user: { ...user, roles } }],
          token,
          kind: "admin",
          user: { ...user, roles }
        });
      }
    } catch (e) {
      console.error("[demo-login]", e);
    }
    return err(res, 503, "\uB370\uBAA8 \uACC4\uC815\uC744 \uC0AC\uC6A9\uD560 \uC218 \uC788\uB294 \uC218\uC601\uC7A5\uC774 \uC5C6\uC2B5\uB2C8\uB2E4. \uC7A0\uC2DC \uD6C4 \uB2E4\uC2DC \uC2DC\uB3C4\uD574\uC8FC\uC138\uC694.");
  }
  try {
    const available_accounts = [];
    let wrongPwCount = 0;
    const [user] = await superAdminDb8.select().from(usersTable).where(eq(usersTable.email, id.toLowerCase())).limit(1);
    if (user) {
      const valid = await comparePassword(password, user.password_hash);
      if (!valid) {
        wrongPwCount++;
      } else {
        if (user.withdrawal_requested_at) {
          const isAnonymized = String(user.email ?? "").startsWith("deleted_") && String(user.email ?? "").endsWith("@deleted.local");
          if (isAnonymized) {
            res.status(401).json({ success: false, error: "\uD0C8\uD1F4 \uCC98\uB9AC\uB41C \uACC4\uC815\uC785\uB2C8\uB2E4.", error_code: "account_withdrawn" });
            return;
          }
          const deletionAt = new Date(new Date(user.withdrawal_requested_at).getTime() + 90 * 24 * 60 * 60 * 1e3);
          const daysLeft = Math.max(0, Math.ceil((deletionAt.getTime() - Date.now()) / 864e5));
          const wToken = signToken({ userId: user.id, role: user.role, poolId: user.swimming_pool_id, withdrawing: true });
          const { password_hash: _pw2, ...safeWUser } = user;
          const wKind = user.role === "pool_admin" ? "admin" : "teacher";
          res.json({
            success: true,
            withdrawing: true,
            days_until_deletion: daysLeft,
            available_accounts: [{ kind: wKind, token: wToken, withdrawing: true, days_until_deletion: daysLeft, user: { ...safeWUser, withdrawing: true, days_until_deletion: daysLeft } }],
            token: wToken,
            kind: wKind,
            user: { ...safeWUser, withdrawing: true, days_until_deletion: daysLeft }
          });
          return;
        }
        if (user.role === "teacher") {
          const rawRows = await superAdminDb8.execute(sql13`SELECT is_activated FROM users WHERE id = ${user.id} LIMIT 1`);
          const isActivated = rawRows.rows[0]?.is_activated ?? true;
          if (!isActivated) {
            const pendingInvite = await superAdminDb8.execute(sql13`
              SELECT id FROM teacher_invites
              WHERE user_id = ${user.id} AND invite_status = 'joinedPendingApproval' LIMIT 1
            `);
            if (pendingInvite.rows.length > 0) {
              res.status(403).json({ success: false, error: "\uAD00\uB9AC\uC790 \uC2B9\uC778 \uB300\uAE30 \uC911\uC785\uB2C8\uB2E4.", error_code: "pending_teacher_approval" });
              return;
            }
            res.status(403).json({ success: false, error: "\uACC4\uC815\uC774 \uC544\uC9C1 \uD65C\uC131\uD654\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4.", error_code: "needs_activation", needs_activation: true, teacher_id: user.id });
            return;
          }
        }
        if (user.swimming_pool_id && user.role !== "super_admin") {
          const poolStatus = (await superAdminDb8.execute(sql13`
            SELECT deactivated_at, deletion_scheduled_at
            FROM swimming_pools
            WHERE id = ${user.swimming_pool_id} AND deactivated_at IS NOT NULL LIMIT 1
          `)).rows[0];
          if (poolStatus?.deactivated_at) {
            const scheduledAt = poolStatus.deletion_scheduled_at ? new Date(poolStatus.deletion_scheduled_at) : new Date(new Date(poolStatus.deactivated_at).getTime() + 90 * 24 * 60 * 60 * 1e3);
            const daysLeft = Math.max(0, Math.ceil((scheduledAt.getTime() - Date.now()) / 864e5));
            res.status(403).json({
              success: false,
              error_code: "pool_deactivated",
              error: "\uAD6C\uB3C5\uC774 \uB9CC\uB8CC\uB418\uC5B4 \uACC4\uC815\uC774 \uBE44\uD65C\uC131\uD654\uB418\uC5C8\uC2B5\uB2C8\uB2E4.",
              message: "\uAD6C\uB3C5\uC774 \uB9CC\uB8CC\uB418\uC5B4 \uACC4\uC815\uC774 \uBE44\uD65C\uC131\uD654\uB418\uC5C8\uC2B5\uB2C8\uB2E4.",
              days_until_deletion: daysLeft,
              deletion_scheduled_at: scheduledAt.toISOString(),
              deactivated_at: poolStatus.deactivated_at
            });
            return;
          }
        }
        const isDemoAccount = user.email === "demo@swimnote.app";
        if (!isDemoAccount) {
          const totpRow = await superAdminDb8.execute(sql13`SELECT totp_enabled FROM users WHERE id = ${user.id} LIMIT 1`);
          const totpEnabled = totpRow.rows[0]?.totp_enabled ?? false;
          if (totpEnabled) {
            const totpSession = signTotpSession(user.id);
            res.json({ success: true, totp_required: true, totp_session: totpSession });
            return;
          }
        }
        const token = signToken({ userId: user.id, role: user.role, poolId: user.swimming_pool_id });
        const { password_hash: _, ...safeUser } = user;
        const rolesRow = await superAdminDb8.execute(sql13`SELECT roles FROM users WHERE id = ${user.id} LIMIT 1`);
        const roles = rolesRow.rows[0]?.roles ?? [user.role];
        available_accounts.push({ kind: "admin", token, user: { ...safeUser, roles } });
      }
    }
    const parentByLoginId = await superAdminDb8.execute(sql13`SELECT * FROM parent_accounts WHERE login_id = ${id} LIMIT 1`);
    let parentRow = parentByLoginId.rows[0] ?? null;
    if (!parentRow) {
      const byPhoneRaw = await superAdminDb8.execute(sql13`SELECT * FROM parent_accounts WHERE phone = ${id} LIMIT 1`);
      parentRow = byPhoneRaw.rows[0] ?? null;
    }
    if (parentRow) {
      const valid = await comparePassword(password, parentRow.pin_hash);
      if (!valid) {
        wrongPwCount++;
      } else {
        if (parentRow.withdrawal_requested_at) {
          const deletionAt = new Date(new Date(parentRow.withdrawal_requested_at).getTime() + 90 * 24 * 60 * 60 * 1e3);
          const daysLeft = Math.max(0, Math.ceil((deletionAt.getTime() - Date.now()) / 864e5));
          res.status(403).json({ success: false, error: `\uD0C8\uD1F4 \uCC98\uB9AC \uC911\uC778 \uACC4\uC815\uC785\uB2C8\uB2E4. ${daysLeft}\uC77C \uD6C4 \uC644\uC804\uD788 \uC0AD\uC81C\uB429\uB2C8\uB2E4.`, error_code: "withdrawal_in_progress", days_until_deletion: daysLeft });
          return;
        }
        let poolName = null;
        try {
          const [pool2] = await superAdminDb8.select({ name: swimmingPoolsTable.name }).from(swimmingPoolsTable).where(eq(swimmingPoolsTable.id, parentRow.swimming_pool_id)).limit(1);
          poolName = pool2?.name ?? null;
        } catch {
        }
        const token = signToken({ userId: parentRow.id, role: "parent_account", poolId: parentRow.swimming_pool_id });
        available_accounts.push({
          kind: "parent",
          token,
          join_status: "approved",
          join_request_id: null,
          parent: { id: parentRow.id, name: parentRow.name, nickname: parentRow.nickname || null, phone: parentRow.phone, login_id: parentRow.login_id, swimming_pool_id: parentRow.swimming_pool_id, pool_name: poolName }
        });
      }
    }
    if (available_accounts.length === 0) {
      if (wrongPwCount > 0) {
        res.status(401).json({ success: false, error: "\uBE44\uBC00\uBC88\uD638\uAC00 \uC77C\uCE58\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", error_code: "wrong_password" });
        return;
      }
      res.status(401).json({ success: false, error: "\uAC00\uC785\uB41C \uACC4\uC815\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.", error_code: "user_not_found" });
      return;
    }
    const first = available_accounts[0];
    res.json({
      success: true,
      available_accounts,
      // 하위 호환 필드
      token: first.token,
      kind: first.kind,
      user: first.kind === "admin" ? first.user : void 0,
      parent: first.kind === "parent" ? first.parent : void 0
    });
  } catch (e) {
    console.error("[LOGIN_ROUTE_ERROR]", { path: "/unified-login", body: { identifier: req.body?.identifier }, reason: e?.message, stack: e?.stack });
    return err(res, 500, "\uC11C\uBC84 \uC624\uB958\uAC00 \uBC1C\uC0DD\uD588\uC2B5\uB2C8\uB2E4.");
  }
});
router3.post("/check-role-permission", requireAuth, async (req, res) => {
  const { role } = req.body;
  if (!role) return err(res, 400, "role\uC744 \uC9C0\uC815\uD574\uC8FC\uC138\uC694.");
  try {
    const userId = req.user.userId;
    if (["super_admin", "platform_admin", "super_manager"].includes(role)) {
      res.json({ valid: true });
      return;
    }
    const userRow = await superAdminDb8.execute(sql13`
      SELECT is_activated, roles, role AS primary_role FROM users WHERE id = ${userId} LIMIT 1
    `);
    const u = userRow.rows[0];
    if (!u) {
      res.json({ valid: false });
      return;
    }
    const userRoles = u.roles?.length ? u.roles : [u.primary_role];
    if (!userRoles.includes(role)) {
      return res.status(403).json({ valid: false, error: "invalid_role" });
    }
    if (role === "teacher") {
      if (userRoles.includes("pool_admin") || u.primary_role === "pool_admin") {
        res.json({ valid: true });
        return;
      }
      const rows = await superAdminDb8.execute(sql13`
        SELECT invite_status FROM teacher_invites WHERE user_id = ${userId} LIMIT 1
      `);
      const row = rows.rows[0];
      if (!row) {
        res.json({ valid: u.is_activated === true });
        return;
      }
      res.json({ valid: row.invite_status === "approved" });
      return;
    }
    res.json({ valid: true });
  } catch (e) {
    console.error(e);
    return err(res, 500, "\uC11C\uBC84 \uC624\uB958\uAC00 \uBC1C\uC0DD\uD588\uC2B5\uB2C8\uB2E4.");
  }
});
router3.get("/verify-role", requireAuth, async (req, res) => {
  const { userId, role } = req.user;
  if (["super_admin", "platform_admin", "super_manager"].includes(role)) {
    return res.json({ valid: true, role });
  }
  try {
    const rolesRow = await superAdminDb8.execute(sql13`
      SELECT roles, role AS primary_role, swimming_pool_id FROM users WHERE id = ${userId} LIMIT 1
    `);
    const row = rolesRow.rows[0];
    if (!row) return res.status(403).json({ valid: false, error: "\uACC4\uC815 \uC5C6\uC74C" });
    const dbRoles = row.roles?.length ? row.roles : [row.primary_role];
    if (!dbRoles.includes(role)) {
      return res.status(403).json({ valid: false, error: "invalid_role", db_roles: dbRoles });
    }
    return res.json({ valid: true, role, db_roles: dbRoles, pool_id: row.swimming_pool_id });
  } catch (e) {
    console.error(e);
    return err(res, 500, "\uC11C\uBC84 \uC624\uB958\uAC00 \uBC1C\uC0DD\uD588\uC2B5\uB2C8\uB2E4.");
  }
});
router3.post("/switch-role", requireAuth, async (req, res) => {
  const { role } = req.body;
  if (!role) return err(res, 400, "\uC804\uD658\uD560 \uC5ED\uD560\uC744 \uC9C0\uC815\uD574\uC8FC\uC138\uC694.");
  try {
    const rolesRow = await superAdminDb8.execute(sql13`SELECT roles, swimming_pool_id, role AS primary_role FROM users WHERE id = ${req.user.userId} LIMIT 1`);
    const row = rolesRow.rows[0];
    if (!row) return err(res, 404, "\uACC4\uC815\uC744 \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.");
    let userRoles = row.roles ?? [];
    const isPoolAdmin = userRoles.includes("pool_admin") || row.primary_role === "pool_admin";
    if (!userRoles.includes(role) && role === "teacher" && isPoolAdmin) {
      userRoles = [...userRoles, "teacher"];
      const rolesLiteral = `{${userRoles.map((r) => `"${r}"`).join(",")}}`;
      await superAdminDb8.execute(sql13.raw(`UPDATE users SET roles = '${rolesLiteral}'::TEXT[] WHERE id = '${req.user.userId}'`));
    }
    if (role === "teacher" && isPoolAdmin) {
      try {
        const userId = req.user.userId;
        const existingInvite = await superAdminDb8.execute(sql13`
          SELECT id FROM teacher_invites WHERE user_id = ${userId} LIMIT 1
        `);
        if (!existingInvite.rows.length) {
          const userInfo = await superAdminDb8.execute(sql13`
            SELECT name, phone FROM users WHERE id = ${userId} LIMIT 1
          `);
          const info = userInfo.rows[0];
          const inviteId = `ti_admin_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
          await superAdminDb8.execute(sql13`
            INSERT INTO teacher_invites
              (id, swimming_pool_id, name, phone, invite_status, invited_by, user_id, requested_at, approved_at, created_at)
            VALUES
              (${inviteId}, ${row.swimming_pool_id}, ${info?.name ?? ""}, ${info?.phone ?? ""},
               'approved', ${userId}, ${userId}, now(), now(), now())
          `).catch(() => {
          });
        }
      } catch {
      }
    }
    if (!userRoles.includes(role)) return err(res, 403, "\uD574\uB2F9 \uC5ED\uD560\uC5D0 \uB300\uD55C \uAD8C\uD55C\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.");
    const newToken = signToken({ userId: req.user.userId, role, poolId: row.swimming_pool_id });
    res.json({ success: true, token: newToken, role, roles: userRoles });
  } catch (e) {
    console.error(e);
    return err(res, 500, "\uC11C\uBC84 \uC624\uB958\uAC00 \uBC1C\uC0DD\uD588\uC2B5\uB2C8\uB2E4.");
  }
});
router3.post("/reset-password", async (req, res) => {
  const { identifier, new_password } = req.body;
  if (!identifier || !new_password) return err(res, 400, "\uC544\uC774\uB514\uC640 \uC0C8 \uBE44\uBC00\uBC88\uD638\uB97C \uC785\uB825\uD574\uC8FC\uC138\uC694.");
  if (new_password.length < 4) return err(res, 400, "\uBE44\uBC00\uBC88\uD638\uB294 4\uC790 \uC774\uC0C1\uC774\uC5B4\uC57C \uD569\uB2C8\uB2E4.");
  try {
    const [user] = await superAdminDb8.select({ id: usersTable.id }).from(usersTable).where(eq(usersTable.email, identifier.trim().toLowerCase())).limit(1);
    if (user) {
      const hash = await hashPassword(new_password);
      await superAdminDb8.execute(sql13`UPDATE users SET password_hash = ${hash}, updated_at = now() WHERE id = ${user.id}`);
      res.json({ success: true, message: "\uBE44\uBC00\uBC88\uD638\uAC00 \uBCC0\uACBD\uB418\uC5C8\uC2B5\uB2C8\uB2E4." });
      return;
    }
    const [parent] = await db8.select({ id: parentAccountsTable.id }).from(parentAccountsTable).where(eq(parentAccountsTable.phone, identifier.trim())).limit(1);
    if (parent) {
      const hash = await hashPassword(new_password);
      await db8.execute(sql13`UPDATE parent_accounts SET pin_hash = ${hash}, updated_at = now() WHERE id = ${parent.id}`);
      res.json({ success: true, message: "\uBE44\uBC00\uBC88\uD638\uAC00 \uBCC0\uACBD\uB418\uC5C8\uC2B5\uB2C8\uB2E4." });
      return;
    }
    return err(res, 404, "\uD574\uB2F9 \uC544\uC774\uB514\uB85C \uB4F1\uB85D\uB41C \uACC4\uC815\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.");
  } catch (e) {
    console.error(e);
    return err(res, 500, "\uC11C\uBC84 \uC624\uB958\uAC00 \uBC1C\uC0DD\uD588\uC2B5\uB2C8\uB2E4.");
  }
});
router3.post("/change-password", requireAuth, async (req, res) => {
  const { current_password, new_password } = req.body;
  if (!current_password || !new_password) return err(res, 400, "\uD604\uC7AC \uBE44\uBC00\uBC88\uD638\uC640 \uC0C8 \uBE44\uBC00\uBC88\uD638\uB97C \uC785\uB825\uD574\uC8FC\uC138\uC694.");
  if (new_password.length < 4) return err(res, 400, "\uC0C8 \uBE44\uBC00\uBC88\uD638\uB294 4\uC790 \uC774\uC0C1\uC774\uC5B4\uC57C \uD569\uB2C8\uB2E4.");
  try {
    const [user] = await superAdminDb8.select({ id: usersTable.id, password_hash: usersTable.password_hash }).from(usersTable).where(eq(usersTable.id, req.user.userId)).limit(1);
    if (!user) return err(res, 404, "\uC0AC\uC6A9\uC790\uB97C \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.");
    const valid = await comparePassword(current_password, user.password_hash);
    if (!valid) return err(res, 400, "\uD604\uC7AC \uBE44\uBC00\uBC88\uD638\uAC00 \uC62C\uBC14\uB974\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.");
    const hash = await hashPassword(new_password);
    await superAdminDb8.execute(sql13`UPDATE users SET password_hash = ${hash}, updated_at = now() WHERE id = ${user.id}`);
    res.json({ success: true, message: "\uBE44\uBC00\uBC88\uD638\uAC00 \uBCC0\uACBD\uB418\uC5C8\uC2B5\uB2C8\uB2E4." });
  } catch (e) {
    console.error(e);
    return err(res, 500, "\uC11C\uBC84 \uC624\uB958\uAC00 \uBC1C\uC0DD\uD588\uC2B5\uB2C8\uB2E4.");
  }
});
router3.post("/teacher-self-signup", async (req, res) => {
  const { name, email, loginId, password, phone, pool_id, kakao_id, apple_id } = req.body;
  const identifier = (loginId?.trim() || email?.trim() || "").toLowerCase();
  if (!name?.trim() || !identifier || !password || !pool_id) {
    return err(res, 400, "\uC774\uB984, \uC544\uC774\uB514, \uBE44\uBC00\uBC88\uD638, \uC218\uC601\uC7A5\uC740 \uD544\uC218\uC785\uB2C8\uB2E4.");
  }
  if (password.length < 4) return err(res, 400, "\uBE44\uBC00\uBC88\uD638\uB294 4\uC790 \uC774\uC0C1\uC774\uC5B4\uC57C \uD569\uB2C8\uB2E4.");
  if (identifier.length < 4) return err(res, 400, "\uC544\uC774\uB514\uB294 4\uC790 \uC774\uC0C1\uC774\uC5B4\uC57C \uD569\uB2C8\uB2E4.");
  try {
    const [exist] = await superAdminDb8.select({ id: usersTable.id }).from(usersTable).where(eq(usersTable.email, identifier)).limit(1);
    if (exist) return err(res, 409, "\uC774\uBBF8 \uC0AC\uC6A9 \uC911\uC778 \uC544\uC774\uB514\uC785\uB2C8\uB2E4.");
    const [pool2] = await superAdminDb8.select({ id: swimmingPoolsTable.id, name: swimmingPoolsTable.name }).from(swimmingPoolsTable).where(eq(swimmingPoolsTable.id, pool_id)).limit(1);
    if (!pool2) return err(res, 404, "\uC218\uC601\uC7A5\uC744 \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.");
    const hash = await hashPassword(password);
    const userId = `u_teacher_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    const cleanedPhone = phone?.trim() || "";
    let autoApproved = false;
    let matchedInviteId = null;
    if (cleanedPhone) {
      const inviteMatch = await superAdminDb8.execute(sql13`
        SELECT id FROM teacher_invites
        WHERE swimming_pool_id = ${pool_id}
          AND phone = ${cleanedPhone}
          AND invite_status IN ('invited', 'active', 'pending')
        LIMIT 1
      `);
      if (inviteMatch.rows.length > 0) {
        autoApproved = true;
        matchedInviteId = inviteMatch.rows[0].id;
      }
    }
    await superAdminDb8.execute(sql13`
      INSERT INTO users (id, email, password_hash, name, phone, role, swimming_pool_id, is_activated, kakao_id, apple_id, created_at, updated_at)
      VALUES (${userId}, ${identifier}, ${hash}, ${name.trim()}, ${cleanedPhone || null},
              'teacher', ${pool_id}, ${autoApproved}, ${kakao_id || null}, ${apple_id || null}, now(), now())
    `);
    if (autoApproved && matchedInviteId) {
      await superAdminDb8.execute(sql13`
        UPDATE teacher_invites
        SET invite_status = 'approved', user_id = ${userId}, approved_at = now(), approved_by = ${userId}
        WHERE id = ${matchedInviteId}
      `);
    } else {
      const inviteId = `ti_self_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
      await superAdminDb8.execute(sql13`
        INSERT INTO teacher_invites (id, swimming_pool_id, name, phone, invite_status, invited_by, user_id, requested_at, created_at)
        VALUES (${inviteId}, ${pool_id}, ${name.trim()}, ${cleanedPhone},
                'joinedPendingApproval', ${userId}, ${userId}, now(), now())
      `);
    }
    const token = signToken({ userId, role: "teacher", poolId: pool_id });
    if (autoApproved) {
      res.status(201).json({
        success: true,
        message: "\uAC00\uC785\uC774 \uC644\uB8CC\uB418\uC5C8\uC2B5\uB2C8\uB2E4.",
        pool_name: pool2.name,
        status: "approved",
        auto_approved: true,
        token,
        user: { id: userId, email: identifier, name: name.trim(), phone: cleanedPhone, role: "teacher", swimming_pool_id: pool_id, is_activated: true }
      });
    } else {
      res.status(201).json({
        success: true,
        message: "\uAC00\uC785 \uC2E0\uCCAD\uC774 \uC644\uB8CC\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uAD00\uB9AC\uC790 \uC2B9\uC778 \uD6C4 \uC218\uC601\uC7A5 \uC815\uBCF4\uAC00 \uC5F0\uACB0\uB429\uB2C8\uB2E4.",
        pool_name: pool2.name,
        status: "pending_approval",
        auto_approved: false,
        token,
        user: { id: userId, email: identifier, name: name.trim(), phone: cleanedPhone, role: "teacher", swimming_pool_id: pool_id, is_activated: false }
      });
    }
  } catch (e) {
    console.error("[teacher-self-signup]", e);
    return err(res, 500, e.message || "\uC11C\uBC84 \uC624\uB958\uAC00 \uBC1C\uC0DD\uD588\uC2B5\uB2C8\uB2E4.");
  }
});
