function abbreviateAddress(address) {
  if (!address) return "";
  const parts = address.trim().split(/\s+/);
  if (parts.length === 0) return "";
  const first = parts[0];
  if (first.endsWith("\uB3C4")) {
    return parts.slice(0, Math.min(3, parts.length)).join(" ");
  }
  if (first.endsWith("\uC2DC")) {
    return parts.slice(0, Math.min(2, parts.length)).join(" ");
  }
  return parts.slice(0, Math.min(2, parts.length)).join(" ");
}
router4.get("/public-search", async (req, res) => {
  const q = (req.query.name || "").trim();
  if (!q) {
    res.json({ success: true, data: [] });
    return;
  }
  try {
    const rows = await superAdminDb10.execute(sql15`
      SELECT id, name, address
      FROM swimming_pools
      WHERE approval_status = 'approved'
        AND name ILIKE ${q + "%"}
      ORDER BY
        CASE WHEN LOWER(name) = LOWER(${q}) THEN 0 ELSE 1 END,
        LENGTH(name),
        name
      LIMIT 20
    `);
    const data = rows.rows.map((r) => ({
      id: r.id,
      name: r.name,
      address: abbreviateAddress(r.address)
    }));
    res.json({ success: true, data });
  } catch (e) {
    console.error(e);
    res.status(500).json({ success: false, data: [] });
  }
});
