async function processRetryQueue() {
  try {
    const pending = await superAdminDb11.execute(sql17`
      SELECT * FROM event_retry_queue
      WHERE resolved = false
        AND retry_count < max_retries
        AND next_retry_at <= NOW()
      ORDER BY next_retry_at ASC
      LIMIT 50
    `);
    const rows = pending.rows;
    if (rows.length === 0) return;
    for (const row of rows) {
      try {
        await writeToSuperAdmin({
          pool_id: row.pool_id,
          event_type: row.event_type,
          entity_type: row.entity_type,
          entity_id: row.entity_id,
          actor_id: row.actor_id,
          actor_name: row.actor_name,
          payload: row.payload
        }, "pool_ops_retry");
        await superAdminDb11.execute(sql17`
          UPDATE event_retry_queue SET resolved = true, updated_at = NOW() WHERE id = ${row.id}
        `);
      } catch (err15) {
        const newCount = row.retry_count + 1;
        if (newCount >= row.max_retries) {
          await moveToDeadLetter({ ...row, retry_count: newCount, last_error: String(err15).slice(0, 500) });
        } else {
          const nextRetry = new Date(Date.now() + Math.pow(2, newCount) * 60 * 1e3);
          await superAdminDb11.execute(sql17`
            UPDATE event_retry_queue
            SET retry_count   = ${newCount},
                last_error    = ${String(err15).slice(0, 500)},
                next_retry_at = ${nextRetry.toISOString()},
                updated_at    = NOW()
            WHERE id = ${row.id}
          `);
        }
      }
    }
    console.log(`[pool-event-logger] \uC7AC\uC2DC\uB3C4 \uCC98\uB9AC: ${rows.length}\uAC74`);
  } catch (err15) {
    console.error("[pool-event-logger] \uC7AC\uC2DC\uB3C4 \uD050 \uCC98\uB9AC \uC624\uB958:", err15);
  }
}
