router5.post(
  "/students/:id/withdraw",
  requireAuth,
  requireRole("super_admin", "pool_admin"),
  async (req, res) => {
    try {
      const { id: studentId } = req.params;
      const [student] = await db12.select().from(studentsTable).where(eq4(studentsTable.id, studentId)).limit(1);
      if (!student) {
        res.status(404).json({ error: "\uD559\uC0DD\uC744 \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4." });
        return;
      }
      if (req.user.role === "pool_admin") {
        const [me] = await superAdminDb13.select({ swimming_pool_id: usersTable3.swimming_pool_id }).from(usersTable3).where(eq4(usersTable3.id, req.user.userId)).limit(1);
        if (me?.swimming_pool_id !== student.swimming_pool_id) {
          res.status(403).json({ error: "\uAD8C\uD55C\uC774 \uC5C6\uC2B5\uB2C8\uB2E4." });
          return;
        }
      }
      if (student.status === "withdrawn") {
        res.status(400).json({ error: "\uC774\uBBF8 \uD0C8\uD1F4 \uCC98\uB9AC\uB41C \uD559\uC0DD\uC785\uB2C8\uB2E4." });
        return;
      }
      const photos = await db12.execute(sql20`
        SELECT id, storage_key FROM student_photos WHERE student_id = ${studentId}
      `);
      if (photos.rows.length > 0) {
        try {
          const { Client: Client7 } = await import("@replit/object-storage");
          const client = new Client7();
          await Promise.allSettled(
            photos.rows.map((p) => client.delete(p.storage_key).catch(() => {
            }))
          );
        } catch {
        }
        await db12.execute(sql20`DELETE FROM student_photos WHERE student_id = ${studentId}`);
      }
      let lastClassName = null;
      if (student.class_group_id) {
        const cgResult = await db12.execute(sql20`
          SELECT name FROM class_groups WHERE id = ${student.class_group_id} LIMIT 1
        `);
        lastClassName = cgResult.rows[0]?.name ?? null;
      }
      const withdrawEffDate = kstTodayStr();
      await db12.transaction(async (tx) => {
        const lockedRows = await tx.execute(sql20`
          SELECT id, status, class_group_id, assigned_class_ids
          FROM students WHERE id = ${studentId} LIMIT 1 FOR UPDATE
        `);
        const locked = lockedRows.rows[0];
        if (!locked) throw new Error("STUDENT_NOT_FOUND");
        await closeAllActiveClassHistory(tx, studentId, withdrawEffDate);
        await tx.execute(sql20`
          UPDATE students
          SET status = 'withdrawn', class_group_id = NULL,
              assigned_class_ids = '[]'::jsonb, schedule_labels = NULL,
              last_class_group_name = ${lastClassName}, withdrawn_at = now(), updated_at = now()
          WHERE id = ${studentId}
        `);
      });
      await db12.execute(sql20`
        DELETE FROM parent_students WHERE student_id = ${studentId}
      `);
      const classGroupId = student.class_group_id;
      if (classGroupId) {
        const remainingResult = await db12.execute(sql20`
          SELECT COUNT(*) AS cnt FROM students
          WHERE class_group_id = ${classGroupId} AND status IN ('active', 'pending_parent_link', 'unregistered')
        `);
        const remainCount = Number(remainingResult.rows[0]?.cnt || 0);
        if (remainCount === 0) {
          try {
            await db12.execute(sql20`
              UPDATE class_diaries SET is_deleted = true, deleted_at = now()
              WHERE class_group_id = ${classGroupId} AND is_deleted = false
            `);
          } catch {
          }
        }
      }
      res.json({ success: true, message: `${student.name} \uD559\uC0DD\uC774 \uD0C8\uD1F4 \uCC98\uB9AC\uB418\uC5C8\uC2B5\uB2C8\uB2E4.` });
    } catch (e) {
      if (e?.message === "STUDENT_NOT_FOUND") {
        res.status(404).json({ error: "\uD559\uC0DD\uC744 \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4." });
        return;
      }
      console.error(e);
      res.status(500).json({ error: "\uC11C\uBC84 \uC624\uB958\uAC00 \uBC1C\uC0DD\uD588\uC2B5\uB2C8\uB2E4." });
    }
  }
);
