router5.get("/student-requests/:id/pool-students", requireAuth, requireRole("super_admin", "pool_admin"), async (req, res) => {
  try {
    const [srr] = await superAdminDb13.select().from(studentRegistrationRequestsTable2).where(eq4(studentRegistrationRequestsTable2.id, req.params.id)).limit(1);
    if (!srr) {
      res.status(404).json({ error: "\uC694\uCCAD\uC744 \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4." });
      return;
    }
    const [pa] = await db12.select({ phone: parentAccountsTable3.phone }).from(parentAccountsTable3).where(eq4(parentAccountsTable3.id, srr.parent_id)).limit(1);
    const parentPhone = pa?.phone || null;
    const poolStudents = await db12.select({
      id: studentsTable.id,
      name: studentsTable.name,
      birth_date: studentsTable.birth_date,
      phone: studentsTable.phone,
      class_group_id: studentsTable.class_group_id
    }).from(studentsTable).where(eq4(studentsTable.swimming_pool_id, srr.swimming_pool_id));
    const alreadyLinked = await db12.select({ student_id: parentStudentsTable.student_id }).from(parentStudentsTable).where(eq4(parentStudentsTable.parent_id, srr.parent_id));
    const linkedIds = new Set(alreadyLinked.map((l) => l.student_id));
    const normalizePhone3 = (p) => (p || "").replace(/\D/g, "");
    const parentPhoneNorm = normalizePhone3(parentPhone);
    const result = poolStudents.map((s) => ({
      ...s,
      already_linked: linkedIds.has(s.id),
      phone_match: parentPhoneNorm.length > 0 && normalizePhone3(s.phone) === parentPhoneNorm
    })).sort((a, b) => {
      if (a.phone_match && !b.phone_match) return -1;
      if (!a.phone_match && b.phone_match) return 1;
      return a.name.localeCompare(b.name, "ko");
    });
    res.json({ parent_phone: parentPhone, students: result });
  } catch (err15) {
    res.status(500).json({ error: "\uC11C\uBC84 \uC624\uB958\uAC00 \uBC1C\uC0DD\uD588\uC2B5\uB2C8\uB2E4." });
  }
});
