router5.get("/storage", requireAuth, requireRole("super_admin", "pool_admin"), async (req, res) => {
  try {
    let storageLabel2 = function(mb) {
      if (mb >= 1024) return `${Math.round(mb / 1024)}GB`;
      return `${Math.round(mb / 100) * 100 || Math.round(mb / 10) * 10 || mb}MB`;
    };
    var storageLabel = storageLabel2;
    const [meRow] = await superAdminDb13.select({ swimming_pool_id: usersTable3.swimming_pool_id }).from(usersTable3).where(eq4(usersTable3.id, req.user.userId)).limit(1);
    const poolId = meRow?.swimming_pool_id ?? null;
    if (!poolId) {
      res.status(403).json({ error: "\uC18C\uC18D\uB41C \uC218\uC601\uC7A5\uC774 \uC5C6\uC2B5\uB2C8\uB2E4." });
      return;
    }
    const [poolRow] = (await superAdminDb13.execute(sql20`
      SELECT COALESCE(sp.subscription_tier, 'free') AS tier,
             plans.storage_mb                        AS plan_storage_mb,
             COALESCE(sp.extra_storage_gb, 0)        AS extra_storage_gb
      FROM swimming_pools sp
      LEFT JOIN subscription_plans plans
             ON plans.tier = COALESCE(sp.subscription_tier, 'free')
      WHERE sp.id = ${poolId} LIMIT 1
    `)).rows;
    const activeTier = poolRow?.tier ?? "free";
    const planMb = Number(poolRow?.plan_storage_mb ?? 102);
    const extraMb = Number(poolRow?.extra_storage_gb ?? 0) * 1024;
    const totalMb = planMb + extraMb;
    const quotaBytes = totalMb * 1024 * 1024;
    const displayStorage = storageLabel2(totalMb);
    let photoBytes = 0;
    let videoBytes = 0;
    try {
      const [rp] = (await db12.execute(sql20`
        SELECT COALESCE(SUM(file_size), 0) AS used FROM photo_assets_meta WHERE pool_id = ${poolId}
      `)).rows;
      photoBytes = Number(rp?.used ?? 0);
    } catch {
    }
    try {
      const [rv] = (await db12.execute(sql20`
        SELECT COALESCE(SUM(file_size), 0) AS used FROM video_assets_meta WHERE pool_id = ${poolId}
      `)).rows;
      videoBytes = Number(rv?.used ?? 0);
    } catch {
    }
    const totalBytes = photoBytes + videoBytes;
    let staff = [];
    try {
      const staffRows = (await db12.execute(sql20`
        SELECT u.id, u.name, u.role,
               COALESCE(p.photo_bytes, 0) AS photo_bytes,
               COALESCE(v.video_bytes, 0) AS video_bytes
        FROM users u
        LEFT JOIN (
          SELECT uploaded_by, SUM(file_size) AS photo_bytes
          FROM photo_assets_meta WHERE pool_id = ${poolId}
          GROUP BY uploaded_by
        ) p ON p.uploaded_by = u.id
        LEFT JOIN (
          SELECT uploaded_by, SUM(file_size) AS video_bytes
          FROM video_assets_meta WHERE pool_id = ${poolId}
          GROUP BY uploaded_by
        ) v ON v.uploaded_by = u.id
        WHERE u.swimming_pool_id = ${poolId}
          AND u.role IN ('pool_admin', 'teacher')
        ORDER BY (COALESCE(p.photo_bytes, 0) + COALESCE(v.video_bytes, 0)) DESC
      `)).rows;
      staff = staffRows.map((r) => ({
        id: r.id,
        name: r.name,
        role: r.role,
        photo_bytes: Number(r.photo_bytes ?? 0),
        video_bytes: Number(r.video_bytes ?? 0),
        messenger_bytes: 0,
        diary_bytes: 0,
        notice_bytes: 0,
        system_bytes: 0,
        total_bytes: Number(r.photo_bytes ?? 0) + Number(r.video_bytes ?? 0)
      }));
    } catch {
    }
    res.json({
      total_bytes: totalBytes,
      quota_bytes: quotaBytes,
      display_storage: displayStorage,
      photo_bytes: photoBytes,
      video_bytes: videoBytes,
      messenger_bytes: 0,
      diary_bytes: 0,
      notice_bytes: 0,
      system_bytes: 0,
      tier: activeTier,
      staff
    });
  } catch (err15) {
    console.error("[admin/storage]", err15);
    res.status(500).json({ error: "\uC11C\uBC84 \uC624\uB958\uAC00 \uBC1C\uC0DD\uD588\uC2B5\uB2C8\uB2E4." });
  }
});
