async function getAdminPoolId(req) {
  if (req.user.role === "pool_admin") {
    if (req.user.poolId) return req.user.poolId;
    const [u] = await superAdminDb13.select({ swimming_pool_id: usersTable3.swimming_pool_id }).from(usersTable3).where(eq4(usersTable3.id, req.user.userId)).limit(1);
    return u?.swimming_pool_id ?? null;
  }
  if (req.user.role === "teacher" && req.user.poolId) {
    return req.user.poolId;
  }
  return req.query.pool_id ?? null;
}
