router5.patch(
  "/students/:id/status",
  requireAuth,
  requireRole("super_admin", "pool_admin"),
  async (req, res) => {
    try {
      const { status, reason } = req.body;
      const allowedStatus = ["active", "inactive", "withdrawn", "suspended", "pending", "archived"];
      if (!allowedStatus.includes(status)) {
        return res.status(400).json({ error: "\uC720\uD6A8\uD558\uC9C0 \uC54A\uC740 \uC0C1\uD0DC\uAC12\uC785\uB2C8\uB2E4." });
      }
      const poolId = await getAdminPoolId(req);
      if (!poolId) {
        return res.status(403).json({ error: "\uC218\uC601\uC7A5 \uC815\uBCF4\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4." });
      }
      const [student] = (await db12.execute(sql20`SELECT id, name, status FROM students WHERE id = ${req.params.id} AND swimming_pool_id = ${poolId}`)).rows;
      if (!student) {
        return res.status(404).json({ error: "\uD68C\uC6D0\uC744 \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4." });
      }
      const [actor] = (await superAdminDb13.execute(sql20`SELECT name FROM users WHERE id = ${req.user.userId}`)).rows;
      const actorName = actor?.name || req.user.userId;
      const isClassDepartureStatus = status === "suspended" || status === "withdrawn" || status === "archived";
      if (isClassDepartureStatus) {
        const effDate = kstTodayStr();
        await db12.transaction(async (tx) => {
          const lockedRows = await tx.execute(sql20`
            SELECT id, status, class_group_id, assigned_class_ids
            FROM students WHERE id = ${req.params.id} LIMIT 1 FOR UPDATE
          `);
          const locked = lockedRows.rows[0];
          if (!locked) throw new Error("STUDENT_NOT_FOUND");
          await closeAllActiveClassHistory(tx, req.params.id, effDate);
          if (status === "withdrawn") {
            await tx.execute(sql20`UPDATE students SET status = ${status}, archived_reason = ${reason ?? null}, class_group_id = NULL, assigned_class_ids = '[]'::jsonb, schedule_labels = NULL, withdrawn_at = NOW(), updated_at = NOW() WHERE id = ${req.params.id}`);
          } else if (status === "archived") {
            await tx.execute(sql20`UPDATE students SET status = 'archived', archived_reason = COALESCE(${reason ?? null}, 'archived'), class_group_id = NULL, assigned_class_ids = '[]'::jsonb, schedule_labels = NULL, updated_at = NOW() WHERE id = ${req.params.id}`);
          } else {
            await tx.execute(sql20`UPDATE students SET status = ${status}, archived_reason = ${reason ?? null}, class_group_id = NULL, assigned_class_ids = '[]'::jsonb, schedule_labels = NULL, updated_at = NOW() WHERE id = ${req.params.id}`);
          }
        });
      } else {
        await db12.execute(sql20`UPDATE students SET status = ${status}, archived_reason = ${reason ?? null}, updated_at = NOW() WHERE id = ${req.params.id}`);
      }
      await writeActivityLog({
        poolId,
        studentId: req.params.id,
        targetName: student.name,
        actionType: "update",
        targetType: "status",
        beforeValue: student.status,
        afterValue: status,
        actorId: req.user.userId,
        actorName,
        actorRole: req.user.role,
        note: reason
      });
      res.json({ success: true });
    } catch (e) {
      if (e?.message === "STUDENT_NOT_FOUND") return res.status(404).json({ error: "\uD559\uC0DD\uC744 \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4." });
      console.error(e);
      res.status(500).json({ error: "\uC11C\uBC84 \uC624\uB958" });
    }
  }
);
