router5.patch(
  "/students/:id/info",
  requireAuth,
  requireRole("super_admin", "pool_admin"),
  async (req, res) => {
    try {
      const poolId = await getAdminPoolId(req);
      if (!poolId) {
        return res.status(403).json({ error: "\uC218\uC601\uC7A5 \uC815\uBCF4\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4." });
      }
      const { name, birth_year, parent_name, parent_phone, parent_phone2, parent_phone3, parent_phone4, memo, notes } = req.body;
      const [student] = (await db12.execute(sql20`SELECT * FROM students WHERE id = ${req.params.id} AND swimming_pool_id = ${poolId}`)).rows;
      if (!student) {
        return res.status(404).json({ error: "\uD68C\uC6D0\uC744 \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4." });
      }
      const [actor] = (await superAdminDb13.execute(sql20`SELECT name FROM users WHERE id = ${req.user.userId}`)).rows;
      const actorName = actor?.name || req.user.userId;
      const changes = [];
      if (name && name !== student.name) changes.push(`\uC774\uB984: ${student.name}\u2192${name}`);
      if (birth_year && String(birth_year) !== String(student.birth_year)) changes.push(`\uCD9C\uC0DD\uB144: ${student.birth_year}\u2192${birth_year}`);
      if (parent_name && parent_name !== student.parent_name) changes.push(`\uBCF4\uD638\uC790: ${student.parent_name}\u2192${parent_name}`);
      if (parent_phone !== void 0 && parent_phone !== student.parent_phone) changes.push(`\uBCF4\uD638\uC790\uC5F0\uB77D\uCC98 \uBCC0\uACBD`);
      if (parent_phone2 !== void 0 && parent_phone2 !== student.parent_phone2) changes.push(`\uBCF4\uD638\uC790\uC5F0\uB77D\uCC982 \uBCC0\uACBD`);
      if (parent_phone3 !== void 0 && parent_phone3 !== student.parent_phone3) changes.push(`\uBCF4\uD638\uC790\uC5F0\uB77D\uCC983 \uBCC0\uACBD`);
      if (parent_phone4 !== void 0 && parent_phone4 !== student.parent_phone4) changes.push(`\uBCF4\uD638\uC790\uC5F0\uB77D\uCC984 \uBCC0\uACBD`);
      const normParentPhone = parent_phone != null ? String(parent_phone).replace(/[^0-9]/g, "") || null : null;
      const phone2Provided = "parent_phone2" in req.body;
      const phone3Provided = "parent_phone3" in req.body;
      const phone4Provided = "parent_phone4" in req.body;
      const normParentPhone2 = phone2Provided ? parent_phone2 ? String(parent_phone2).replace(/[^0-9]/g, "") || null : null : void 0;
      const normParentPhone3 = phone3Provided ? parent_phone3 ? String(parent_phone3).replace(/[^0-9]/g, "") || null : null : void 0;
      const normParentPhone4 = phone4Provided ? parent_phone4 ? String(parent_phone4).replace(/[^0-9]/g, "") || null : null : void 0;
      let newParentUserId = student.parent_user_id || null;
      let parentAccountName = null;
      if (!newParentUserId) {
        for (const tryPhone of [normParentPhone, normParentPhone2, normParentPhone3, normParentPhone4]) {
          if (newParentUserId || !tryPhone) continue;
          const [matched] = (await db12.execute(sql20`
            SELECT pa.id, pa.name FROM parent_accounts pa
            WHERE REGEXP_REPLACE(COALESCE(pa.phone,''),'[^0-9]','','g') = ${tryPhone}
              AND (pa.swimming_pool_id = ${poolId} OR pa.swimming_pool_id IS NULL)
            ORDER BY (pa.swimming_pool_id = ${poolId}) DESC NULLS LAST
            LIMIT 1
          `)).rows;
          if (matched) {
            newParentUserId = matched.id;
            parentAccountName = matched.name;
            changes.push(`\uD559\uBD80\uBAA8 \uC571 \uC790\uB3D9 \uC5F0\uACB0: ${matched.name}`);
          }
        }
      }
      await db12.execute(sql20`
        UPDATE students SET
          name = COALESCE(${name ?? null}, name),
          birth_year = COALESCE(${birth_year ?? null}, birth_year),
          parent_name = COALESCE(${parent_name ?? null}, parent_name),
          parent_phone = COALESCE(${normParentPhone}, parent_phone),
          parent_phone2 = CASE WHEN ${phone2Provided} THEN ${normParentPhone2 ?? null} ELSE parent_phone2 END,
          parent_phone3 = CASE WHEN ${phone3Provided} THEN ${normParentPhone3 ?? null} ELSE parent_phone3 END,
          parent_phone4 = CASE WHEN ${phone4Provided} THEN ${normParentPhone4 ?? null} ELSE parent_phone4 END,
          memo = COALESCE(${memo ?? null}, memo),
          notes = COALESCE(${notes ?? null}, notes),
          updated_at = NOW()
        WHERE id = ${req.params.id}
      `);
      if (newParentUserId && !student.parent_user_id) {
        await db12.execute(sql20`
          UPDATE students SET parent_user_id = ${newParentUserId} WHERE id = ${req.params.id}
        `);
      }
      if (newParentUserId && !student.parent_user_id) {
        const psId = `ps_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
        await db12.execute(sql20`
          INSERT INTO parent_students (id, parent_id, student_id, swimming_pool_id, status, approved_at)
          VALUES (${psId}, ${newParentUserId}, ${req.params.id}, ${poolId}, 'approved', NOW())
          ON CONFLICT DO NOTHING
        `);
      }
      if (changes.length > 0) {
        await writeActivityLog({
          poolId,
          studentId: req.params.id,
          targetName: student.name,
          actionType: "update",
          targetType: "info",
          afterValue: changes.join(", "),
          actorId: req.user.userId,
          actorName,
          actorRole: req.user.role
        });
      }
      const changedV2Fields = [];
      if (name && name !== student.name) changedV2Fields.push("name");
      if (parent_phone !== void 0 && parent_phone !== student.parent_phone) changedV2Fields.push("parent_phone");
      if (parent_phone2 !== void 0 && parent_phone2 !== student.parent_phone2) changedV2Fields.push("parent_phone2");
      if (parent_phone3 !== void 0 && parent_phone3 !== student.parent_phone3) changedV2Fields.push("parent_phone3");
      if (parent_phone4 !== void 0 && parent_phone4 !== student.parent_phone4) changedV2Fields.push("parent_phone4");
      if (changedV2Fields.length > 0) {
        triggerAutoLinkOnStudentV2(req.params.id, changedV2Fields).catch(
          (e) => console.error("[v2-admin-trigger] info patch \uD2B8\uB9AC\uAC70 \uC624\uB958:", e?.message)
        );
      }
      res.json({ success: true, parent_user_id: newParentUserId, parent_account_name: parentAccountName });
    } catch (err15) {
      console.error(err15);
      res.status(500).json({ error: "\uC11C\uBC84 \uC624\uB958" });
    }
  }
);
router5.get(
  "/students/:id/detail",
  requireAuth,
  requireRole("super_admin", "pool_admin"),
  async (req, res) => {
    try {
      const poolId = await getAdminPoolId(req);
      if (!poolId) {
        return res.status(403).json({ error: "\uC218\uC601\uC7A5 \uC815\uBCF4\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4." });
      }
      const [student] = (await superAdminDb13.execute(sql20`
        SELECT s.*,
          (SELECT cg.name FROM class_groups cg WHERE cg.id = s.class_group_id LIMIT 1) AS class_name,
          (SELECT u.name FROM users u WHERE u.id = cg.teacher_user_id LIMIT 1) AS teacher_name,
          (SELECT pa.name FROM parent_students ps JOIN parent_accounts pa ON pa.id = ps.parent_id
           WHERE ps.student_id = s.id AND ps.status = 'approved' LIMIT 1) AS parent_account_name,
          (SELECT ps.status FROM parent_students ps WHERE ps.student_id = s.id ORDER BY ps.created_at DESC LIMIT 1) AS parent_link_status
        FROM students s
        LEFT JOIN class_groups cg ON cg.id = s.class_group_id
        WHERE s.id = ${req.params.id} AND s.swimming_pool_id = ${poolId}
      `)).rows;
      if (!student) {
        return res.status(404).json({ error: "\uD68C\uC6D0\uC744 \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4." });
      }
      const attendance = (await db12.execute(sql20`
        SELECT date, status, class_group_id FROM attendance
        WHERE student_id = ${req.params.id}
        ORDER BY date DESC LIMIT 30
      `)).rows;
      const diaries = student.class_group_id ? (await db12.execute(sql20`
        SELECT cd.id, cd.lesson_date, cd.common_content, cd.teacher_name, cd.is_edited,
               csn.note_content AS student_note
        FROM class_diaries cd
        LEFT JOIN class_diary_student_notes csn ON csn.diary_id = cd.id AND csn.student_id = ${req.params.id} AND csn.is_deleted = false
        WHERE cd.class_group_id = ${student.class_group_id} AND cd.is_deleted = false
        ORDER BY cd.lesson_date DESC LIMIT 10
      `)).rows : [];
      const parentLinks = (await db12.execute(sql20`
        SELECT pa.id, pa.name, pa.phone, ps.status AS link_status
        FROM parent_students ps
        JOIN parent_accounts pa ON pa.id = ps.parent_id
        WHERE ps.student_id = ${req.params.id}
      `)).rows;
      res.json({ ...student, recent_attendance: attendance, recent_diaries: diaries, parents: parentLinks });
    } catch (err15) {
      console.error(err15);
      res.status(500).json({ error: "\uC11C\uBC84 \uC624\uB958" });
    }
  }
);
router5.get(
  "/makeups",
  requireAuth,
  requireRole("super_admin", "pool_admin", "teacher"),
  async (req, res) => {
    try {
      const poolId = await getAdminPoolId(req);
      if (!poolId) {
        res.status(403).json({ error: "\uC218\uC601\uC7A5 \uC5C6\uC74C" });
        return;
      }
      await db12.execute(sql20.raw(`
        UPDATE makeup_sessions
        SET status = 'expired'
        WHERE swimming_pool_id = '${poolId}'
          AND status = 'waiting'
          AND expire_at IS NOT NULL
          AND expire_at < NOW()
      `));
      const { status, student_id, teacher_id, assigned_teacher_id, class_group_id } = req.query;
      const conditions = [`swimming_pool_id = '${poolId}'`];
      if (status) {
        if (status === "waiting") {
          conditions.push(`status IN ('waiting', 'expired')`);
        } else {
          conditions.push(`status = '${status}'`);
        }
      }
      if (student_id) conditions.push(`student_id = '${student_id}'`);
      if (teacher_id) conditions.push(`original_teacher_id = '${teacher_id}'`);
      if (assigned_teacher_id) conditions.push(`(assigned_teacher_id = '${assigned_teacher_id}' OR transferred_to_teacher_id = '${assigned_teacher_id}')`);
      if (class_group_id) conditions.push(`assigned_class_group_id = '${class_group_id}'`);
      const callerId = req.user?.userId;
      const callerRole = req.user?.role;
      if (callerRole !== "super_admin" && callerId && !teacher_id) {
        const myClasses = (await db12.execute(sql20.raw(`
          SELECT id FROM class_groups
          WHERE (teacher_user_id = '${callerId}'
             OR co_teacher_ids @> to_jsonb('${callerId}'::text))
          LIMIT 1
        `))).rows;
        if (myClasses.length > 0) {
          conditions.push(`(
            original_teacher_id = '${callerId}'
            OR original_class_group_id IN (
              SELECT id FROM class_groups
              WHERE teacher_user_id = '${callerId}'
                 OR co_teacher_ids @> to_jsonb('${callerId}'::text)
            )
          )`);
        }
      }
      const rows = (await db12.execute(sql20.raw(`
        SELECT * FROM makeup_sessions
        WHERE ${conditions.join(" AND ")}
        ORDER BY created_at DESC
      `))).rows;
      const nowKst = new Date(Date.now() + 9 * 3600 * 1e3);
      const result = rows.map((r) => ({
        ...r,
        is_expired: r.status === "expired" || r.expire_at != null && new Date(r.expire_at) < nowKst
      }));
      res.json(result);
    } catch (err15) {
      console.error(err15);
      res.status(500).json({ error: "\uC11C\uBC84 \uC624\uB958" });
    }
  }
);
router5.get(
  "/makeups/eligible-classes",
  requireAuth,
  requireRole("super_admin", "pool_admin", "teacher"),
  async (req, res) => {
    try {
      const poolId = await getAdminPoolId(req);
      if (!poolId) {
        res.status(403).json({ error: "\uC218\uC601\uC7A5 \uC5C6\uC74C" });
        return;
      }
      const { teacher_id } = req.query;
      const whereClause = teacher_id ? `WHERE cg.swimming_pool_id = '${poolId}' AND cg.is_deleted = false AND cg.teacher_user_id = '${teacher_id}'` : `WHERE cg.swimming_pool_id = '${poolId}' AND cg.is_deleted = false`;
      const rows = (await db12.execute(sql20.raw(`
        SELECT
          cg.id, cg.name, cg.schedule_days, cg.schedule_time,
          cg.capacity, cg.instructor, cg.teacher_user_id,
          COUNT(s.id)::int AS current_members
        FROM class_groups cg
        LEFT JOIN students s ON s.class_group_id = cg.id AND s.status NOT IN ('withdrawn','deleted')
        ${whereClause}
        GROUP BY cg.id
        ORDER BY cg.schedule_days, cg.schedule_time
      `))).rows;
      const eligible = rows.map((r) => ({
        ...r,
        available_slots: r.capacity ? Math.max(0, r.capacity - r.current_members) : 999,
        is_eligible: r.capacity ? r.current_members < r.capacity : true
      }));
      res.json(eligible);
    } catch (err15) {
      console.error(err15);
      res.status(500).json({ error: "\uC11C\uBC84 \uC624\uB958" });
    }
  }
);
