router5.patch(
  "/makeups/:id/assign",
  requireAuth,
  requireRole("super_admin", "pool_admin", "teacher"),
  async (req, res) => {
    try {
      const poolId = await getAdminPoolId(req);
      if (!poolId) {
        res.status(403).json({ error: "\uC218\uC601\uC7A5 \uC5C6\uC74C" });
        return;
      }
      const { class_group_id, assigned_date } = req.body;
      if (!class_group_id) {
        res.status(400).json({ error: "class_group_id \uD544\uC694" });
        return;
      }
      if (assigned_date) {
        if (!isValidCalendarDate(assigned_date)) {
          res.status(400).json({ error: "INVALID_ASSIGNED_DATE", message: "\uB0A0\uC9DC \uD615\uC2DD\uC774 \uC62C\uBC14\uB974\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. (YYYY-MM-DD)" });
          return;
        }
        try {
          validateMakeupDateRange(assigned_date, kstTodayStr());
        } catch (e) {
          res.status(e.status ?? 400).json({ error: e.code, message: e.message });
          return;
        }
      }
      const [cg] = await db12.select().from(classGroupsTable).where(eq4(classGroupsTable.id, class_group_id)).limit(1);
      if (!cg) {
        res.status(404).json({ error: "\uBC18 \uC5C6\uC74C" });
        return;
      }
      const actor = req.user;
      const { allow_expired } = req.body;
      const mkCheckRows = (await db12.execute(sql20`
        SELECT status FROM makeup_sessions WHERE id = ${req.params.id} AND swimming_pool_id = ${poolId} LIMIT 1
      `)).rows;
      if (!mkCheckRows.length) {
        res.status(404).json({ error: "\uBCF4\uAC15 \uC5C6\uC74C" });
        return;
      }
      if (mkCheckRows[0].status === "expired" && !allow_expired) {
        res.status(409).json({
          code: "MAKEUP_EXPIRED_CONFIRM_REQUIRED",
          error: "MAKEUP_EXPIRED_CONFIRM_REQUIRED",
          message: "\uBCF4\uAC15 \uAC00\uB2A5 \uAE30\uAC04\uC774 \uC9C0\uB09C \uD56D\uBAA9\uC785\uB2C8\uB2E4. \uADF8\uB798\uB3C4 \uCC98\uB9AC\uD558\uB824\uBA74 allow_expired: true \uB97C \uD3EC\uD568\uD558\uC5EC \uB2E4\uC2DC \uC694\uCCAD\uD558\uC138\uC694."
        });
        return;
      }
      const assignResult = (await db12.execute(sql20.raw(`
        UPDATE makeup_sessions SET
          status = 'assigned',
          assigned_class_group_id = '${class_group_id}',
          assigned_class_group_name = ${cg.name ? `'${cg.name.replace(/'/g, "''")}'` : "NULL"},
          assigned_teacher_id = ${cg.teacher_user_id ? `'${cg.teacher_user_id}'` : "NULL"},
          assigned_teacher_name = ${cg.instructor ? `'${cg.instructor.replace(/'/g, "''")}'` : "NULL"},
          assigned_date = ${assigned_date ? `'${assigned_date}'` : "NULL"},
          updated_at = now()
        WHERE id = '${req.params.id}' AND swimming_pool_id = '${poolId}'
          AND status IN ('waiting', 'expired')
        RETURNING id
      `))).rows;
      if (assignResult.length === 0) {
        const latestRows = (await db12.execute(sql20`
          SELECT * FROM makeup_sessions WHERE id = ${req.params.id} LIMIT 1
        `)).rows;
        res.status(409).json({
          code: "MAKEUP_CONFLICT",
          message: "\uC774\uBBF8 \uCC98\uB9AC\uB41C \uBCF4\uAC15 \uAC74\uC785\uB2C8\uB2E4.",
          latest_state: latestRows[0] || null
        });
        return;
      }
      await writeActivityLog({
        poolId,
        studentId: null,
        targetName: req.params.id,
        actionType: "makeup_assigned",
        targetType: "makeup",
        beforeValue: "waiting",
        afterValue: "assigned",
        actorId: actor.userId,
        actorName: actor.name || "\uAD00\uB9AC\uC790",
        actorRole: actor.role,
        note: `\uBCF4\uAC15\uBC18 \uBC30\uC815: ${cg.name}`
      });
      const mkRow = await db12.execute(sql20`SELECT student_name, assigned_date FROM makeup_sessions WHERE id = ${req.params.id}`);
      const mk = mkRow.rows[0];
      if (mk) {
        const dateStr = mk.assigned_date ? ` (${mk.assigned_date})` : "";
        await createSystemMessage({
          poolId,
          msgType: "system_makeup",
          content: `${mk.student_name} \uD68C\uC6D0 \uBCF4\uAC15 \uC218\uC5C5\uC774 ${cg.name}\uBC18\uC5D0 \uBC30\uC815\uB418\uC5C8\uC2B5\uB2C8\uB2E4${dateStr}.`
        });
      }
      logPoolEvent({ pool_id: poolId, event_type: "makeup_assign", entity_type: "makeup_session", entity_id: req.params.id, actor_id: actor.userId, payload: { class_group_id, class_name: cg.name, assigned_date } }).catch(console.error);
      res.json({ success: true });
    } catch (err15) {
      console.error(err15);
      res.status(500).json({ error: "\uC11C\uBC84 \uC624\uB958" });
    }
  }
);
