router5.patch(
  "/makeups/:id/complete",
  requireAuth,
  requireRole("super_admin", "pool_admin", "teacher"),
  async (req, res) => {
    try {
      const poolId = await getAdminPoolId(req);
      if (!poolId) {
        res.status(403).json({ error: "\uC218\uC601\uC7A5 \uC5C6\uC74C" });
        return;
      }
      const { substitute_teacher_id, substitute_teacher_name, note } = req.body;
      const actor = req.user;
      const rows = (await db12.execute(sql20`SELECT * FROM makeup_sessions WHERE id = ${req.params.id} AND swimming_pool_id = ${poolId} LIMIT 1`)).rows;
      const mk = rows[0];
      if (!mk) {
        res.status(404).json({ error: "\uBCF4\uAC15 \uC5C6\uC74C" });
        return;
      }
      const isSubstitute = substitute_teacher_id && substitute_teacher_id !== mk.original_teacher_id;
      const completeResult = (await db12.execute(sql20`
        UPDATE makeup_sessions SET
          status = 'completed',
          is_substitute = ${isSubstitute || false},
          substitute_teacher_id = ${substitute_teacher_id || null},
          substitute_teacher_name = ${substitute_teacher_name || null},
          completed_at = now(),
          note = ${note || null},
          updated_at = now()
        WHERE id = ${req.params.id} AND swimming_pool_id = ${poolId}
          AND status = 'assigned'
        RETURNING id
      `)).rows;
      if (completeResult.length === 0) {
        const latestRows = (await db12.execute(sql20`
          SELECT * FROM makeup_sessions WHERE id = ${req.params.id} LIMIT 1
        `)).rows;
        res.status(409).json({
          code: "MAKEUP_CONFLICT",
          message: "\uBCF4\uAC15 \uC0C1\uD0DC\uAC00 \uBCC0\uACBD\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uC774\uBBF8 \uC644\uB8CC \uCC98\uB9AC\uB418\uC5C8\uAC70\uB098 \uB2E4\uB978 \uC0C1\uD0DC\uC785\uB2C8\uB2E4.",
          latest_state: latestRows[0] || null
        });
        return;
      }
      const completedNote = isSubstitute ? `\uB300\uB9AC\uBCF4\uAC15 \uC644\uB8CC: ${substitute_teacher_name} \uC120\uC0DD\uB2D8 (\uC6D0\uB2F4\uB2F9: ${mk.original_teacher_name})` : `\uBCF4\uAC15 \uC644\uB8CC`;
      await writeActivityLog({
        poolId,
        studentId: mk.student_id,
        targetName: mk.student_name || req.params.id,
        actionType: "makeup_completed",
        targetType: "makeup",
        beforeValue: "assigned",
        afterValue: "completed",
        actorId: actor.userId,
        actorName: actor.name || "\uAD00\uB9AC\uC790",
        actorRole: actor.role,
        note: completedNote
      });
      logPoolEvent({ pool_id: poolId, event_type: "makeup_complete", entity_type: "makeup_session", entity_id: req.params.id, actor_id: actor.userId, payload: { student_id: mk.student_id, student_name: mk.student_name } }).catch(console.error);
      res.json({ success: true });
    } catch (err15) {
      console.error(err15);
      res.status(500).json({ error: "\uC11C\uBC84 \uC624\uB958" });
    }
  }
);
