router5.get(
  "/parents",
  requireAuth,
  requireRole("super_admin", "pool_admin"),
  async (req, res) => {
    try {
      const poolId = await getAdminPoolId(req);
      if (!poolId) {
        res.status(403).json({ error: "\uC218\uC601\uC7A5 \uC5C6\uC74C" });
        return;
      }
      const appRows = (await db12.execute(sql20`
        SELECT
          pa.id,
          pa.name,
          pa.phone,
          pa.login_id,
          pa.created_at,
          'app' AS source,
          COALESCE(json_agg(json_build_object(
            'id', s.id, 'name', s.name
          )) FILTER (WHERE s.id IS NOT NULL), '[]') AS students
        FROM parent_accounts pa
        LEFT JOIN parent_students ps ON ps.parent_id = pa.id
        LEFT JOIN students s ON s.id = ps.student_id
        WHERE (
          pa.swimming_pool_id = ${poolId}
          OR (
            pa.swimming_pool_id IS NULL
            AND REGEXP_REPLACE(COALESCE(pa.phone,''),'[^0-9]','','g') IN (
              SELECT REGEXP_REPLACE(COALESCE(st.parent_phone,''),'[^0-9]','','g')
              FROM students st
              WHERE st.swimming_pool_id = ${poolId}
                AND st.parent_phone IS NOT NULL AND st.parent_phone != ''
                AND st.status NOT IN ('withdrawn','archived','deleted')
            )
          )
        )
        GROUP BY pa.id
        ORDER BY pa.created_at DESC
      `)).rows;
      await db12.execute(sql20`
        UPDATE parent_accounts pa
        SET swimming_pool_id = ${poolId}, updated_at = now()
        WHERE pa.swimming_pool_id IS NULL
          AND REGEXP_REPLACE(COALESCE(pa.phone,''),'[^0-9]','','g') IN (
            SELECT REGEXP_REPLACE(COALESCE(st.parent_phone,''),'[^0-9]','','g')
            FROM students st
            WHERE st.swimming_pool_id = ${poolId}
              AND st.parent_phone IS NOT NULL AND st.parent_phone != ''
              AND st.status NOT IN ('withdrawn','archived','deleted')
          )
      `);
      const guardianRows = (await db12.execute(sql20`
        SELECT
          COALESCE(st.parent_phone, 'nophone_' || st.id::text) AS id,
          MAX(st.parent_name) AS name,
          MAX(st.parent_phone) AS phone,
          NULL::text AS login_id,
          MIN(st.created_at) AS created_at,
          'guardian' AS source,
          json_agg(json_build_object('id', st.id, 'name', st.name)) AS students
        FROM students st
        WHERE st.swimming_pool_id = ${poolId}
          AND st.status NOT IN ('withdrawn', 'archived', 'deleted')
          AND (
            (st.parent_name IS NOT NULL AND st.parent_name != '')
            OR (st.parent_phone IS NOT NULL AND st.parent_phone != '')
          )
        GROUP BY COALESCE(st.parent_phone, 'nophone_' || st.id::text)
        ORDER BY MIN(st.created_at) DESC
      `)).rows;
      const appPhones = new Set(appRows.map((r) => (r.phone || "").replace(/[^0-9]/g, "")).filter(Boolean));
      const filteredGuardians = guardianRows.filter((r) => {
        const norm = (r.phone || "").replace(/[^0-9]/g, "");
        return !norm || !appPhones.has(norm);
      });
      const result = [
        ...appRows.map((r) => ({ ...r, linked: true })),
        ...filteredGuardians.map((r) => ({ ...r, linked: false }))
      ];
      res.json(result);
    } catch (err15) {
      console.error(err15);
      res.status(500).json({ error: "\uC11C\uBC84 \uC624\uB958" });
    }
  }
);
router5.post(
  "/auto-link-parents",
  requireAuth,
  requireRole("super_admin", "pool_admin"),
  async (req, res) => {
    try {
      const poolId = await getAdminPoolId(req);
      if (!poolId) {
        res.status(403).json({ error: "\uC218\uC601\uC7A5 \uC5C6\uC74C" });
        return;
      }
      const unlinked = (await db12.execute(sql20`
        SELECT id, name, parent_phone, parent_name
        FROM students
        WHERE swimming_pool_id = ${poolId}
          AND parent_user_id IS NULL
          AND parent_phone IS NOT NULL AND parent_phone != ''
          AND deleted_at IS NULL AND status NOT IN ('archived','deleted')
      `)).rows;
      let linked = 0;
      for (const stu of unlinked) {
        const normPhone = stu.parent_phone.replace(/[^0-9]/g, "");
        const normName = stu.parent_name ? stu.parent_name.replace(/\s+/g, "").toLowerCase() : null;
        let paId = null;
        const [byPhone] = (await db12.execute(sql20`
          SELECT id FROM parent_accounts
          WHERE REGEXP_REPLACE(COALESCE(phone,''),'[^0-9]','','g') = ${normPhone}
            AND (swimming_pool_id = ${poolId} OR swimming_pool_id IS NULL)
          ORDER BY (swimming_pool_id = ${poolId}) DESC NULLS LAST
          LIMIT 1
        `)).rows;
        if (byPhone) paId = byPhone.id;
        if (!paId && normName) {
          const [byName] = (await db12.execute(sql20`
            SELECT id FROM parent_accounts
            WHERE REPLACE(LOWER(COALESCE(name,'')),' ','') = ${normName}
              AND (swimming_pool_id = ${poolId} OR swimming_pool_id IS NULL)
            ORDER BY (swimming_pool_id = ${poolId}) DESC NULLS LAST
            LIMIT 1
          `)).rows;
          if (byName) paId = byName.id;
        }
        if (!paId) continue;
        const psId = `ps_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
        await db12.execute(sql20`
          INSERT INTO parent_students (id, parent_id, student_id, swimming_pool_id, status, approved_at)
          VALUES (${psId}, ${paId}, ${stu.id}, ${poolId}, 'approved', NOW())
          ON CONFLICT DO NOTHING
        `);
        await db12.execute(sql20`
          UPDATE students SET parent_user_id = ${paId}, status = 'active', updated_at = NOW()
          WHERE id = ${stu.id} AND parent_user_id IS NULL
        `);
        await db12.execute(sql20`
          UPDATE parent_accounts SET swimming_pool_id = ${poolId}, updated_at = NOW()
          WHERE id = ${paId} AND swimming_pool_id IS NULL
        `);
        linked++;
      }
      await db12.execute(sql20`
        UPDATE students s
        SET parent_user_id = ps.parent_id,
            status = CASE WHEN s.status IN ('unregistered','pending_approval') THEN 'active' ELSE s.status END,
            updated_at = NOW()
        FROM parent_students ps
        WHERE ps.student_id = s.id
          AND s.swimming_pool_id = ${poolId}
          AND s.parent_user_id IS NULL
          AND ps.status = 'approved'
      `);
      res.json({ success: true, total_checked: unlinked.length, linked });
    } catch (err15) {
      console.error(err15);
      res.status(500).json({ error: "\uC11C\uBC84 \uC624\uB958" });
    }
  }
);
