router5.get(
  "/settlement-summary",
  requireAuth,
  requireRole("super_admin", "pool_admin"),
  async (req, res) => {
    try {
      const poolId = await getAdminPoolId(req);
      if (!poolId) {
        res.status(403).json({ error: "\uC218\uC601\uC7A5 \uC5C6\uC74C" });
        return;
      }
      const { month } = req.query;
      const targetMonth = month || (/* @__PURE__ */ new Date()).toISOString().slice(0, 7);
      const studentRows = (await db12.execute(sql20.raw(`
        SELECT
          LEAST(COALESCE(weekly_count, 1), 3) AS wc,
          COUNT(*)::int AS cnt
        FROM students
        WHERE swimming_pool_id = '${poolId}'
          AND status NOT IN ('withdrawn','deleted')
          AND (class_group_id IS NOT NULL)
        GROUP BY LEAST(COALESCE(weekly_count, 1), 3)
        ORDER BY wc
      `))).rows;
      const extraRows = (await db12.execute(sql20.raw(`
        SELECT cg.name AS class_name, COUNT(s.id)::int AS student_count
        FROM class_groups cg
        JOIN students s ON s.class_group_id = cg.id AND s.status NOT IN ('withdrawn','deleted')
        WHERE cg.swimming_pool_id = '${poolId}'
          AND cg.is_deleted = false
          AND cg.is_one_time = true
        GROUP BY cg.name
        ORDER BY cg.name
      `))).rows;
      const pricingRows = (await db12.execute(sql20.raw(`
        SELECT type_key, type_name, monthly_fee, sessions_per_month
        FROM pool_class_pricing
        WHERE pool_id = '${poolId}' AND is_active = true
        ORDER BY type_key
      `))).rows;
      const pricingMap = {};
      for (const p of pricingRows) pricingMap[p.type_key] = p;
      const WC_KEY = { 1: "weekly_1", 2: "weekly_2", 3: "weekly_3" };
      const WC_LABEL = { 1: "\uC8FC1\uD68C", 2: "\uC8FC2\uD68C", 3: "\uC8FC3\uD68C \uC774\uC0C1" };
      let totalSessions = 0;
      let totalRevenue = 0;
      const groups = studentRows.map((row) => {
        const wc = Number(row.wc) || 1;
        const cnt = row.cnt || 0;
        const key = WC_KEY[wc] || "weekly_1";
        const pricing = pricingMap[key];
        const monthlyFee = pricing ? Number(pricing.monthly_fee) : 0;
        const sessions = cnt * wc;
        const subtotal = cnt * monthlyFee;
        totalSessions += sessions;
        totalRevenue += subtotal;
        return {
          type_key: key,
          label: WC_LABEL[wc] || `\uC8FC${wc}\uD68C`,
          student_count: cnt,
          weekly_count: wc,
          monthly_fee: monthlyFee,
          sessions,
          subtotal
        };
      });
      const extraClasses = extraRows.map((r) => ({
        class_name: r.class_name,
        student_count: r.student_count
      }));
      const hasPricing = pricingRows.length > 0;
      res.json({
        month: targetMonth,
        groups,
        extra_classes: extraClasses,
        total_sessions: totalSessions,
        total_revenue: totalRevenue,
        has_pricing: hasPricing
      });
    } catch (err15) {
      console.error(err15);
      res.status(500).json({ error: "\uC11C\uBC84 \uC624\uB958" });
    }
  }
);
