router5.get("/level-settings", requireAuth, requireRole("super_admin", "pool_admin"), async (req, res) => {
  try {
    const poolId = req.user.poolId || req.query.poolId;
    if (!poolId) {
      res.status(400).json({ error: "\uC218\uC601\uC7A5 \uC815\uBCF4 \uC5C6\uC74C" });
      return;
    }
    const rows = await db12.execute(sql20`
      SELECT level_order, level_name, level_description, learning_content,
             promotion_test_rule, badge_type, badge_label, badge_color, badge_text_color, is_active
      FROM pool_level_settings WHERE pool_id = ${poolId}
      ORDER BY level_order ASC
    `);
    if (rows.rows.length === 0) {
      res.json(DEFAULT_LEVELS);
    } else {
      const custom = rows.rows;
      const merged = DEFAULT_LEVELS.map((def) => {
        const c = custom.find((r) => r.level_order === def.level_order);
        return c ? { ...def, ...c, is_custom: true } : def;
      });
      res.json(merged);
    }
  } catch (err15) {
    console.error(err15);
    res.status(500).json({ error: "\uC11C\uBC84 \uC624\uB958" });
  }
});
