init_auto_link_v2();
import {
  studentsTable as studentsTable2,
  classGroupsTable as classGroupsTable2,
  parentStudentsTable as parentStudentsTable2,
  parentAccountsTable as parentAccountsTable4,
  usersTable as usersTable4,
  attendanceTable,
  classChangeLogsTable
} from "@workspace/db/schema";
import { eq as eq5, and as and4, sql as sql21 } from "drizzle-orm";

// src/utils/change-logger.ts
import { superAdminDb as superAdminDb14 } from "@workspace/db";
import { dataChangeLogsTable } from "@workspace/db/schema";
async function logChange(params) {
  try {
    await superAdminDb14.insert(dataChangeLogsTable).values({
      id: crypto.randomUUID(),
      tenant_id: params.tenantId,
      table_name: params.tableName,
      record_id: params.recordId,
      change_type: params.changeType,
      payload: params.payload ?? null,
      sync_status: "pending"
    });
  } catch (err15) {
    console.error("[change-logger] \uB85C\uADF8 \uAE30\uB85D \uC2E4\uD328:", err15);
  }
}

// src/routes/students.ts
var router6 = Router6();
function err2(res, status, message) {
  return res.status(status).json({ success: false, message, error: message });
}
async function getPoolId(userId) {
  const [user] = await superAdminDb15.select().from(usersTable4).where(eq5(usersTable4.id, userId)).limit(1);
  return user?.swimming_pool_id || null;
}
async function getEffectiveMemberLimit(poolId) {
  const [planRow] = (await superAdminDb15.execute(sql21`
    SELECT COALESCE(p.member_limit, sp.member_limit) AS effective_member_limit,
           p.member_limit AS pool_override
    FROM swimming_pools p
    LEFT JOIN subscription_plans sp ON sp.tier = p.subscription_tier
    WHERE p.id = ${poolId} LIMIT 1
  `)).rows;
  const [cntRow] = (await db13.execute(sql21`
    SELECT COUNT(*) AS cnt FROM students
    WHERE swimming_pool_id = ${poolId} AND status NOT IN ('archived','deleted')
  `)).rows;
  const limit = Number(planRow?.effective_member_limit ?? 5);
  const current = Number(cntRow?.cnt ?? 0);
  const overrideActive = planRow?.pool_override != null;
  console.log(`[member-limit] poolId=${poolId} limit=${limit} (override=${overrideActive ? planRow?.pool_override : "none"}) current=${current}`);
  return { limit, current, overrideActive };
}
function generateInviteCode() {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  return Array.from({ length: 8 }, () => chars[Math.floor(Math.random() * chars.length)]).join("");
}
async function enrichWithClasses(student) {
  const assignedIds = Array.isArray(student.assigned_class_ids) ? student.assigned_class_ids : typeof student.assigned_class_ids === "string" ? JSON.parse(student.assigned_class_ids || "[]") : [];
  if (assignedIds.length === 0) return { ...student, assignedClasses: [] };
  const classes = await Promise.all(assignedIds.map(async (id) => {
    const [cg] = await db13.select({
      id: classGroupsTable2.id,
      name: classGroupsTable2.name,
      schedule_days: classGroupsTable2.schedule_days,
      schedule_time: classGroupsTable2.schedule_time,
      instructor: classGroupsTable2.instructor
    }).from(classGroupsTable2).where(eq5(classGroupsTable2.id, id)).limit(1);
    return cg || null;
  }));
  const validClasses = classes.filter(Boolean);
  const labels = validClasses.map((c) => {
    if (!c) return "";
    const days = c.schedule_days.split(",").map((d) => d.trim());
    const hour = c.schedule_time.split(":")[0];
    return days.map((d) => `${d}${hour}`).join("\xB7");
  }).filter(Boolean).join("\xB7");
  return { ...student, assignedClasses: validClasses, schedule_labels: labels };
}
router6.get("/", requireAuth, async (req, res) => {
  const _stuListStartedAt = Date.now();
  try {
    const poolId = await getPoolId(req.user.userId);
    if (!poolId && req.user.role !== "super_admin") return err2(res, 403, "\uC18C\uC18D\uB41C \uC218\uC601\uC7A5\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.");
    const poolAll = req.query.pool_all === "true";
    let students;
    if (req.user.role === "teacher" && !poolAll) {
      const teacherClasses = await db13.select({ id: classGroupsTable2.id }).from(classGroupsTable2).where(and4(
        eq5(classGroupsTable2.swimming_pool_id, poolId),
        eq5(classGroupsTable2.teacher_user_id, req.user.userId),
        eq5(classGroupsTable2.is_deleted, false)
      ));
      const classIds = teacherClasses.map((c) => c.id);
      if (classIds.length === 0) {
        return res.json([]);
      }
      const classIdsLiteral = classIds.map((id) => `'${id}'`).join(",");
      students = await db13.select().from(studentsTable2).where(and4(
        eq5(studentsTable2.swimming_pool_id, poolId),
        sql21`status NOT IN ('archived', 'deleted')`,
        sql21`(
            class_group_id = ANY(ARRAY[${sql21.raw(classIdsLiteral)}])
            OR EXISTS (
              SELECT 1 FROM jsonb_array_elements_text(COALESCE(assigned_class_ids, '[]'::jsonb)) AS cid
              WHERE cid = ANY(ARRAY[${sql21.raw(classIdsLiteral)}])
            )
          )`
      ));
    } else {
      students = await db13.select().from(studentsTable2).where(and4(
        eq5(studentsTable2.swimming_pool_id, poolId),
        sql21`status NOT IN ('archived', 'deleted')`
      ));
    }
    const enriched = await Promise.all(students.map(async (s) => {
      let class_group_name = null;
      if (s.class_group_id) {
        const [grp] = await db13.select({ name: classGroupsTable2.name }).from(classGroupsTable2).where(eq5(classGroupsTable2.id, s.class_group_id)).limit(1);
        class_group_name = grp?.name || null;
      }
      const withClasses = await enrichWithClasses({ ...s, class_group_name });
      return withClasses;
    }));
    const sorted = enriched.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
    console.log("[PERF][students-list]", { elapsed_ms: Date.now() - _stuListStartedAt, pool_id: poolId, count: sorted.length });
    res.json(sorted);
  } catch (e) {
    console.error(e);
    return err2(res, 500, "\uC11C\uBC84 \uC624\uB958\uAC00 \uBC1C\uC0DD\uD588\uC2B5\uB2C8\uB2E4.");
  }
});
