async function autoCreateMakeupForAbsent(poolId, studentId, cgId, date, attendanceId) {
  const existing = (await db13.execute(sql21`
    SELECT id FROM makeup_sessions
    WHERE student_id = ${studentId} AND absence_date = ${date} AND status != 'cancelled'
    LIMIT 1
  `)).rows;
  if (existing.length > 0) return;
  const [student] = await db13.select({ name: studentsTable2.name }).from(studentsTable2).where(eq5(studentsTable2.id, studentId)).limit(1);
  if (!student) return;
  let teacherId = null, teacherName = null, cgName = null;
  if (cgId) {
    const [cg] = await db13.select().from(classGroupsTable2).where(eq5(classGroupsTable2.id, cgId)).limit(1);
    if (cg) {
      teacherId = cg.teacher_user_id || null;
      teacherName = cg.instructor || null;
      cgName = cg.name || null;
    }
  }
  const mkId = `mk_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`;
  await db13.execute(sql21`
    INSERT INTO makeup_sessions (
      id, swimming_pool_id, student_id, student_name,
      original_class_group_id, original_class_group_name,
      original_teacher_id, original_teacher_name,
      absence_date, absence_attendance_id, status
    ) VALUES (
      ${mkId}, ${poolId}, ${studentId}, ${student.name},
      ${cgId}, ${cgName}, ${teacherId}, ${teacherName},
      ${date}, ${attendanceId}, 'waiting'
    )
  `);
}
async function cancelWaitingMakeup(studentId, date) {
  await db13.execute(sql21`
    UPDATE makeup_sessions
    SET status = 'cancelled', cancelled_at = now(), cancelled_reason = 'absent_cleared'
    WHERE student_id = ${studentId} AND absence_date = ${date} AND status = 'waiting'
  `);
}
router6.post("/:id/attendance", requireAuth, requireRole("super_admin", "pool_admin", "teacher"), async (req, res) => {
  const { date, status, class_group_id } = req.body;
  if (!date || !["present", "absent"].includes(status)) {
    return err2(res, 400, "\uB0A0\uC9DC\uC640 \uCD9C\uACB0 \uC0C1\uD0DC(present/absent)\uB97C \uC785\uB825\uD574\uC8FC\uC138\uC694.");
  }
  try {
    const poolId = await getPoolId(req.user.userId);
    if (!poolId) return err2(res, 403, "\uC18C\uC18D\uB41C \uC218\uC601\uC7A5\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.");
    const [actor] = await superAdminDb15.select({ name: usersTable4.name, role: usersTable4.role }).from(usersTable4).where(eq5(usersTable4.id, req.user.userId)).limit(1);
    const actorName = actor?.name || req.user.userId;
    const [student] = await db13.select().from(studentsTable2).where(eq5(studentsTable2.id, req.params.id)).limit(1);
    const cgId = class_group_id || student?.class_group_id || null;
    const existing = await db13.select().from(attendanceTable).where(and4(eq5(attendanceTable.student_id, req.params.id), eq5(attendanceTable.date, date))).limit(1);
    if (existing.length > 0) {
      const prevStatus = existing[0].status;
      const [updated] = await db13.update(attendanceTable).set({
        status,
        class_group_id: cgId || existing[0].class_group_id,
        updated_at: /* @__PURE__ */ new Date(),
        modified_by: req.user.userId,
        modified_by_name: actorName
      }).where(eq5(attendanceTable.id, existing[0].id)).returning();
      if (status === "absent") {
        await autoCreateMakeupForAbsent(poolId, req.params.id, cgId, date, existing[0].id);
      } else if (status === "present" && prevStatus === "absent") {
        await cancelWaitingMakeup(req.params.id, date);
      }
      res.json({ success: true, ...updated, was_modified: true });
    } else {
      const id = `att_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
      const [created] = await db13.insert(attendanceTable).values({
        id,
        student_id: req.params.id,
        swimming_pool_id: poolId,
        class_group_id: cgId || null,
        date,
        status,
        created_by: req.user.userId,
        created_by_name: actorName
      }).returning();
      if (status === "absent") {
        await autoCreateMakeupForAbsent(poolId, req.params.id, cgId, date, id);
      }
      res.status(201).json({ success: true, ...created, was_modified: false });
    }
  } catch (e) {
    console.error(e);
    return err2(res, 500, "\uC11C\uBC84 \uC624\uB958\uAC00 \uBC1C\uC0DD\uD588\uC2B5\uB2C8\uB2E4.");
  }
});
