router10.get("/attendance", requireAuth, requireParent, async (req, res) => {
  try {
    const pa = await db18.execute(sql26`SELECT id FROM parent_accounts WHERE id = ${req.user.userId} LIMIT 1`);
    if (!pa.rows.length) {
      res.status(404).json({ error: "\uACC4\uC815\uC744 \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4." });
      return;
    }
    const linkedStudents = await db18.execute(sql26`
      SELECT ps.student_id, s.name as student_name
      FROM parent_students ps
      JOIN students s ON s.id = ps.student_id
      WHERE ps.parent_id = ${req.user.userId} AND ps.status = 'approved'
    `);
    const studentIds = linkedStudents.rows.map((r) => r.student_id);
    const studentNames = Object.fromEntries(linkedStudents.rows.map((r) => [r.student_id, r.student_name]));
    if (!studentIds.length) {
      res.json([]);
      return;
    }
    const records = [];
    for (const sid of studentIds) {
      const sidSafe = sid.replace(/'/g, "''");
      const rows = await db18.execute(sql26.raw(`
        SELECT a.id, a.student_id as member_id, a.date, a.status
        FROM attendance a
        JOIN student_class_history sch
          ON sch.student_id = a.student_id
          AND sch.class_group_id = a.class_group_id
          AND sch.enrolled_at::text <= a.date
          AND (sch.left_at IS NULL OR sch.left_at::text > a.date)
        WHERE a.student_id = '${sidSafe}'
          AND a.class_group_id IS NOT NULL
        ORDER BY a.date DESC
      `));
      for (const r of rows.rows) {
        records.push({ ...r, member_name: studentNames[sid] || "" });
      }
    }
    records.sort((a, b) => b.date.localeCompare(a.date));
    res.json(records);
  } catch (err15) {
    console.error(err15);
    res.status(500).json({ error: "\uC11C\uBC84 \uC624\uB958\uAC00 \uBC1C\uC0DD\uD588\uC2B5\uB2C8\uB2E4." });
  }
});
