router10.get("/students/:id/level-info", requireAuth, requireParent, async (req, res) => {
  try {
    const [link] = await db18.select().from(parentStudentsTable3).where(and8(
      eq9(parentStudentsTable3.parent_id, req.user.userId),
      eq9(parentStudentsTable3.student_id, req.params.id),
      eq9(parentStudentsTable3.status, "approved")
    )).limit(1);
    if (!link) {
      res.status(403).json({ error: "\uC811\uADFC \uAD8C\uD55C\uC774 \uC5C6\uC2B5\uB2C8\uB2E4." });
      return;
    }
    const studRow = await db18.execute(sql26`
      SELECT current_level_order, swimming_pool_id FROM students WHERE id = ${req.params.id}
    `);
    const student = studRow.rows[0];
    const poolId = student?.swimming_pool_id;
    const currentOrder = student?.current_level_order ?? null;
    const levelRows = await db18.execute(sql26`
      SELECT level_order, level_name, level_description, learning_content,
             promotion_test_rule, badge_type, badge_label, badge_color, badge_text_color, is_active
      FROM pool_level_settings WHERE pool_id = ${poolId}
      ORDER BY level_order ASC
    `);
    const allDefs = levelRows.rows.length > 0 ? levelRows.rows : DEFAULT_LEVELS_P;
    const activeDefs = allDefs.filter((l) => l.is_active !== false);
    const currentDef = currentOrder ? allDefs.find((l) => l.level_order === currentOrder) ?? null : null;
    const nextDef = currentOrder ? activeDefs.find((l) => l.level_order > currentOrder) ?? null : null;
    res.json({ current_level_order: currentOrder, current_level: currentDef, next_level: nextDef, all_levels: activeDefs });
  } catch (err15) {
    res.status(500).json({ error: "\uC11C\uBC84 \uC624\uB958" });
  }
});
