router10.post("/link-child", requireAuth, requireParent, async (req, res) => {
  const parentId = req.user.userId;
  const { swimming_pool_id, child_name, child_birth_year, child_phone_last4 } = req.body;
  if (!swimming_pool_id || !child_name?.trim()) {
    res.status(400).json({ success: false, message: "\uC218\uC601\uC7A5\uACFC \uC790\uB140 \uC774\uB984\uC744 \uC785\uB825\uD574\uC8FC\uC138\uC694." });
    return;
  }
  try {
    const [pool2] = await superAdminDb19.select().from(swimmingPoolsTable4).where(eq9(swimmingPoolsTable4.id, swimming_pool_id)).limit(1);
    if (!pool2) {
      res.status(400).json({ success: false, message: "\uC874\uC7AC\uD558\uC9C0 \uC54A\uB294 \uC218\uC601\uC7A5\uC785\uB2C8\uB2E4." });
      return;
    }
    const nameRaw = child_name.trim();
    const nameNorm = normalizeName(nameRaw);
    const paRows = await db18.execute(sql26`
      SELECT phone FROM parent_accounts WHERE id = ${parentId} LIMIT 1
    `);
    const parentPhone = (paRows.rows[0]?.phone || "").replace(/[^0-9]/g, "");
    await db18.execute(sql26`
      UPDATE parent_accounts SET swimming_pool_id = ${swimming_pool_id}, updated_at = NOW()
      WHERE id = ${parentId}
    `);
    const { matched, studentId, studentName, reason } = await tryMatchStudentV2(parentId, swimming_pool_id, parentPhone, nameNorm);
    if (matched && studentId) {
      const linkResult = await linkParentToStudentV2(parentId, studentId, swimming_pool_id);
      if (linkResult.success) {
        return res.json({ success: true, status: "linked", message: "\uC790\uB140\uAC00 \uC5F0\uACB0\uB418\uC5C8\uC2B5\uB2C8\uB2E4.", student: { id: studentId, name: studentName } });
      }
    }
    const foundRows = (await db18.execute(sql26`
      SELECT id, name FROM students
      WHERE swimming_pool_id = ${swimming_pool_id}
        AND REPLACE(LOWER(TRIM(COALESCE(name,''))), ' ', '') = ${nameNorm}
        AND status NOT IN ('withdrawn','archived','deleted')
      LIMIT 5
    `)).rows;
    if (foundRows.length === 0) {
      return res.json({ success: false, status: "not_found", message: "\uC218\uC601\uC7A5 \uD68C\uC6D0 \uBAA9\uB85D\uC5D0 \uD574\uB2F9 \uC774\uB984\uC758 \uD559\uC0DD\uC774 \uC5C6\uC2B5\uB2C8\uB2E4. \uAD00\uB9AC\uC790\uC5D0\uAC8C \uC774\uB984 \uB4F1\uB85D\uC744 \uC694\uCCAD\uD558\uC138\uC694." });
    }
    const pendingStudentId = foundRows.length === 1 ? foundRows[0].id : null;
    const pendingStudentName = foundRows.length === 1 ? foundRows[0].name : foundRows[0].name;
    const pendingReason = foundRows.length >= 2 ? "duplicate_name" : "phone_mismatch";
    await upsertParentV2Pending(parentId, swimming_pool_id, nameRaw, nameNorm, parentPhone, pendingReason, pendingStudentId ?? void 0);
    try {
      const { sendPushToPoolAdmins: sendPushToPoolAdmins3 } = await Promise.resolve().then(() => (init_push_service(), push_service_exports));
      const [pa] = (await db18.execute(sql26`SELECT name FROM parent_accounts WHERE id=${parentId} LIMIT 1`)).rows;
      await sendPushToPoolAdmins3(
        swimming_pool_id,
        "parent_join",
        "\uD559\uBD80\uBAA8 \uC5F0\uACB0 \uC2B9\uC778 \uB300\uAE30",
        `${pa?.name || "\uD559\uBD80\uBAA8"}\uB2D8\uC774 ${pendingStudentName} \uC5F0\uACB0\uC744 \uC694\uCCAD\uD588\uC2B5\uB2C8\uB2E4. \uC804\uD654\uBC88\uD638 \uD655\uC778 \uD6C4 \uC2B9\uC778\uD574\uC8FC\uC138\uC694.`,
        { screen: "approvals" },
        `parent_link_${parentId}`
      );
    } catch {
    }
    return res.json({
      success: false,
      status: "pending",
      pending_reason: pendingReason,
      message: pendingReason === "duplicate_name" ? "\uAC19\uC740 \uC774\uB984\uC758 \uD559\uC0DD\uC774 \uC5EC\uB7EC \uBA85\uC785\uB2C8\uB2E4. \uAD00\uB9AC\uC790\uAC00 \uD655\uC778 \uD6C4 \uC2B9\uC778\uD569\uB2C8\uB2E4." : "\uB4F1\uB85D\uB41C \uBCF4\uD638\uC790 \uC804\uD654\uBC88\uD638\uC640 \uC77C\uCE58\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uAD00\uB9AC\uC790\uAC00 \uD655\uC778 \uD6C4 \uC2B9\uC778\uD569\uB2C8\uB2E4.",
      student: { name: pendingStudentName }
    });
  } catch (e) {
    console.error(e);
    res.status(500).json({ success: false, message: "\uC11C\uBC84 \uC624\uB958\uAC00 \uBC1C\uC0DD\uD588\uC2B5\uB2C8\uB2E4." });
  }
});
