async function insertGrowthEvents(params) {
  const {
    tx,
    poolId,
    diaryId,
    savedNotes,
    curriculumMatches,
    requestId,
    contractVersion
  } = params;
  let inserted = 0;
  let skipped = 0;
  let errors = 0;
  const trace = `req=${requestId ?? "-"} diary=${diaryId}`;
  for (const match of curriculumMatches) {
    if (match.match_status !== "PENDING_REVIEW") {
      console.log(
        `[growth-event] SKIP_STATUS ${trace} student=${match.student_ref} skip_reason=status:${match.match_status}`
      );
      skipped++;
      continue;
    }
    let tokenPayload;
    try {
      tokenPayload = verifyMatchToken(match.match_token, {
        expectedPoolId: poolId,
        expectedStudentId: match.student_ref,
        expectedCandidateId: match.candidate_id
      });
    } catch (e) {
      if (e instanceof MatchTokenError) {
        console.error(
          `[growth-event] TOKEN_ERROR ${trace} student=${match.student_ref} skip_reason=${e.code}`
        );
        errors++;
        continue;
      }
      throw e;
    }
    const studentNote = savedNotes.find((n) => n.student_id === tokenPayload.student_id);
    if (!studentNote) {
      console.log(
        `[growth-event] NO_NOTE ${trace} student=${tokenPayload.student_id} skip_reason=no_student_note`
      );
      skipped++;
      continue;
    }
    try {
      const insertRes = await tx.execute(sql30`
        INSERT INTO growth_events (
          student_id,
          swimming_pool_id,
          curriculum_item_id,
          curriculum_version_id,
          diary_note_id,
          source,
          match_token_id,
          growth_match_status,
          confidence,
          matching_algorithm_version,
          contract_version,
          request_id
        ) VALUES (
          ${tokenPayload.student_id},
          ${poolId},
          ${tokenPayload.curriculum_item_id},
          ${tokenPayload.curriculum_version_id},
          ${studentNote.id},
          'teacher_ai',
          ${tokenPayload.token_id},
          'PENDING_REVIEW',
          ${tokenPayload.confidence},
          ${tokenPayload.matching_algorithm_version},
          ${contractVersion ?? null},
          ${requestId ?? null}
        )
        ON CONFLICT (diary_note_id, student_id, curriculum_item_id, source)
          WHERE diary_note_id IS NOT NULL AND is_invalidated = false
        DO NOTHING
      `);
      const rowCount = insertRes.rowCount ?? 0;
      if (rowCount > 0) {
        console.log(
          `[growth-event] INSERTED ${trace} note=${studentNote.id} student=${tokenPayload.student_id} curriculum=${tokenPayload.curriculum_item_id}`
        );
        inserted++;
      } else {
        console.log(
          `[growth-event] CONFLICT_SKIP ${trace} note=${studentNote.id} student=${tokenPayload.student_id} skip_reason=uq_per_note`
        );
        skipped++;
      }
    } catch (e) {
      if (e?.code === "23505") {
        console.log(
          `[growth-event] DUPLICATE_TOKEN_SKIP ${trace} student=${tokenPayload.student_id} skip_reason=uq_match_token`
        );
        skipped++;
      } else {
        throw e;
      }
    }
  }
  return { inserted, skipped, errors };
}
async function getStudentGrowthEvents(params) {
  const { db: db63, poolId, studentId, limit, offset, status, source, from, to } = params;
  const statusClause = status ? sql30` AND ge.growth_match_status = ${status}::growth_match_status_enum` : sql30``;
  const sourceClause = source ? sql30` AND ge.source = ${source}` : sql30``;
  const fromClause = from ? sql30` AND ge.created_at >= ${from}::timestamptz` : sql30``;
  const toClause = to ? sql30` AND ge.created_at <  ${to}::timestamptz` : sql30``;
  const listRes = await db63.execute(sql30`
    SELECT
      ge.id                    AS event_id,
      ge.student_id,
      ge.source,
      ge.growth_match_status   AS status,
      ge.created_at,
      ge.diary_note_id,
      ge.curriculum_item_id,
      ge.curriculum_version_id,
      ge.match_token_id,
      ge.confidence,
      ge.is_invalidated,
      ci.title                 AS curriculum_title
    FROM growth_events ge
    LEFT JOIN curriculum_items ci ON ci.id = ge.curriculum_item_id
    WHERE ge.student_id        = ${studentId}
      AND ge.swimming_pool_id  = ${poolId}
      AND ge.is_invalidated    = false
      ${statusClause}
      ${sourceClause}
      ${fromClause}
      ${toClause}
    ORDER BY ge.created_at DESC
    LIMIT  ${limit}
    OFFSET ${offset}
  `);
  const countRes = await db63.execute(sql30`
    SELECT COUNT(*) AS cnt
    FROM growth_events ge
    WHERE ge.student_id       = ${studentId}
      AND ge.swimming_pool_id = ${poolId}
      AND ge.is_invalidated   = false
      ${statusClause}
      ${sourceClause}
      ${fromClause}
      ${toClause}
  `);
  const total = Number(countRes.rows[0]?.cnt ?? 0);
  const events = listRes.rows.map((r) => ({
    event_id: r.event_id,
    student_id: r.student_id,
    source: r.source,
    status: r.status,
    created_at: r.created_at instanceof Date ? r.created_at.toISOString() : String(r.created_at),
    diary_note_id: r.diary_note_id ?? null,
    curriculum_item_id: r.curriculum_item_id ?? null,
    curriculum_version_id: r.curriculum_version_id ?? null,
    match_token_id: r.match_token_id ?? null,
    confidence: r.confidence != null ? Number(r.confidence) : null,
    is_invalidated: Boolean(r.is_invalidated),
    curriculum_title: r.curriculum_title ?? null
  }));
  return { events, total };
}
async function getGrowthEventById(params) {
  const { db: db63, poolId, studentId, eventId } = params;
  const res = await db63.execute(sql30`
    SELECT
      ge.id                    AS event_id,
      ge.student_id,
      ge.source,
      ge.growth_match_status   AS status,
      ge.created_at,
      ge.diary_note_id,
      ge.curriculum_item_id,
      ge.curriculum_version_id,
      ge.match_token_id,
      ge.confidence,
      ge.is_invalidated,
      ci.title                 AS curriculum_title
    FROM growth_events ge
    LEFT JOIN curriculum_items ci ON ci.id = ge.curriculum_item_id
    WHERE ge.id               = ${eventId}
      AND ge.student_id       = ${studentId}
      AND ge.swimming_pool_id = ${poolId}
    LIMIT 1
  `);
  const r = res.rows[0];
  if (!r) return null;
  return {
    event_id: r.event_id,
    student_id: r.student_id,
    source: r.source,
    status: r.status,
    created_at: r.created_at instanceof Date ? r.created_at.toISOString() : String(r.created_at),
    diary_note_id: r.diary_note_id ?? null,
    curriculum_item_id: r.curriculum_item_id ?? null,
    curriculum_version_id: r.curriculum_version_id ?? null,
    match_token_id: r.match_token_id ?? null,
    confidence: r.confidence != null ? Number(r.confidence) : null,
    is_invalidated: Boolean(r.is_invalidated),
    curriculum_title: r.curriculum_title ?? null
  };
}
var ReviewConflictError = class extends Error {
  code;
  constructor(code, message) {
    super(message);
    this.name = "ReviewConflictError";
    this.code = code;
  }
};
async function reviewGrowthEvent(params) {
  const { db: db63, poolId, studentId, eventId, action, reviewerUserId, reviewerRole = "teacher" } = params;
  const newStatus = action === "accept" ? "TEACHER_ACCEPTED" : "TEACHER_REJECTED";
  const fetchRes = await db63.execute(sql30`
    SELECT id, growth_match_status, is_invalidated
    FROM growth_events
    WHERE id               = ${eventId}
      AND student_id       = ${studentId}
      AND swimming_pool_id = ${poolId}
    LIMIT 1
  `);
  const row = fetchRes.rows[0];
  if (!row) return null;
  if (Boolean(row.is_invalidated)) {
    throw new ReviewConflictError("invalidated", "\uBB34\uD6A8\uD654\uB41C \uC774\uBCA4\uD2B8\uB294 \uAC80\uD1A0\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.");
  }
  const currentStatus = row.growth_match_status;
  if (currentStatus === newStatus) {
    return { updated: false, previousStatus: currentStatus, newStatus };
  }
  if (currentStatus !== "PENDING_REVIEW") {
    throw new ReviewConflictError(
      "invalid_transition",
      `${currentStatus} \uC0C1\uD0DC\uC5D0\uC11C\uB294 review \uBCC0\uACBD\uC774 \uBD88\uAC00\uD569\uB2C8\uB2E4.`
    );
  }
  const now = (/* @__PURE__ */ new Date()).toISOString();
  await db63.execute(sql30`
    UPDATE growth_events
    SET growth_match_status = ${newStatus}::growth_match_status_enum,
        reviewed_by         = ${reviewerUserId},
        reviewed_at         = ${now}::timestamptz,
        updated_at          = NOW()
    WHERE id               = ${eventId}
      AND swimming_pool_id = ${poolId}
  `);
  try {
    const versionRes = await db63.execute(sql30`
      SELECT next_audit_version('growth_event', ${eventId}) AS v
    `);
    const version = versionRes.rows[0]?.v ?? 1;
    await db63.execute(sql30`
      INSERT INTO audit_logs (
        entity_type, entity_id, entity_version,
        action, actor_type, actor_id, pool_id,
        before_data, after_data, reason,
        request_id, correlation_id, ip_hash
      ) VALUES (
        'growth_event', ${eventId}, ${version},
        'update',
        ${reviewerRole}, ${reviewerUserId}, ${poolId},
        ${JSON.stringify({ growth_match_status: currentStatus, student_id: studentId })}::jsonb,
        ${JSON.stringify({ growth_match_status: newStatus, review_action: action, reviewed_by: reviewerUserId, reviewed_at: now })}::jsonb,
        'teacher_review',
        NULL, NULL, NULL
      )
    `);
  } catch (auditErr) {
    console.warn("[growth-review] audit_log \uAE30\uB85D \uC2E4\uD328:", auditErr.message);
  }
  console.log(
    `[growth-review] ${action.toUpperCase()}: event=${eventId} pool=${poolId} status: ${currentStatus} \u2192 ${newStatus} by=${reviewerUserId}`
  );
  return { updated: true, previousStatus: currentStatus, newStatus };
}

