var COL = `id, level_id, title, template_text, sort_order, is_active, category, level, scope, teacher_id`;
router13.get(
  "/diary-templates",
  requireAuth,
  requireRole("super_admin", "pool_admin", "teacher"),
  async (req, res) => {
    try {
      const poolId = await getUserPoolId2(req.user.userId);
      const levelId = req.query.level_id;
      const includeInactive = req.query.include_inactive === "true";
      const isAdmin = ["super_admin", "pool_admin"].includes(req.user.role);
      const userId = req.user.userId;
      const ORDER = sql31`ORDER BY scope ASC, sort_order ASC, created_at ASC`;
      if (isAdmin) {
        if (levelId) {
          const rows = includeInactive ? await db21.execute(sql31`SELECT ${sql31.raw(COL)} FROM diary_templates WHERE swimming_pool_id = ${poolId} AND level_id = ${levelId} AND scope = 'global' ${ORDER}`) : await db21.execute(sql31`SELECT ${sql31.raw(COL)} FROM diary_templates WHERE swimming_pool_id = ${poolId} AND level_id = ${levelId} AND scope = 'global' AND is_active = true ${ORDER}`);
          res.json(rows.rows);
        } else {
          const rows = await db21.execute(sql31`SELECT ${sql31.raw(COL)} FROM diary_templates WHERE swimming_pool_id = ${poolId} AND scope = 'global' AND is_active = true ${ORDER}`);
          res.json(rows.rows);
        }
      } else {
        const lvF = levelId ? sql31`AND g.level_id = ${levelId}` : sql31``;
        const lvFt = levelId ? sql31`AND level_id = ${levelId}` : sql31``;
        const activeFilter = includeInactive ? sql31`` : sql31`AND COALESCE(ov.is_active, true) = true`;
        const merged = await db21.execute(sql31`
          SELECT
            g.id           AS global_id,
            g.id           AS id,
            COALESCE(ov.template_text, g.template_text) AS template_text,
            COALESCE(ov.title, g.title)                 AS title,
            g.level_id, g.sort_order,
            COALESCE(ov.is_active, g.is_active)         AS is_active,
            (ov.id IS NOT NULL)                         AS is_overridden,
            ov.id                                       AS override_id
          FROM diary_templates g
          LEFT JOIN diary_templates ov
            ON ov.source_template_id = g.id
           AND ov.scope = 'teacher'
           AND ov.teacher_id = ${userId}
           AND ov.swimming_pool_id = g.swimming_pool_id
          WHERE g.swimming_pool_id = ${poolId}
            AND g.scope = 'global'
            AND g.is_active = true
            ${lvF}
            ${activeFilter}
          ORDER BY g.sort_order ASC, g.created_at ASC
        `);
        const teacherNew = await db21.execute(sql31`
          SELECT
            NULL           AS global_id,
            id, template_text, title, level_id, sort_order, is_active,
            false          AS is_overridden,
            id             AS override_id
          FROM diary_templates
          WHERE swimming_pool_id = ${poolId}
            AND scope = 'teacher'
            AND teacher_id = ${userId}
            AND source_template_id IS NULL
            ${lvFt}
            ${includeInactive ? sql31`` : sql31`AND is_active = true`}
          ORDER BY sort_order ASC
        `);
        res.json([...merged.rows, ...teacherNew.rows]);
      }
    } catch (e) {
      console.error(e);
      apiErr(res, 500, "\uC11C\uBC84 \uC624\uB958");
    }
  }
);
router13.post(
  "/diary-templates/:id/override",
  requireAuth,
  requireRole("teacher"),
  async (req, res) => {
    try {
      const { template_text, title } = req.body;
      if (!template_text?.trim()) return apiErr(res, 400, "\uB0B4\uC6A9\uC744 \uC785\uB825\uD574\uC8FC\uC138\uC694.");
      const globalId = req.params.id;
      const poolId = await getUserPoolId2(req.user.userId);
      const userId = req.user.userId;
      const gCheck = await db21.execute(sql31`SELECT id, level_id, sort_order FROM diary_templates WHERE id = ${globalId} AND swimming_pool_id = ${poolId} AND scope = 'global'`);
      if (!gCheck.rows.length) return apiErr(res, 404, "\uC6D0\uBCF8 \uD15C\uD50C\uB9BF\uC744 \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.");
      const g = gCheck.rows[0];
      const existing = await db21.execute(sql31`SELECT id FROM diary_templates WHERE source_template_id = ${globalId} AND scope = 'teacher' AND teacher_id = ${userId} AND swimming_pool_id = ${poolId}`);
      if (existing.rows.length) {
        const ovId = existing.rows[0].id;
        await db21.execute(sql31`UPDATE diary_templates SET template_text = ${template_text.trim()}, title = ${title?.trim() || null}, updated_at = NOW() WHERE id = ${ovId}`);
        res.json({ success: true, id: ovId });
      } else {
        const newId = genId2("dt");
        await db21.execute(sql31`INSERT INTO diary_templates (id, swimming_pool_id, template_text, title, level_id, sort_order, scope, teacher_id, source_template_id, created_by) VALUES (${newId}, ${poolId}, ${template_text.trim()}, ${title?.trim() || null}, ${g.level_id}, ${g.sort_order}, 'teacher', ${userId}, ${globalId}, ${userId})`);
        res.json({ success: true, id: newId });
      }
    } catch (e) {
      console.error(e);
      apiErr(res, 500, "\uC11C\uBC84 \uC624\uB958");
    }
  }
);
router13.post(
  "/diary-templates/:id/toggle-active",
  requireAuth,
  requireRole("teacher"),
  async (req, res) => {
    try {
      const { is_active } = req.body;
      if (typeof is_active !== "boolean") return apiErr(res, 400, "is_active(boolean) \uD544\uC694");
      const templateId = req.params.id;
      const poolId = await getUserPoolId2(req.user.userId);
      const userId = req.user.userId;
      const check = await db21.execute(sql31`
        SELECT id, scope, teacher_id, template_text, level_id, sort_order
        FROM diary_templates WHERE id = ${templateId} AND swimming_pool_id = ${poolId}
      `);
      if (!check.rows.length) return apiErr(res, 404, "\uD15C\uD50C\uB9BF\uC744 \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.");
      const tpl = check.rows[0];
      if (tpl.scope === "global") {
        const existing = await db21.execute(sql31`
          SELECT id FROM diary_templates
          WHERE source_template_id = ${templateId} AND scope = 'teacher'
            AND teacher_id = ${userId} AND swimming_pool_id = ${poolId}
        `);
        if (existing.rows.length) {
          const ovId = existing.rows[0].id;
          await db21.execute(sql31`UPDATE diary_templates SET is_active = ${is_active}, updated_at = NOW() WHERE id = ${ovId}`);
        } else if (!is_active) {
          const newId = genId2("dt");
          await db21.execute(sql31`
            INSERT INTO diary_templates (id, swimming_pool_id, template_text, level_id, sort_order, scope, teacher_id, source_template_id, is_active, created_by)
            VALUES (${newId}, ${poolId}, ${tpl.template_text}, ${tpl.level_id}, ${tpl.sort_order}, 'teacher', ${userId}, ${templateId}, false, ${userId})
          `);
        }
      } else if (tpl.scope === "teacher" && tpl.teacher_id === userId) {
        await db21.execute(sql31`UPDATE diary_templates SET is_active = ${is_active}, updated_at = NOW() WHERE id = ${templateId} AND swimming_pool_id = ${poolId}`);
      } else {
        return apiErr(res, 403, "\uAD8C\uD55C\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.");
      }
      res.json({ success: true });
    } catch (e) {
      console.error(e);
      apiErr(res, 500, "\uC11C\uBC84 \uC624\uB958");
    }
  }
);
