router13.get(
  "/teacher/overview",
  requireAuth,
  requireRole("teacher", "pool_admin", "super_admin"),
  async (req, res) => {
    try {
      const { userId } = req.user;
      const poolId = await getUserPoolId2(userId);
      const today = (/* @__PURE__ */ new Date()).toISOString().slice(0, 10);
      const myClasses = await db21.execute(sql31`
        SELECT id FROM class_groups
        WHERE teacher_user_id = ${userId} AND swimming_pool_id = ${poolId}
      `);
      const classIds = myClasses.rows.map((r) => r.id);
      if (classIds.length === 0) {
        res.json({ unread_messages: 0, pending_diaries_today: 0, pending_diaries_past: 0, makeup_count: 0, unread_news: 0 });
        return;
      }
      const classIdList = classIds.map((id) => `'${id}'`).join(",");
      const unreadMsg = await db21.execute(sql31`
        SELECT COUNT(*) AS cnt
        FROM diary_messages dm
        JOIN class_diaries cd ON cd.id = dm.diary_id
        WHERE cd.class_group_id IN (${sql31.raw(classIdList)})
          AND dm.sender_role = 'parent'
          AND dm.is_deleted = false
          AND dm.read_at IS NULL
      `).catch(() => ({ rows: [{ cnt: 0 }] }));
      const nowKST = new Date((/* @__PURE__ */ new Date()).toLocaleString("en-US", { timeZone: "Asia/Seoul" }));
      const dayNamesKr = { 0: "\uC77C", 1: "\uC6D4", 2: "\uD654", 3: "\uC218", 4: "\uBAA9", 5: "\uAE08", 6: "\uD1A0" };
      const todayKr = dayNamesKr[nowKST.getDay()];
      const pendingToday = await db21.execute(sql31`
        SELECT COUNT(*) AS cnt
        FROM class_groups cg
        WHERE cg.id IN (${sql31.raw(classIdList)})
          AND cg.is_deleted = false
          AND (
            (cg.is_one_time = false AND cg.schedule_days LIKE ${"%" + todayKr + "%"})
            OR (cg.is_one_time = true AND cg.one_time_date = ${today})
          )
          AND NOT EXISTS (
            SELECT 1 FROM class_diaries cd
            WHERE cd.class_group_id = cg.id AND cd.lesson_date = ${today} AND cd.is_deleted = false
          )
      `);
      const pendingPastCount = 0;
      const makeupCount = await db21.execute(sql31`
        SELECT COUNT(*) AS cnt FROM makeup_sessions
        WHERE original_class_group_id IN (${sql31.raw(classIdList)}) AND status = 'waiting'
      `);
      const pendingRequests = await db21.execute(sql31`
        SELECT COUNT(*) AS cnt FROM parent_student_requests
        WHERE teacher_user_id = ${userId} AND status = 'pending'
      `).catch(() => ({ rows: [{ cnt: 0 }] }));
      const unreadReqMsgs = await db21.execute(sql31`
        SELECT COUNT(*) AS cnt FROM parent_request_messages prm
        JOIN parent_student_requests psr ON psr.id = prm.request_id
        WHERE psr.teacher_user_id = ${userId}
          AND prm.sender_type = 'parent'
          AND prm.is_read_by_teacher = false
      `).catch(() => ({ rows: [{ cnt: 0 }] }));
      const psRows = await db21.execute(sql31`
        SELECT notification_type, is_enabled FROM push_settings
        WHERE user_id = ${userId} AND notification_type IN ('news_like', 'news_thanks', 'news_comment')
      `).catch(() => ({ rows: [] }));
      const newsSettings = {};
      for (const r of psRows.rows) newsSettings[r.notification_type] = Boolean(r.is_enabled);
      const enabledNewsTypes = [];
      if (newsSettings.news_like !== false) enabledNewsTypes.push("diary_like");
      if (newsSettings.news_thanks !== false) enabledNewsTypes.push("diary_thanks");
      if (newsSettings.news_comment !== false) enabledNewsTypes.push("diary_comment");
      let unreadNews = 0;
      if (enabledNewsTypes.length > 0) {
        const typeList = enabledNewsTypes.map((t) => `'${t}'`).join(",");
        const newsCount = await db21.execute(sql31`
          SELECT COUNT(*) AS cnt FROM notifications
          WHERE recipient_id = ${userId} AND recipient_type = 'user'
            AND type IN (${sql31.raw(typeList)}) AND is_read = false
        `).catch(() => ({ rows: [{ cnt: 0 }] }));
        unreadNews = Number(newsCount.rows[0]?.cnt ?? 0);
      }
      res.json({
        unread_messages: Number(unreadMsg.rows[0]?.cnt ?? 0),
        pending_diaries_today: Number(pendingToday.rows[0]?.cnt ?? 0),
        pending_diaries_past: pendingPastCount,
        makeup_count: Number(makeupCount.rows[0]?.cnt ?? 0),
        pending_parent_requests: Number(pendingRequests.rows[0]?.cnt ?? 0),
        unread_parent_request_messages: Number(unreadReqMsgs.rows[0]?.cnt ?? 0),
        unread_news: unreadNews
      });
    } catch (e) {
      console.error(e);
      apiErr(res, 500, "\uC11C\uBC84 \uC624\uB958");
    }
  }
);
