// src/payment/toss.ts
var TOSS_API_BASE = "https://api.tosspayments.com/v1";
function authHeader(secretKey) {
  return "Basic " + Buffer.from(secretKey + ":").toString("base64");
}
var TossPaymentProvider = class {
  name = "toss";
  secretKey;
  constructor(secretKey) {
    this.secretKey = secretKey;
  }
  async issueBillingKey(cardInfo) {
    const customerKey = `customer_${Date.now()}`;
    const body = {
      cardNumber: cardInfo.cardNumber.replace(/\s/g, ""),
      cardExpirationYear: cardInfo.expiry.split("/")[1],
      cardExpirationMonth: cardInfo.expiry.split("/")[0],
      customerIdentityNumber: cardInfo.birthOrBiz ?? "",
      cardPassword: cardInfo.password ?? "",
      customerKey
    };
    const res = await fetch(`${TOSS_API_BASE}/billing/authorizations/card`, {
      method: "POST",
      headers: {
        Authorization: authHeader(this.secretKey),
        "Content-Type": "application/json"
      },
      body: JSON.stringify(body)
    });
    if (!res.ok) {
      const err15 = await res.json().catch(() => ({}));
      throw new Error(err15.message ?? "\uD1A0\uC2A4\uD398\uC774\uBA3C\uCE20 \uBE4C\uB9C1\uD0A4 \uBC1C\uAE09 \uC2E4\uD328");
    }
    const data = await res.json();
    return {
      billingKey: data.billingKey,
      cardLast4: data.card?.number?.slice(-4) ?? "****",
      cardBrand: data.card?.company ?? "\uCE74\uB4DC"
    };
  }
  async charge(params) {
    const body = {
      billingKey: params.billingKey,
      customerKey: params.poolId,
      amount: params.amount,
      orderId: params.orderId,
      orderName: params.orderName,
      customerName: params.poolId
    };
    const res = await fetch(`${TOSS_API_BASE}/billing/${params.billingKey}`, {
      method: "POST",
      headers: {
        Authorization: authHeader(this.secretKey),
        "Content-Type": "application/json"
      },
      body: JSON.stringify(body)
    });
    const data = await res.json();
    if (!res.ok) {
      return { success: false, pgTransactionId: "", errorMessage: data.message ?? "\uACB0\uC81C \uC2E4\uD328" };
    }
    return { success: true, pgTransactionId: data.paymentKey };
  }
  async deleteBillingKey(billingKey) {
    console.log(`[toss] \uBE4C\uB9C1\uD0A4 \uBE44\uD65C\uC131\uD654 \uCC98\uB9AC \u2014 ${billingKey}`);
  }
};

// src/payment/portone.ts
var PORTONE_API_BASE = "https://api.portone.io";
var PortOnePaymentProvider = class {
  name = "portone";
  apiSecret;
  channelKey;
  constructor(apiSecret, channelKey) {
    this.apiSecret = apiSecret;
    this.channelKey = channelKey;
  }
  async getAccessToken() {
    const res = await fetch(`${PORTONE_API_BASE}/login/api-secret`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ apiSecret: this.apiSecret })
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.message ?? "\uD3EC\uD2B8\uC6D0 \uC778\uC99D \uC2E4\uD328");
    return data.accessToken;
  }
  async issueBillingKey(cardInfo) {
    const token = await this.getAccessToken();
    const digits = cardInfo.cardNumber.replace(/\s|-/g, "");
    const res = await fetch(`${PORTONE_API_BASE}/billing-keys`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        channelKey: this.channelKey,
        method: {
          card: {
            credential: {
              number: digits,
              expiryYear: cardInfo.expiry.split("/")[1],
              expiryMonth: cardInfo.expiry.split("/")[0],
              birthOrBusinessRegistrationNumber: cardInfo.birthOrBiz ?? "",
              passwordTwoDigits: cardInfo.password ?? ""
            }
          }
        }
      })
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.message ?? "\uD3EC\uD2B8\uC6D0 \uBE4C\uB9C1\uD0A4 \uBC1C\uAE09 \uC2E4\uD328");
    const cardLast4 = data.methods?.[0]?.card?.number?.slice(-4) ?? "****";
    const cardBrand = data.methods?.[0]?.card?.brand ?? "\uCE74\uB4DC";
    return { billingKey: data.billingKey, cardLast4, cardBrand };
  }
  async charge(params) {
    const token = await this.getAccessToken();
    const paymentId = params.orderId;
    const res = await fetch(`${PORTONE_API_BASE}/payments/${paymentId}/billing-key`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        billingKey: params.billingKey,
        orderName: params.orderName,
        amount: { total: params.amount },
        currency: "KRW",
        customer: { id: params.poolId }
      })
    });
    const data = await res.json();
    if (!res.ok || data.status === "FAILED") {
      return { success: false, pgTransactionId: paymentId, errorMessage: data.message ?? "\uACB0\uC81C \uC2E4\uD328" };
    }
    return { success: true, pgTransactionId: paymentId };
  }
  async deleteBillingKey(billingKey) {
    const token = await this.getAccessToken();
    await fetch(`${PORTONE_API_BASE}/billing-keys/${billingKey}`, {
      method: "DELETE",
      headers: { Authorization: `Bearer ${token}` }
    });
  }
};

