async function handleXEntitlementEvent(params) {
  const { eventType, poolId, productId, eventId, expiresAt, isSandbox } = params;
  const [currentPool] = (await superAdminDb27.execute(sql36`
      SELECT xmode_config_status, xmode_purchased_at,
             xmode_subscription_end_at,
             COALESCE(x_paid_entitlement,  false) AS x_paid_entitlement,
             COALESCE(x_manual_entitlement, false) AS x_manual_entitlement,
             COALESCE(x_force_disabled,    false) AS x_force_disabled
      FROM swimming_pools
      WHERE id = ${poolId}
      LIMIT 1
    `)).rows;
  if (!currentPool) {
    console.warn(`[x-entitlement] pool \uC5C6\uC74C: ${poolId}`);
    return;
  }
  const beforePaid = Boolean(currentPool.x_paid_entitlement);
  const beforeManual = Boolean(currentPool.x_manual_entitlement);
  const beforeForce = Boolean(currentPool.x_force_disabled);
  const beforeEffective = resolveEffectiveXEntitlement({
    x_paid_entitlement: beforePaid,
    x_manual_entitlement: beforeManual,
    x_force_disabled: beforeForce
  });
  let newPaid = beforePaid;
  switch (eventType) {
    case "INITIAL_PURCHASE":
    case "RENEWAL":
    case "UNCANCELLATION": {
      newPaid = true;
      await superAdminDb27.execute(sql36`
        UPDATE swimming_pools
        SET x_paid_entitlement        = true,
            xmode_subscription_end_at = ${expiresAt ?? null},
            xmode_payment_failed_at   = NULL,
            xmode_purchased_at        = COALESCE(xmode_purchased_at, NOW()),
            x_auto_renew_cancelled    = false,
            updated_at                = NOW()
        WHERE id = ${poolId}
      `);
      break;
    }
    case "CANCELLATION": {
      await superAdminDb27.execute(sql36`
        UPDATE swimming_pools
        SET xmode_subscription_end_at = ${expiresAt ?? null},
            x_auto_renew_cancelled    = true,
            updated_at                = NOW()
        WHERE id = ${poolId}
      `);
      break;
    }
    case "EXPIRATION": {
      newPaid = false;
      await superAdminDb27.execute(sql36`
        UPDATE swimming_pools
        SET x_paid_entitlement        = false,
            xmode_subscription_end_at = ${expiresAt ?? null},
            updated_at               = NOW()
        WHERE id = ${poolId}
      `);
      break;
    }
    case "REFUND": {
      newPaid = false;
      await superAdminDb27.execute(sql36`
        UPDATE swimming_pools
        SET x_paid_entitlement = false,
            updated_at         = NOW()
        WHERE id = ${poolId}
      `);
      break;
    }
    case "BILLING_ISSUE": {
      await superAdminDb27.execute(sql36`
        UPDATE swimming_pools
        SET xmode_payment_failed_at = NOW(),
            updated_at              = NOW()
        WHERE id = ${poolId}
      `);
      break;
    }
    default:
      console.log(
        `[x-entitlement] \uBBF8\uC9C0\uC6D0 \uC774\uBCA4\uD2B8 \uD0C0\uC785: ${eventType} \u2014 log-only (pool=${poolId})`
      );
      return;
  }
  const afterEffective = resolveEffectiveXEntitlement({
    x_paid_entitlement: newPaid,
    x_manual_entitlement: beforeManual,
    x_force_disabled: beforeForce
  });
  if (afterEffective !== beforeEffective) {
    try {
      const versionRes = await superAdminDb27.execute(sql36`
        SELECT next_audit_version('swimming_pool_xmode', ${poolId}) AS v
      `);
      const version = versionRes.rows[0]?.v ?? 1;
      const beforeData = {
        xmode_entitlement: beforeEffective,
        // effective (backward compat key)
        x_paid_entitlement: beforePaid,
        x_manual_entitlement: beforeManual,
        x_force_disabled: beforeForce,
        xmode_config_status: currentPool.xmode_config_status,
        xmode_purchased_at: currentPool.xmode_purchased_at ?? null,
        xmode_subscription_end_at: currentPool.xmode_subscription_end_at ?? null
      };
      const afterData = {
        xmode_entitlement: afterEffective,
        // effective (backward compat key)
        x_paid_entitlement: newPaid,
        source: "revenuecat_paid",
        // X02-B2: source 명시
        event_type: eventType,
        product_id: productId,
        event_id: eventId ?? null,
        expires_at: expiresAt ?? null
      };
      await superAdminDb27.execute(sql36`
        INSERT INTO audit_logs (
          entity_type, entity_id, entity_version,
          action, actor_type, actor_id, pool_id,
          before_data, after_data, reason,
          request_id, correlation_id, ip_hash
        ) VALUES (
          'swimming_pool_xmode', ${poolId}, ${version},
          'update', 'revenuecat', ${"rc:" + (eventId ?? "unknown")}, ${poolId},
          ${JSON.stringify(beforeData)}::jsonb,
          ${JSON.stringify(afterData)}::jsonb,
          ${"RC webhook: " + eventType + (isSandbox ? " (sandbox)" : "")},
          NULL, NULL, NULL
        )
      `);
    } catch (auditErr) {
      console.error("[x-entitlement] audit_log \uAE30\uB85D \uC2E4\uD328:", auditErr.message);
    }
  }
  console.log(
    `[x-entitlement] ${eventType}: pool=${poolId} paid: ${beforePaid} \u2192 ${newPaid} effective: ${beforeEffective} \u2192 ${afterEffective}` + (isSandbox ? " [sandbox]" : "")
  );
}

// src/lib/x-billing.ts
import { superAdminDb as superAdminDb28 } from "@workspace/db";
import { sql as sql37 } from "drizzle-orm";
function resolveXProductForSequence(sequence) {
  if (sequence >= 1 && sequence <= 100) {
    return { tierKey: "tier1", discountPercent: 50, storeProductId: "com.swimnote.x.monthly.tier1" };
  }
  if (sequence >= 101 && sequence <= 300) {
    return { tierKey: "tier2", discountPercent: 30, storeProductId: "com.swimnote.x.monthly.tier2" };
  }
  if (sequence >= 301 && sequence <= 500) {
    return { tierKey: "tier3", discountPercent: 10, storeProductId: "com.swimnote.x.monthly.tier3" };
  }
  return { tierKey: "standard", discountPercent: 0, storeProductId: "com.swimnote.x.monthly.standard" };
}
var RC_V2_BASE = "https://api.revenuecat.com/v2";
async function fetchRCSubscriberEntitlement(appUserId, _entitlementId = "x_mode") {
  const secret = process.env.REVENUECAT_SECRET_API_KEY;
  const projectId = process.env.REVENUECAT_PROJECT_ID;
  if (!secret) throw new Error("REVENUECAT_SECRET_API_KEY not configured");
  if (!projectId) throw new Error("REVENUECAT_PROJECT_ID not configured");
  const headers = { Authorization: `Bearer ${secret}` };
  const customerBase = `${RC_V2_BASE}/projects/${projectId}/customers/${encodeURIComponent(appUserId)}`;
  const custResp = await fetch(customerBase, { headers });
  if (!custResp.ok) {
    if (custResp.status === 404) {
      return { entitlement: null, originalAppUserId: appUserId };
    }
    const body = await custResp.text().catch(() => "");
    throw new Error(`RC V2 customer ${custResp.status}: ${body.slice(0, 200)}`);
  }
  const custData = await custResp.json();
  const originalAppUserId = custData.original_app_user_id ?? appUserId;
  const subResp = await fetch(`${customerBase}/subscriptions`, { headers });
  if (!subResp.ok) {
    const body = await subResp.text().catch(() => "");
    throw new Error(`RC V2 subscriptions ${subResp.status}: ${body.slice(0, 200)}`);
  }
  const subData = await subResp.json();
  const xProductIds = new Set(
    (process.env.REVENUECAT_X_PRODUCT_IDS ?? "").split(",").map((s) => s.trim()).filter(Boolean)
  );
  const activeSubs = (subData.items ?? []).filter((sub) => {
    const storeId = sub.product?.store_identifier ?? "";
    return sub.gives_access === true && (xProductIds.size === 0 || xProductIds.has(storeId));
  });
  if (activeSubs.length === 0) return { entitlement: null, originalAppUserId };
  const best = activeSubs.sort((a, b) => {
    const aTs = a.current_period_end_at ? new Date(a.current_period_end_at).getTime() : 0;
    const bTs = b.current_period_end_at ? new Date(b.current_period_end_at).getTime() : 0;
    return bTs - aTs;
  })[0];
  const productId = best.product?.store_identifier ?? null;
  const expiresAt = best.current_period_end_at ?? null;
  const envStr = (best.environment ?? "").toLowerCase();
  const environment = envStr === "sandbox" ? "SANDBOX" : "PRODUCTION";
  return {
    originalAppUserId,
    entitlement: {
      isActive: true,
      // gives_access=true → active
      productIdentifier: productId,
      expiresAt,
      purchaseDate: best.purchase_date ?? null,
      originalPurchaseDate: best.original_purchase_date ?? null,
      originalTransactionId: best.original_transaction_id ?? null,
      latestTransactionId: best.store_transaction_id ?? null,
      environment
    }
  };
}
