    const [purchasedSlot] = (await superAdminDb28.execute(sql37`
      SELECT id, tier_key FROM x_subscription_slots
      WHERE pool_id = ${poolId} AND status = 'PURCHASED'
      ORDER BY purchased_at DESC LIMIT 1
    `)).rows;
