router18.post("/sync-x-subscription", requireAuth, requireRole("pool_admin"), async (req, res) => {
  try {
    const userId = req.user.userId;
    const poolId = await getPoolId7(userId);
    if (!poolId) {
      res.status(403).json({ error: "\uC18C\uC18D\uB41C \uC218\uC601\uC7A5\uC774 \uC5C6\uC2B5\uB2C8\uB2E4." });
      return;
    }
    const result = await syncXSubscription({ poolId, userId });
    res.json({ ok: true, ...result });
  } catch (err15) {
    const code = err15?.code ?? "";
    if (code === "ALREADY_SUBSCRIBED" || code === "NO_RESERVED_SLOT") {
      res.status(409).json({ error: code, message: err15.message });
      return;
    }
    if (code === "RC_ENTITLEMENT_INACTIVE") {
      res.status(422).json({ error: code, message: err15.message });
      return;
    }
    if (code === "PRODUCT_MISMATCH") {
      res.status(409).json({ error: code, message: err15.message });
      return;
    }
    if (code === "PAYMENT_DEADLINE_EXPIRED") {
      res.status(410).json({ error: code, message: err15.message });
      return;
    }
    console.error("[sync-x-subscription]", err15);
    res.status(500).json({ error: err15?.message ?? "\uB3D9\uAE30\uD654 \uC624\uB958" });
  }
});
router18.get("/x-subscription-status", requireAuth, requireRole("pool_admin"), async (req, res) => {
  try {
    const userId = req.user.userId;
    const poolId = await getPoolId7(userId);
    if (!poolId) {
      res.status(403).json({ error: "\uC18C\uC18D\uB41C \uC218\uC601\uC7A5\uC774 \uC5C6\uC2B5\uB2C8\uB2E4." });
      return;
    }
    const [pool2] = (await superAdminDb31.execute(sql40`
      SELECT x_paid_entitlement,
             x_manual_entitlement,
             x_force_disabled,
             COALESCE(x_auto_renew_cancelled, false) AS x_auto_renew_cancelled,
             xmode_subscription_end_at,
             xmode_payment_failed_at,
             xmode_purchased_at
      FROM swimming_pools
      WHERE id = ${poolId}
      LIMIT 1
    `)).rows;
    if (!pool2) {
      res.status(404).json({ error: "POOL_NOT_FOUND" });
      return;
    }
    const [slot] = (await superAdminDb31.execute(sql40`
      SELECT tier_key, franchise_number, purchased_at, updated_at
      FROM x_subscription_slots
      WHERE pool_id = ${poolId} AND status = 'PURCHASED'
      ORDER BY purchased_at DESC
      LIMIT 1
    `)).rows;
    const paid = Boolean(pool2.x_paid_entitlement);
    const manual = Boolean(pool2.x_manual_entitlement);
    const forceDisabled = Boolean(pool2.x_force_disabled);
    const autoRenewCancelled = Boolean(pool2.x_auto_renew_cancelled);
    const paymentFailed = pool2.xmode_payment_failed_at != null;
    const endAt = pool2.xmode_subscription_end_at ?? null;
    let subscription_status;
    if (forceDisabled) {
      subscription_status = "UNKNOWN";
    } else if (paid) {
      if (paymentFailed) {
        subscription_status = "BILLING_ISSUE";
      } else if (autoRenewCancelled) {
        subscription_status = "CANCELLED_BUT_ACTIVE";
      } else {
        subscription_status = "ACTIVE";
      }
    } else if (manual) {
      subscription_status = "ACTIVE";
    } else if (endAt && new Date(endAt) > /* @__PURE__ */ new Date()) {
      subscription_status = "CANCELLED_BUT_ACTIVE";
    } else if (pool2.xmode_purchased_at) {
      subscription_status = "EXPIRED";
    } else {
      subscription_status = "UNKNOWN";
    }
    const X_KRW_PRICE = {
      tier1: "\u20A975,000",
      tier2: "\u20A9105,000",
      tier3: "\u20A9135,000",
      standard: "\u20A9150,000"
    };
    const tierKey = slot?.tier_key ?? null;
    const krw_price = tierKey ? X_KRW_PRICE[tierKey] ?? null : null;
    res.json({
      subscription_status,
      tier_key: tierKey,
      krw_price,
      franchise_number: slot?.franchise_number ?? null,
      purchased_at: pool2.xmode_purchased_at ?? null,
      subscription_end_at: endAt,
      payment_failed_at: pool2.xmode_payment_failed_at ?? null,
      auto_renew_cancelled: autoRenewCancelled,
      synced_at: slot?.updated_at ?? pool2.xmode_purchased_at ?? null,
      source: paid ? "paid" : manual ? "manual" : null
    });
  } catch (err15) {
    console.error("[x-subscription-status]", err15);
    res.status(500).json({ error: "\uC11C\uBC84 \uC624\uB958\uAC00 \uBC1C\uC0DD\uD588\uC2B5\uB2C8\uB2E4." });
  }
});
router18.post("/restore-x-subscription", requireAuth, requireRole("pool_admin"), async (req, res) => {
  try {
    const userId = req.user.userId;
    const poolId = await getPoolId7(userId);
    if (!poolId) {
      res.status(403).json({ error: "\uC18C\uC18D\uB41C \uC218\uC601\uC7A5\uC774 \uC5C6\uC2B5\uB2C8\uB2E4." });
      return;
    }
    const { entitlement, originalAppUserId } = await fetchRCSubscriberEntitlement(userId, "x_mode");
    if (!entitlement || !entitlement.isActive) {
      res.status(422).json({
        error: "RC_ENTITLEMENT_INACTIVE",
        message: "\uBCF5\uC6D0 \uAC00\uB2A5\uD55C X \uAD6C\uB3C5\uC774 \uC5C6\uC2B5\uB2C8\uB2E4."
      });
      return;
    }
    await superAdminDb31.execute(sql40`
      UPDATE swimming_pools
      SET x_paid_entitlement        = true,
          xmode_subscription_end_at = ${entitlement.expiresAt ?? null},
          xmode_payment_failed_at   = NULL,
          xmode_purchased_at        = COALESCE(xmode_purchased_at, NOW()),
          x_auto_renew_cancelled    = false,
          updated_at                = NOW()
      WHERE id = ${poolId}
    `);
    await auditXEvent({
      action: "x_restore",
      poolId,
      actorId: userId,
      before: {},
      after: {
        x_paid_entitlement: true,
        source: "restore",
        rc_user: originalAppUserId,
        expires_at: entitlement.expiresAt ?? null
      },
      reason: "pool_admin \uAD6C\uB9E4 \uBCF5\uC6D0: RC x_mode entitlement \uC11C\uBC84 \uD655\uC778 \uD6C4 \uD65C\uC131\uD654"
    });
    console.log(`[restore-x-subscription] pool=${poolId} user=${userId} expires=${entitlement.expiresAt}`);
    res.json({ ok: true, expires_at: entitlement.expiresAt ?? null });
  } catch (err15) {
    const code = err15?.code ?? "";
    if (code === "RC_ENTITLEMENT_INACTIVE") {
      res.status(422).json({ error: code, message: err15.message });
      return;
    }
    console.error("[restore-x-subscription]", err15);
    res.status(500).json({ error: err15?.message ?? "\uBCF5\uC6D0 \uC624\uB958" });
  }
});
