router18.post("/cron/cleanup-deactivated", async (req, res) => {
  const cronSecret = process.env.CRON_SECRET ?? process.env.JWT_SECRET ?? "";
  const authHeader2 = req.headers.authorization ?? "";
  if (cronSecret && authHeader2 !== `Bearer ${cronSecret}`) {
    res.status(401).json({ error: "unauthorized" });
    return;
  }
  try {
    const expiredPools = (await superAdminDb31.execute(sql40`
      SELECT id, name FROM swimming_pools
      WHERE deletion_scheduled_at IS NOT NULL
        AND deletion_scheduled_at <= NOW()
      LIMIT 50
    `)).rows;
    if (expiredPools.length === 0) {
      res.json({ ok: true, deleted: 0, message: "\uC0AD\uC81C \uB300\uC0C1 \uC5C6\uC74C" });
      return;
    }
    let deletedCount = 0;
    for (const pool2 of expiredPools) {
      try {
        const poolId = pool2.id;
        await db26.execute(sql40`DELETE FROM students WHERE swimming_pool_id = ${poolId}`).catch(() => {
        });
        await superAdminDb31.execute(sql40`DELETE FROM parent_accounts WHERE swimming_pool_id = ${poolId}`).catch(() => {
        });
        await superAdminDb31.execute(sql40`DELETE FROM teacher_invites WHERE swimming_pool_id = ${poolId}`).catch(() => {
        });
        await superAdminDb31.execute(sql40`DELETE FROM policy_consents WHERE pool_id = ${poolId}`).catch(() => {
        });
        await superAdminDb31.execute(sql40`DELETE FROM pool_subscriptions WHERE swimming_pool_id = ${poolId}`).catch(() => {
        });
        await superAdminDb31.execute(sql40`DELETE FROM users WHERE swimming_pool_id = ${poolId}`).catch(() => {
        });
        await superAdminDb31.execute(sql40`DELETE FROM swimming_pools WHERE id = ${poolId}`).catch(() => {
        });
        console.log(`[cron/cleanup] \uD480 \uC601\uAD6C \uC0AD\uC81C \uC644\uB8CC: ${poolId} (${pool2.name})`);
        deletedCount++;
        Promise.resolve().then(() => (init_opsAlerts(), opsAlerts_exports)).then(({ createOpsAlert: createOpsAlert2 }) => {
          createOpsAlert2({
            type: "pool_permanently_deleted",
            title: "\uC218\uC601\uC7A5 \uC601\uAD6C \uC0AD\uC81C",
            message: `${pool2.name ?? poolId} \uC218\uC601\uC7A5\uC774 90\uC77C \uC720\uC608 \uB9CC\uB8CC\uB85C \uC601\uAD6C \uC0AD\uC81C\uB418\uC5C8\uC2B5\uB2C8\uB2E4.`,
            severity: "warning",
            relatedPoolId: poolId
          }).catch(console.error);
        }).catch(console.error);
      } catch (e) {
        console.error(`[cron/cleanup] \uD480 \uC0AD\uC81C \uC624\uB958 ${pool2.id}:`, e.message);
      }
    }
    res.json({ ok: true, deleted: deletedCount, pools: expiredPools.map((p) => p.id) });
  } catch (e) {
    console.error("[cron/cleanup] \uD06C\uB860 \uC624\uB958:", e);
    res.status(500).json({ error: e.message });
  }
});
