var router19 = Router19();
function genId3(prefix) {
  return `${prefix}_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}
function generateInviteCode2() {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  return Array.from({ length: 8 }, () => chars[Math.floor(Math.random() * chars.length)]).join("");
}
var _messagesTableReady = false;
async function ensureMessagesTable() {
  if (_messagesTableReady) return;
  await db27.execute(sql41`
    CREATE TABLE IF NOT EXISTS parent_request_messages (
      id TEXT PRIMARY KEY DEFAULT (gen_random_uuid()::text),
      request_id TEXT NOT NULL,
      swimming_pool_id TEXT NOT NULL,
      sender_type TEXT NOT NULL,
      sender_id TEXT,
      message_type TEXT NOT NULL DEFAULT 'message',
      content TEXT NOT NULL,
      is_read_by_teacher BOOLEAN DEFAULT false,
      is_read_by_parent BOOLEAN DEFAULT false,
      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
    )
  `).catch(() => {
  });
  _messagesTableReady = true;
}
var REQUEST_TYPE_NAMES = {
  absence: "\uACB0\uC11D \uC2E0\uCCAD",
  makeup: "\uBCF4\uAC15 \uC694\uCCAD",
  postpone: "\uC5F0\uAE30 \uC2E0\uCCAD",
  withdrawal: "\uD1F4\uC6D0 \uC2E0\uCCAD",
  counseling: "\uC0C1\uB2F4 \uC694\uCCAD",
  inquiry: "\uBB38\uC758"
};
async function insertSystemMessage(requestId, poolId, content) {
  await ensureMessagesTable();
  const id = `prm_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`;
  await db27.execute(sql41`
    INSERT INTO parent_request_messages
    (id, request_id, swimming_pool_id, sender_type, sender_id, message_type, content, is_read_by_teacher, is_read_by_parent)
    VALUES (${id}, ${requestId}, ${poolId}, 'system', NULL, 'system', ${content}, true, true)
  `).catch(() => {
  });
}
function _abbreviateAddr(address) {
  if (!address) return "";
  const parts = address.trim().split(/\s+/);
  if (parts.length === 0) return "";
  const first = parts[0];
  if (first.endsWith("\uB3C4")) return parts.slice(0, Math.min(3, parts.length)).join(" ");
  if (first.endsWith("\uC2DC")) return parts.slice(0, Math.min(2, parts.length)).join(" ");
  return parts.slice(0, Math.min(2, parts.length)).join(" ");
}
router19.get("/pools/public-search", async (req, res) => {
  const q = (req.query.name || "").trim();
  if (!q) {
    res.json({ success: true, data: [] });
    return;
  }
  try {
    const results = await superAdminDb32.select({
      id: swimmingPoolsTable5.id,
      name: swimmingPoolsTable5.name,
      address: swimmingPoolsTable5.address
    }).from(swimmingPoolsTable5).where(and11(
      sql41`approval_status = 'approved'`,
      ilike(swimmingPoolsTable5.name, `${q}%`)
    )).orderBy(
      sql41`CASE WHEN LOWER(name) = LOWER(${q}) THEN 0 ELSE 1 END`,
      sql41`LENGTH(name)`,
      swimmingPoolsTable5.name
    ).limit(20);
    const data = results.map((r) => ({
      id: r.id,
      name: r.name,
      address: _abbreviateAddr(r.address)
    }));
    res.json({ success: true, data });
  } catch (err15) {
    console.error(err15);
    res.status(500).json({ success: false, data: [] });
  }
});
