router19.patch(
  "/parent-requests/:id",
  requireAuth,
  requireRole("pool_admin", "sub_admin", "teacher", "super_admin"),
  async (req, res) => {
    try {
      const { status, admin_note } = req.body;
      if (!["done", "rejected", "pending"].includes(status)) {
        res.status(400).json({ success: false, message: "status\uB294 done, rejected, pending \uC911 \uD558\uB098\uC5EC\uC57C \uD569\uB2C8\uB2E4." });
        return;
      }
      const [me] = await superAdminDb32.select({ swimming_pool_id: usersTable14.swimming_pool_id }).from(usersTable14).where(eq16(usersTable14.id, req.user.userId)).limit(1);
      if (!me?.swimming_pool_id) {
        res.status(403).json({ success: false, message: "\uC18C\uC18D \uC218\uC601\uC7A5 \uC5C6\uC74C" });
        return;
      }
      const [reqRow] = await db27.execute(sql41`
        SELECT parent_id, request_type, student_id, status AS prev_status FROM parent_student_requests
        WHERE id = ${req.params.id} AND swimming_pool_id = ${me.swimming_pool_id}
        LIMIT 1
      `).then((r) => r.rows);
      await db27.execute(sql41`
        ALTER TABLE parent_student_requests
        ADD COLUMN IF NOT EXISTS is_read_by_teacher BOOLEAN DEFAULT false
      `).catch(() => {
      });
      await db27.execute(sql41`
        UPDATE parent_student_requests
        SET status = ${status},
            is_read_by_teacher = true,
            updated_at = NOW()
        WHERE id = ${req.params.id} AND swimming_pool_id = ${me.swimming_pool_id}
      `);
      const statusChanged = reqRow?.prev_status !== status;
      if (reqRow && status !== "pending" && statusChanged) {
        const typeNameSys = REQUEST_TYPE_NAMES[reqRow.request_type] || "\uC694\uCCAD";
        const sysMsgContent = status === "done" ? `${typeNameSys}\uC774 \uCC98\uB9AC\uB410\uC2B5\uB2C8\uB2E4.` : `${typeNameSys}\uC744 \uCC98\uB9AC\uD558\uC9C0 \uBABB\uD588\uC2B5\uB2C8\uB2E4.`;
        await insertSystemMessage(req.params.id, me.swimming_pool_id, sysMsgContent);
      }
      if (reqRow?.parent_id && status !== "pending" && statusChanged) {
        const TYPE_LABELS = {
          absence: "\uACB0\uC11D",
          makeup: "\uBCF4\uAC15",
          postpone: "\uC5F0\uAE30",
          withdrawal: "\uD1F4\uC6D0",
          counseling: "\uC0C1\uB2F4",
          inquiry: "\uBB38\uC758"
        };
        const typeLabel = TYPE_LABELS[reqRow.request_type] || "\uC218\uC5C5";
        const pushTitle = status === "done" ? `${typeLabel} \uC694\uCCAD\uC774 \uCC98\uB9AC\uB410\uC2B5\uB2C8\uB2E4` : `${typeLabel} \uC694\uCCAD\uC774 \uAC70\uC808\uB410\uC2B5\uB2C8\uB2E4`;
        const pushBody = status === "done" ? "\uC120\uC0DD\uB2D8\uC774 \uC694\uCCAD\uC744 \uD655\uC778\uD558\uACE0 \uCC98\uB9AC\uD588\uC2B5\uB2C8\uB2E4." : admin_note ? `\uAC70\uC808 \uC0AC\uC720: ${admin_note}` : "\uC694\uCCAD\uC774 \uAC70\uC808\uB410\uC2B5\uB2C8\uB2E4. \uC218\uC601\uC7A5\uC5D0 \uBB38\uC758\uD574\uC8FC\uC138\uC694.";
        try {
          const notifId = `notif_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`;
          await db27.execute(sql41`
            INSERT INTO notifications (id, recipient_id, recipient_type, type, title, body, ref_id, ref_type, pool_id, is_read)
            SELECT ${notifId}, ${reqRow.parent_id}, 'parent_account',
                   'parent_request_result', ${pushTitle}, ${pushBody},
                   ${req.params.id}, 'request', ${me.swimming_pool_id}, false
            WHERE NOT EXISTS (
              SELECT 1 FROM notifications
              WHERE type = 'parent_request_result'
                AND ref_id = ${req.params.id}
                AND recipient_id = ${reqRow.parent_id}
                AND created_at > NOW() - INTERVAL '1 hour'
            )
          `);
        } catch (notifErr) {
          console.error("[parent-requests PATCH notification error]", notifErr);
        }
        try {
          const { sendPushToUser: sendPushToUser2 } = await Promise.resolve().then(() => (init_push_service(), push_service_exports));
          await sendPushToUser2(
            reqRow.parent_id,
            true,
            "parent_request_result",
            pushTitle,
            pushBody,
            { requestId: req.params.id },
            `req_result_${req.params.id}`
          );
        } catch (pushErr) {
          console.error("[parent-requests PATCH push error]", pushErr);
        }
      }
      res.json({ success: true });
    } catch (err15) {
      console.error(err15);
      res.status(500).json({ success: false, message: "\uC11C\uBC84 \uC624\uB958" });
    }
  }
);
