function pgTextArrayLiteral(arr) {
  if (arr.length === 0) return "'{}'::text[]";
  const escaped = arr.map((s) => `"${String(s).replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`);
  return `'{${escaped.join(",")}}'::text[]`;
}
