async function runAutoBackup() {
  const locked = await acquireLock("backup-auto", 7200);
  if (!locked) {
    console.log("[auto-backup] \uB2E4\uB978 \uC11C\uBC84\uAC00 \uBC31\uC5C5 \uC2E4\uD589 \uC911 \u2014 \uC2A4\uD0B5");
    return;
  }
  const settings = await getBackupSettings();
  if (!settings.auto_enabled) {
    console.log("[auto-backup] \uC790\uB3D9 \uBC31\uC5C5 \uBE44\uD65C\uC131\uD654\uB428 \u2014 \uAC74\uB108\uB700");
    await releaseLock("backup-auto");
    return;
  }
  const refreshInterval = setInterval(() => {
    refreshLock("backup-auto", 7200).catch(() => {
    });
  }, 10 * 60 * 1e3);
  console.log("[auto-backup] \uC790\uB3D9 \uBC31\uC5C5 \uC2DC\uC791 \u2192", (/* @__PURE__ */ new Date()).toISOString());
  try {
    const result = await runRealBackup({
      type: "auto",
      createdBy: "system",
      note: `\uC790\uB3D9 \uBC31\uC5C5 (${settings.schedule_type})`
    });
    console.log(`[auto-backup] Object Storage \uC644\uB8CC \u2014 id: ${result.backupId}, size: ${(result.sizeBytes / 1024 / 1024).toFixed(2)}MB`);
    if (isDbSeparated) {
      const backupDb = getBackupDb();
      runBackupToTarget({
        target: "pool",
        targetDb: backupDb,
        createdBy: "system",
        note: `\uC790\uB3D9 \uBC31\uC5C5 (${settings.schedule_type})`,
        backupType: "auto"
      }).catch((e) => console.error("[auto-backup] pool \uBC31\uC5C5 \uC2E4\uD328:", e.message));
    }
    if (backupProtectDb) {
      runBackupToTarget({
        target: "super_protect",
        targetDb: backupProtectDb,
        createdBy: "system",
        note: `\uC790\uB3D9 \uBCF4\uD638\uBC31\uC5C5 (${settings.schedule_type})`,
        backupType: "auto"
      }).catch((e) => console.error("[auto-backup] \uBCF4\uD638\uBC31\uC5C5 \uC2E4\uD328:", e.message));
    }
    await cleanupOldAutoBackups(settings.retention_days);
    await recordHeartbeat("backup-auto", { schedule_type: settings.schedule_type, status: "success" });
  } catch (err15) {
    console.error("[auto-backup] \uC2E4\uD328:", err15);
    await recordHeartbeat("backup-auto", { status: "error", error: String(err15) }).catch(() => {
    });
  } finally {
    clearInterval(refreshInterval);
    await releaseLock("backup-auto");
  }
}
function startBackupJobs() {
  cron2.schedule("0 3 * * *", async () => {
    try {
      await runIncrementalSync();
    } catch (e) {
      console.error("[cron] \uC99D\uBD84 \uB3D9\uAE30\uD654 \uC624\uB958:", e);
    }
  }, { timezone: "Asia/Seoul" });
  cron2.schedule("0 * * * *", async () => {
    try {
      const settings = await getBackupSettings();
      if (!settings.auto_enabled) return;
      const now = new Date((/* @__PURE__ */ new Date()).toLocaleString("en-US", { timeZone: "Asia/Seoul" }));
      const h = now.getHours();
      const shouldRun = (() => {
        switch (settings.schedule_type) {
          case "every_6h":
            return h % 6 === settings.run_hour % 6;
          case "every_12h":
            return h % 12 === settings.run_hour % 12;
          case "weekly":
            return now.getDay() === 0 && h === settings.run_hour;
          case "daily":
          default:
            return h === settings.run_hour;
        }
      })();
      if (shouldRun) {
        console.log(`[cron] \uC790\uB3D9 \uBC31\uC5C5 \uC2E4\uD589 (${settings.schedule_type}, ${h}:00)`);
        await runAutoBackup();
      }
    } catch (e) {
      console.error("[cron] \uC790\uB3D9 \uBC31\uC5C5 \uCCB4\uD06C \uC624\uB958:", e);
    }
  }, { timezone: "Asia/Seoul" });
  console.log("[backup-batch] \uBC30\uCE58 \uC7A1 \uB4F1\uB85D \uC644\uB8CC (\uC99D\uBD84: \uB9E4\uC77C 03:00 / \uC790\uB3D9\uBC31\uC5C5: \uC124\uC815 \uAE30\uBC18)");
}

