router36.get(
  "/super/storage/:poolId",
  requireAuth,
  requireRole("super_admin"),
  async (req, res) => {
    try {
      const { poolId } = req.params;
      const [pool2] = (await superAdminDb49.execute(sql61`
        SELECT id, name,
          COALESCE(storage_mb, 512)         AS storage_mb,
          COALESCE(display_storage, '500MB') AS display_storage,
          used_storage_bytes,
          upload_blocked
        FROM swimming_pools WHERE id = ${poolId}
      `)).rows;
      if (!pool2) {
        res.status(404).json({ error: "\uC218\uC601\uC7A5 \uC5C6\uC74C" });
        return;
      }
      const storageMb = Number(pool2.storage_mb || 512);
      const usedBytes = Number(pool2.used_storage_bytes || 0);
      const totalBytes = storageMb * 1048576;
      const usagePct = totalBytes > 0 ? Math.min(Math.round(usedBytes / totalBytes * 100), 100) : 0;
      res.json({ ...pool2, usage_pct: usagePct, is_near_limit: usagePct >= 95 });
    } catch (err15) {
      console.error(err15);
      res.status(500).json({ error: "\uC11C\uBC84 \uC624\uB958" });
    }
  }
);
