router36.patch(
  "/super/global-template-sets/:id/activate",
  requireAuth,
  requireRole("super_admin"),
  async (req, res) => {
    const { id } = req.params;
    try {
      const result = await superAdminDb49.transaction(async (tx) => {
        const targetRes = await tx.execute(sql61`
          SELECT * FROM global_template_sets WHERE id = ${id}
        `);
        const target = targetRes.rows[0];
        if (!target) throw Object.assign(new Error("NOT_FOUND"), { status: 404 });
        if (target.status === "ACTIVE") throw Object.assign(new Error("ALREADY_ACTIVE"), { status: 409 });
        if (target.status === "ARCHIVED") throw Object.assign(new Error("ARCHIVED_CANNOT_ACTIVATE"), { status: 409 });
        const prevActiveRes = await tx.execute(sql61`
          UPDATE global_template_sets
          SET status = 'ARCHIVED', archived_at = NOW()
          WHERE status = 'ACTIVE'
          RETURNING id, status
        `);
        const prevActive = prevActiveRes.rows[0];
        const updatedRes = await tx.execute(sql61`
          UPDATE global_template_sets
          SET status = 'ACTIVE', activated_at = NOW()
          WHERE id = ${id}
          RETURNING *
        `);
        return { updated: updatedRes.rows[0], prevActiveId: prevActive?.id ?? null };
      });
      const actorId = req.user.userId;
      await auditGlobalTemplateSet(
        superAdminDb49,
        "GLOBAL_TEMPLATE_SET_ACTIVATED",
        id,
        actorId,
        { status: "DRAFT" },
        { status: "ACTIVE" }
      );
      if (result.prevActiveId) {
        await auditGlobalTemplateSet(
          superAdminDb49,
          "GLOBAL_TEMPLATE_SET_ARCHIVED",
          result.prevActiveId,
          actorId,
          { status: "ACTIVE" },
          { status: "ARCHIVED" },
          "auto-archived by new activation"
        );
      }
      const countRes = await superAdminDb49.execute(sql61`
        SELECT COUNT(*)::int AS n FROM global_template_sets WHERE status = 'ACTIVE'
      `);
      const activeCount = Number(countRes.rows[0].n);
      res.json({ ok: true, set: result.updated, active_count_verified: activeCount });
    } catch (err15) {
      const status = err15.status ?? 500;
      const msg = err15.message;
      if (msg === "NOT_FOUND") {
        res.status(404).json({ error: "NOT_FOUND", message: "\uC874\uC7AC\uD558\uC9C0 \uC54A\uB294 \uD15C\uD50C\uB9BF \uC138\uD2B8" });
        return;
      }
      if (msg === "ALREADY_ACTIVE") {
        res.status(409).json({ error: "ALREADY_ACTIVE", message: "\uC774\uBBF8 ACTIVE \uC0C1\uD0DC\uC785\uB2C8\uB2E4." });
        return;
      }
      if (msg === "ARCHIVED_CANNOT_ACTIVATE") {
        res.status(409).json({ error: "ARCHIVED_CANNOT_ACTIVATE", message: "ARCHIVED \uC138\uD2B8\uB294 \uD65C\uC131\uD654\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4." });
        return;
      }
      res.status(status).json({ error: msg });
    }
  }
);
