async function getDbSize(dbConn, label) {
  try {
    const [row] = (await dbConn.execute(sql67`
      SELECT pg_database_size(current_database())::bigint AS bytes,
             current_database()                           AS db_name,
             pg_size_pretty(pg_database_size(current_database())) AS pretty
    `)).rows;
    return {
      label,
      db_name: row?.db_name ?? "unknown",
      total_bytes: Number(row?.bytes ?? 0),
      total_mb: Math.round(Number(row?.bytes ?? 0) / 1024 / 1024 * 10) / 10,
      pretty: row?.pretty ?? "0 bytes"
    };
  } catch (e) {
    return { label, db_name: "error", total_bytes: 0, total_mb: 0, pretty: "0 bytes", error: String(e) };
  }
}
async function getTableSizes(dbConn) {
  try {
    const rows = (await dbConn.execute(sql67`
      SELECT
        tablename,
        pg_total_relation_size(quote_ident(tablename))::bigint AS bytes,
        pg_size_pretty(pg_total_relation_size(quote_ident(tablename))) AS pretty,
        pg_size_pretty(pg_relation_size(quote_ident(tablename)))       AS data_size,
        pg_size_pretty(pg_total_relation_size(quote_ident(tablename))
          - pg_relation_size(quote_ident(tablename)))                  AS index_size
      FROM pg_tables
      WHERE schemaname = 'public'
      ORDER BY bytes DESC
      LIMIT 30
    `)).rows;
    return rows.map((r) => ({
      table: r.tablename,
      bytes: Number(r.bytes),
      pretty: r.pretty,
      data_size: r.data_size,
      index_size: r.index_size
    }));
  } catch {
    return [];
  }
}
async function getPoolBreakdown() {
  try {
    const rows = (await superAdminDb54.execute(sql67`
      SELECT
        p.id                         AS pool_id,
        p.name                       AS pool_name,
        COUNT(DISTINCT s.id)::int    AS student_count,
        COUNT(DISTINCT u.id)::int    AS teacher_count,
        COUNT(DISTINCT a.id)::int    AS attendance_count,
        COUNT(DISTINCT cd.id)::int   AS diary_count
      FROM swimming_pools p
      LEFT JOIN students    s  ON s.swimming_pool_id = p.id AND s.status = 'active'
      LEFT JOIN users       u  ON u.swimming_pool_id = p.id AND 'teacher' = ANY(u.roles)
      LEFT JOIN attendance  a  ON a.swimming_pool_id = p.id
      LEFT JOIN class_diaries cd ON cd.swimming_pool_id = p.id AND cd.is_deleted = false
      GROUP BY p.id, p.name
      ORDER BY student_count DESC
    `)).rows;
    return rows;
  } catch {
    return [];
  }
}
async function pingDb(dbConn, label) {
  const t0 = Date.now();
  try {
    await dbConn.execute(sql67`SELECT 1`);
    return { label, ok: true, latency_ms: Date.now() - t0 };
  } catch (e) {
    return { label, ok: false, latency_ms: Date.now() - t0, error: String(e) };
  }
}
