async function runDbHealthCheck() {
  try {
    await ensureHealthLogTable();
    const mainPing = await pingDb3(superAdminDb56, "main");
    await writeHealthLog(
      "main_db",
      mainPing.ok ? mainPing.latency_ms > 500 ? "slow" : "ok" : "failed",
      mainPing.latency_ms,
      mainPing.error
    );
    if (!mainPing.ok) {
      const fails = await getConsecutiveFailures("main_db");
      if (fails >= 2) {
        await fireAlert(
          "critical",
          "\u{1F534} \uC6B4\uC601 DB \uC5F0\uACB0 \uBD88\uAC00",
          `superAdminDb \uC751\uB2F5 \uC5C6\uC74C \u2014 \uC5F0\uC18D ${fails}\uD68C \uC2E4\uD328 (${(/* @__PURE__ */ new Date()).toLocaleString("ko-KR")})`
        );
      }
    }
    if (!isDbSeparated4) return;
    if (!checkStandbyCircuit()) return;
    const backupDb = getBackupDb4();
    if (!backupDb) return;
    const standbyPing = await pingDb3(backupDb, "standby");
    recordStandbyPingResult(standbyPing.latency_ms, standbyPing.ok);
    await writeHealthLog(
      "standby_db",
      standbyPing.ok ? standbyPing.latency_ms > 800 ? "slow" : "ok" : "failed",
      standbyPing.latency_ms,
      standbyPing.error
    );
    if (!standbyPing.ok) {
      const fails = await getConsecutiveFailures("standby_db");
      if (fails >= 3) {
        await fireAlert(
          "warning",
          "\u{1F7E1} \uC2A4\uD0E0\uBC14\uC774 DB \uC751\uB2F5 \uC5C6\uC74C",
          `pool backup DB \uC5F0\uACB0 \uBD88\uAC00 \u2014 \uC5F0\uC18D ${fails}\uD68C \uC2E4\uD328. \uC7A5\uC560 \uC2DC \uC790\uB3D9 \uBCF5\uAD6C \uBD88\uAC00 \uC0C1\uD0DC.`
        );
      }
    }
  } catch (e) {
    console.error("[standby-sync] \uD5EC\uC2A4 \uCCB4\uD06C \uC624\uB958:", e.message);
  }
}
var standbyCircuitOpenUntil = 0;
var standbySlowStreak = 0;
var CIRCUIT_SLOW_THRESHOLD_MS = 2e3;
var CIRCUIT_OPEN_STREAK = 3;
var CIRCUIT_OPEN_DURATION_MS = 30 * 60 * 1e3;
function checkStandbyCircuit() {
  if (standbyCircuitOpenUntil > 0 && Date.now() < standbyCircuitOpenUntil) return false;
  if (standbyCircuitOpenUntil > 0) {
    standbyCircuitOpenUntil = 0;
    standbySlowStreak = 0;
    console.log("[standby-sync] \uC11C\uD0B7\uBE0C\uB808\uC774\uCEE4 \uBCF5\uAD6C \u2014 \uC2A4\uD0E0\uBC14\uC774 \uCCB4\uD06C \uC7AC\uAC1C");
  }
  return true;
}
function recordStandbyPingResult(latency_ms, ok) {
  if (!ok || latency_ms >= CIRCUIT_SLOW_THRESHOLD_MS) {
    standbySlowStreak++;
    if (standbySlowStreak >= CIRCUIT_OPEN_STREAK && standbyCircuitOpenUntil === 0) {
      standbyCircuitOpenUntil = Date.now() + CIRCUIT_OPEN_DURATION_MS;
      console.warn(`[standby-sync] \uC11C\uD0B7\uBE0C\uB808\uC774\uCEE4 \uC624\uD508 \u2014 \uC2A4\uD0E0\uBC14\uC774 DB \uC5F0\uC18D ${standbySlowStreak}\uD68C \uB290\uB9BC (${latency_ms}ms). 30\uBD84\uAC04 \uC2A4\uD0B5.`);
    }
  } else {
    standbySlowStreak = 0;
  }
}
