function checkServerMemory() {
  const mem = process.memoryUsage();
  const LIMIT = 2 * 1024 * 1024 * 1024;
  const rssPct = mem.rss / LIMIT * 100;
  const status = rssPct > 85 ? "error" : rssPct > 70 ? "warning" : "normal";
  const rssMB = Math.round(mem.rss / (1024 * 1024));
  const heapMB = Math.round(mem.heapUsed / (1024 * 1024));
  const totalMB = Math.round(mem.heapTotal / (1024 * 1024));
  return {
    rssBytes: mem.rss,
    heapUsedBytes: mem.heapUsed,
    heapTotalBytes: mem.heapTotal,
    containerLimitBytes: LIMIT,
    rssPct: Math.round(rssPct * 10) / 10,
    status,
    note: `RSS ${rssMB} MB / 2048 MB  \xB7  \uD799 ${heapMB} / ${totalMB} MB`
  };
}
