            body: root.is_deleted ? "(\uC0AD\uC81C\uB41C \uB313\uAE00\uC785\uB2C8\uB2E4)" : root.body,
            replies: replies.map((r) => ({ ...r, body: r.is_deleted ? "(\uC0AD\uC81C\uB41C \uB313\uAE00\uC785\uB2C8\uB2E4)" : r.body }))
