// src/routes/resolution-router.ts
import { Router as Router61 } from "express";

// src/lib/support-resolver.ts
import { superAdminDb as superAdminDb73 } from "@workspace/db";
import { sql as sql87 } from "drizzle-orm";
var HIGH_CONFIDENCE = 60;
function tokenize3(s) {
  return s.toLowerCase().replace(/[^\w\s가-힣]/g, " ").split(/\s+/).filter((t) => t.length >= 2);
}
function roleMatches2(row, role) {
  if (row.affected_roles?.length) return row.affected_roles.includes(role);
  if (!row.affected_role || row.affected_role === "all") return true;
  return row.affected_role === role;
}
function modeMatches2(row, mode) {
  if (row.affected_modes?.length) return row.affected_modes.includes(mode);
  if (!row.affected_mode || row.affected_mode === "all") return true;
  return row.affected_mode === mode;
}
function scoreText(row, qLower, tokens) {
  if (row.question && row.question.toLowerCase() === qLower) return 90;
  if (row.title.toLowerCase() === qLower) return 85;
  if (row.question && row.question.toLowerCase().includes(qLower)) return 78;
  if (row.title.toLowerCase().includes(qLower)) return 72;
  if (qLower.length > 2 && row.content.toLowerCase().includes(qLower)) return 65;
  const titleTokens = tokenize3(row.title);
  const contentTokens = tokenize3(row.content + " " + (row.question ?? ""));
  const overlap = tokens.filter(
    (t) => titleTokens.includes(t) || contentTokens.includes(t)
  ).length;
  if (tokens.length > 0 && overlap / tokens.length >= 0.5) return 55;
  return 0;
}
async function logResolverEvent(eventType, meta) {
  try {
    const id = `ev_rr_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`;
    await superAdminDb73.execute(sql87`
      INSERT INTO event_logs (id, category, action, metadata, created_at)
      VALUES (
        ${id},
        'SUPPORT',
        ${eventType},
        ${JSON.stringify({
      source_id: meta.source_id ?? null,
      role: meta.role ?? null,
      mode: meta.mode ?? null,
      pool_id: meta.pool_id ?? null,
      screen_id: meta.screen_id ?? null,
      category: meta.category ?? null,
      feature: meta.feature ?? null
    })}::jsonb,
        NOW()
      )
    `);
  } catch {
  }
}
async function queryKnowledge(itemType, ctx) {
  const isArray = Array.isArray(itemType);
  const rows = await superAdminDb73.execute(
    isArray ? sql87`
        SELECT id, item_type, scope, pool_id, category, feature,
               affected_role, affected_mode, affected_roles, affected_modes,
               title, content, question, answer, deep_link,
               frontend_screen_id, solution_steps, conditions, incident_id,
               status, usage_count
        FROM support_knowledge_items
        WHERE status = 'active'
          AND item_type IN ('FAQ', 'KNOWLEDGE')
          AND (scope = 'global' OR (scope = 'pool' AND pool_id = ${ctx.poolId}))
        ORDER BY usage_count DESC
        LIMIT 200
      ` : itemType === "RULE" ? sql87`
        SELECT id, item_type, scope, pool_id, category, feature,
               affected_role, affected_mode, affected_roles, affected_modes,
               title, content, question, answer, deep_link,
               frontend_screen_id, solution_steps, conditions, incident_id,
               status, usage_count
        FROM support_knowledge_items
        WHERE status = 'active'
          AND item_type = 'RULE'
          AND (scope = 'global' OR (scope = 'pool' AND pool_id = ${ctx.poolId}))
        ORDER BY usage_count DESC
        LIMIT 100
      ` : itemType === "SOLUTION" ? sql87`
        SELECT id, item_type, scope, pool_id, category, feature,
               affected_role, affected_mode, affected_roles, affected_modes,
               title, content, question, answer, deep_link,
               frontend_screen_id, solution_steps, conditions, incident_id,
               status, usage_count
        FROM support_knowledge_items
        WHERE status = 'active'
          AND item_type = 'SOLUTION'
          AND (scope = 'global' OR (scope = 'pool' AND pool_id = ${ctx.poolId}))
        ORDER BY usage_count DESC
        LIMIT 100
      ` : sql87`
        SELECT id, item_type, scope, pool_id, category, feature,
               affected_role, affected_mode, affected_roles, affected_modes,
               title, content, question, answer, deep_link,
               frontend_screen_id, solution_steps, conditions, incident_id,
               status, usage_count
        FROM support_knowledge_items
        WHERE status = 'active'
          AND item_type = 'KNOWN_ISSUE'
          AND incident_id IS NOT NULL
          AND (scope = 'global' OR (scope = 'pool' AND pool_id = ${ctx.poolId}))
        ORDER BY usage_count DESC
        LIMIT 50
      `
  );
  return rows.rows ?? [];
}
async function tryRule(ctx) {
  const candidates = await queryKnowledge("RULE", ctx);
  const eligible = candidates.filter(
    (r) => roleMatches2(r, ctx.role) && modeMatches2(r, ctx.mode)
  );
  for (const row of eligible) {
    const score = scoreText(row, ctx.qLower, ctx.tokens);
    if (score >= HIGH_CONFIDENCE) {
      await logResolverEvent("RULE_HIT", {
        source_id: row.id,
        role: ctx.role,
        mode: ctx.mode,
        pool_id: ctx.poolId,
        category: row.category,
        feature: row.feature
      });
      return {
        resolution_status: "RESOLVED",
        source_type: "RULE",
        source_id: row.id,
        confidence: score,
        title: row.title,
        answer: row.answer ?? row.content,
        solution_steps: row.solution_steps ?? null,
        screen_id: row.frontend_screen_id ?? null,
        deep_link: row.deep_link ?? null,
        requires_human: false,
        llm_required: false
      };
    }
  }
  return null;
}
var SUBSCRIPTION_KW = ["\uAD6C\uB3C5", "subscription", "\uACB0\uC81C", "payment", "plan", "\uD50C\uB79C", "\uB9CC\uB8CC", "expire", "cancel", "\uCDE8\uC18C"];
var X_KW = ["x\uBAA8\uB4DC", "x mode", "xmode", "x \uD65C\uC131", "x \uAE30\uB2A5", "x \uCEE4\uB9AC\uD058\uB7FC", "x curriculum", "x_mode", "x-mode"];
var REPORT_KW = ["\uB9AC\uD3EC\uD2B8", "report", "\uC131\uC7A5 \uB9AC\uD3EC\uD2B8", "growth report", "\uC0DD\uC131 \uC911", "pending report"];
