async function runResolutionChain(ctx) {
  return await tryRule(ctx) ?? await tryDbState(ctx) ?? await trySolution(ctx) ?? await tryFrontendMap(ctx) ?? await tryFaqKnowledge(ctx) ?? await tryKnownIssue(ctx) ?? await buildNoMatch(ctx);
}
async function gatherEvidence(ctx, maxItems = 5) {
  try {
    const rows = await superAdminDb73.execute(sql87`
      SELECT id, item_type, title, content, question, answer,
             affected_role, affected_mode, affected_roles, affected_modes,
             scope, pool_id, status, usage_count,
             null::text AS deep_link, null::text AS frontend_screen_id,
             null::jsonb AS solution_steps, null::jsonb AS conditions,
             null::text AS incident_id,
             null::text AS category, null::text AS feature
      FROM support_knowledge_items
      WHERE status = 'active'
        AND item_type IN ('FAQ', 'KNOWLEDGE', 'RULE', 'SOLUTION')
        AND (scope = 'global' OR (scope = 'pool' AND pool_id = ${ctx.poolId}))
      ORDER BY usage_count DESC
      LIMIT 100
    `);
    const candidates = rows.rows ?? [];
    const eligible = candidates.filter(
      (r) => roleMatches2(r, ctx.role) && modeMatches2(r, ctx.mode)
    );
    const scored = eligible.map((r) => ({ r, score: scoreText(r, ctx.qLower, ctx.tokens) })).filter(({ score }) => score > 0).sort((a, b) => b.score - a.score).slice(0, maxItems);
    return scored.map(({ r, score }) => ({
      id: r.id,
      item_type: r.item_type,
      title: r.title,
      answer: r.answer ?? r.content,
      score
    }));
  } catch {
    return [];
  }
}

