async function runGrowthReportAnalysisWorker(db63 = superAdminDb81) {
  const result = {
    analyzed: 0,
    skipped: 0,
    failed: 0,
    errors: []
  };
  const pending = await fetchPendingReports(db63);
  if (pending.length === 0) return result;
  for (const item of pending) {
    try {
      await analyzeOneReport(db63, item);
      result.analyzed++;
    } catch (err15) {
      result.failed++;
      result.errors.push(`report=${item.report.id}: ${err15.message}`);
      console.error(`[gr3-worker] unexpected error report=${item.report.id}:`, err15.message);
    }
  }
  return result;
}
function startGrowthReportAnalysisWorker() {
  cron4.schedule("*/5 * * * *", async () => {
    const locked = await acquireLock(ANALYSIS_LOCK, LOCK_TTL_SECONDS);
    if (!locked) {
      console.log("[gr3-worker] lock not acquired \u2014 other instance running");
      return;
    }
    try {
      const result = await runGrowthReportAnalysisWorker();
      if (result.analyzed > 0 || result.failed > 0) {
        await recordHeartbeat(ANALYSIS_LOCK, {
          at: (/* @__PURE__ */ new Date()).toISOString(),
          analyzed: result.analyzed,
          failed: result.failed
        });
      }
    } catch (err15) {
      console.error("[gr3-worker] cron error:", err15.message);
    } finally {
      await releaseLock(ANALYSIS_LOCK);
    }
  });
  setTimeout(async () => {
    const locked = await acquireLock(ANALYSIS_LOCK, LOCK_TTL_SECONDS);
    if (!locked) return;
    try {
      console.log("[gr3-worker] startup analysis run");
      await runGrowthReportAnalysisWorker();
    } catch (err15) {
      console.error("[gr3-worker] startup error:", err15.message);
    } finally {
      await releaseLock(ANALYSIS_LOCK);
    }
  }, 45e3);
  console.log("[gr3-worker] Growth Report Analysis Worker \uC2DC\uC791 (every 5min + 45s startup)");
}

