var publishGrowthReportRouter = Router66();
var publish_growth_report_default = publishGrowthReportRouter;
publishGrowthReportRouter.post(
  "/teacher/growth-reports/:reportId/publish",
  requireAuth,
  requireRole("pool_admin", "super_admin"),
  // teacher = APPROVE only (spec §3)
  async (req, res) => {
    const { reportId } = req.params;
    const { role, userId } = req.user;
    try {
      if (role === "pool_admin") {
        const callerPool = req.user.poolId;
        if (callerPool) {
          const reportCheck = await superAdminDb83.execute(sql101`
            SELECT swimming_pool_id
            FROM growth_reports
            WHERE id = ${reportId} AND deleted_at IS NULL
            LIMIT 1
          `);
          if (!reportCheck.rows.length) {
            res.status(404).json({ success: false, error: "REPORT_NOT_FOUND" });
            return;
          }
          const reportPool = reportCheck.rows[0].swimming_pool_id;
          if (reportPool !== callerPool) {
            res.status(403).json({ success: false, error: "POOL_MISMATCH" });
            return;
          }
        }
      }
      const result = await publishGrowthReport({
        db: superAdminDb83,
        reportId,
        actorId: userId,
        actorType: role
      });
      res.status(200).json({
        success: true,
        alreadyPublished: result.alreadyPublished,
        publishedAt: result.publishedAt ?? null
      });
      if (!result.alreadyPublished && result.studentId) {
        setImmediate(() => {
          notifyGrowthReportPublished({
            reportId,
            studentId: result.studentId,
            poolId: result.poolId ?? "",
            reportPeriod: result.reportPeriod ?? "",
            publishedAt: result.publishedAt ?? (/* @__PURE__ */ new Date()).toISOString(),
            actorId: userId
          }).catch((err15) => {
            console.error("[GR7] notification pipeline failed:", err15);
          });
        });
      }
    } catch (err15) {
      if (err15 instanceof ReportNotFoundError) {
        res.status(404).json({ success: false, error: "REPORT_NOT_FOUND" });
        return;
      }
      if (err15 instanceof PublishNotAllowedError) {
        res.status(409).json({
          success: false,
          error: "PUBLISH_NOT_ALLOWED",
          detail: err15.currentStatus
        });
        return;
      }
      if (err15 instanceof PublishPreconditionError) {
        res.status(422).json({
          success: false,
          error: "PRECONDITION_FAILED",
          detail: err15.detail
        });
        return;
      }
      if (err15 instanceof InvalidTransitionError) {
        res.status(409).json({
          success: false,
          error: "INVALID_TRANSITION"
        });
        return;
      }
      console.error("[publish-growth-report] error:", err15);
      res.status(500).json({ success: false, error: "INTERNAL_ERROR" });
    }
  }
);

