// src/jobs/queue-worker.ts
import { db as db61 } from "@workspace/db";
import { sql as sql109 } from "drizzle-orm";
var RETRY_QUEUE_LOCK = "event-retry-queue";
var MAKEUP_EXPIRY_LOCK = "makeup-expiry-cleanup";
var RETRY_INTERVAL_MS = 5 * 60 * 1e3;
var RETRY_TTL_SECONDS = 290;
var EXPIRY_INTERVAL_MS = 60 * 60 * 1e3;
var EXPIRY_TTL_SECONDS = 3500;
var MAKEUP_BATCH_LIMIT = 50;
async function runRetryQueue() {
  const start = Date.now();
  const locked = await acquireLock(RETRY_QUEUE_LOCK, RETRY_TTL_SECONDS);
  if (!locked) {
    console.log("[queue-worker] retry-queue: lock_not_acquired \u2014 other worker running");
    return { locked: false, errors: 0, durationMs: Date.now() - start };
  }
  try {
    await processRetryQueue();
    const durationMs = Date.now() - start;
    console.log(`[queue-worker] retry-queue: status=ok duration=${durationMs}ms`);
    void recordHeartbeat(RETRY_QUEUE_LOCK, { status: "ok", durationMs }).catch(() => {
    });
    return { locked: true, errors: 0, durationMs };
  } catch (err15) {
    const durationMs = Date.now() - start;
    console.error(`[queue-worker] retry-queue: status=error duration=${durationMs}ms error=${err15?.message ?? "unknown"}`);
    return { locked: true, errors: 1, durationMs };
  } finally {
    await releaseLock(RETRY_QUEUE_LOCK);
  }
}
async function runMakeupExpiry() {
  const start = Date.now();
  const locked = await acquireLock(MAKEUP_EXPIRY_LOCK, EXPIRY_TTL_SECONDS);
  if (!locked) {
    console.log("[queue-worker] makeup-expiry: lock_not_acquired \u2014 other worker running");
    return { locked: false, expired: 0, durationMs: Date.now() - start };
  }
  try {
    const result = await db61.execute(sql109`
      UPDATE makeup_sessions
      SET    status     = 'expired',
             updated_at = NOW()
      WHERE  id IN (
        SELECT id
        FROM   makeup_sessions
        WHERE  status     = 'waiting'
          AND  can_expire = true
          AND  expire_at  IS NOT NULL
          AND  expire_at  < NOW()
        ORDER BY expire_at ASC
        LIMIT  ${MAKEUP_BATCH_LIMIT}
      )
    `);
    const expired = result.rowCount ?? 0;
    const durationMs = Date.now() - start;
    console.log(`[queue-worker] makeup-expiry: status=ok expired=${expired} duration=${durationMs}ms`);
    void recordHeartbeat(MAKEUP_EXPIRY_LOCK, { status: "ok", expired, durationMs }).catch(() => {
    });
    return { locked: true, expired, durationMs };
  } catch (err15) {
    const durationMs = Date.now() - start;
    console.error(`[queue-worker] makeup-expiry: status=error duration=${durationMs}ms error=${err15?.message ?? "unknown"}`);
    return { locked: true, expired: 0, durationMs };
  } finally {
    await releaseLock(MAKEUP_EXPIRY_LOCK);
  }
}
function startQueueWorker() {
  console.log("[queue-worker] \uC2DC\uC791: retry-queue(5\uBD84), makeup-expiry(1\uC2DC\uAC04)");
  setTimeout(() => {
    runRetryQueue().catch(
      (e) => console.error("[queue-worker] retry-queue initial run error:", e?.message)
    );
  }, 3e4);
  setInterval(() => {
    runRetryQueue().catch(
      (e) => console.error("[queue-worker] retry-queue interval error:", e?.message)
    );
  }, RETRY_INTERVAL_MS);
  setTimeout(() => {
    runMakeupExpiry().catch(
      (e) => console.error("[queue-worker] makeup-expiry initial run error:", e?.message)
    );
  }, 6e4);
  setInterval(() => {
    runMakeupExpiry().catch(
      (e) => console.error("[queue-worker] makeup-expiry interval error:", e?.message)
    );
  }, EXPIRY_INTERVAL_MS);
}

// src/jobs/growth-report-scheduler.ts
import cron10 from "node-cron";
import { superAdminDb as superAdminDb88 } from "@workspace/db";
import { sql as sql110 } from "drizzle-orm";
var SCHEDULER_LOCK = "growth-report-cycle";
var LOCK_TTL_SECONDS2 = 600;
function getKSTDate(now) {
  const kstMs = now.getTime() + 9 * 60 * 60 * 1e3;
  const kst = new Date(kstMs);
  const year = kst.getUTCFullYear();
  const month = kst.getUTCMonth() + 1;
  const day = kst.getUTCDate();
  const hours = kst.getUTCHours();
  const minutes = kst.getUTCMinutes();
  const mm = String(month).padStart(2, "0");
  const dd = String(day).padStart(2, "0");
  return {
    year,
    month,
    day,
    hours,
    minutes,
    isoDate: `${year}-${mm}-${dd}`,
    reportPeriod: `${year}-${mm}`
  };
}
function computeCycleTimestamps(year, month) {
  const mm = String(month).padStart(2, "0");
  const reportPeriod = `${year}-${mm}`;
  const parentInputOpenAt = new Date(Date.UTC(year, month - 1, 24, 15, 0, 0));
  const analysisCutoffAt = new Date(parentInputOpenAt.getTime());
  let closeYear = year;
  let closeMonth = month + 1;
  if (closeMonth > 12) {
    closeMonth = 1;
    closeYear += 1;
  }
  const parentInputCloseAt = new Date(Date.UTC(closeYear, closeMonth - 1, 4, 15, 0, 0));
  return {
    reportPeriod,
    parentInputOpenAt,
    analysisCutoffAt,
    parentInputCloseAt,
    analysisFrom: null
  };
}
function emptyResult(runAt) {
  return {
    run_at: runAt,
    timezone: "Asia/Seoul",
    cycles_checked: 0,
    cycles_created: 0,
    cycles_opened: 0,
    cycles_input_closed: 0,
    reports_opened: 0,
    reports_ready_for_analysis: 0,
    skipped: 0,
    failed: 0,
    errors: []
  };
}
async function getXEligiblePools(db63) {
  const res = await db63.execute(sql110`
    SELECT id
    FROM swimming_pools
    WHERE (COALESCE(x_paid_entitlement, false) OR COALESCE(x_manual_entitlement, false))
      AND NOT COALESCE(x_force_disabled, false)
      AND xmode_config_status = 'READY'
      AND approval_status = 'approved'
  `);
  return res.rows;
}
async function openCycleForPool(db63, poolId, reportPeriod, timestamps, result) {
  const insertCycle = await db63.execute(sql110`
    INSERT INTO growth_report_cycles (
      swimming_pool_id, report_period,
      analysis_from, analysis_cutoff_at,
      parent_input_open_at, parent_input_close_at,
      timezone, cycle_status
    ) VALUES (
      ${poolId}, ${reportPeriod},
      ${null},
      ${timestamps.analysisCutoffAt.toISOString()},
      ${timestamps.parentInputOpenAt.toISOString()},
      ${timestamps.parentInputCloseAt.toISOString()},
      'Asia/Seoul', 'PENDING'
    )
    ON CONFLICT (swimming_pool_id, report_period)
    DO NOTHING
    RETURNING id
  `);
  let cycleId;
  if (insertCycle.rows.length > 0) {
    cycleId = insertCycle.rows[0].id;
    result.cycles_created++;
    console.log(`[gr-scheduler] CYCLE_CREATED: cycle=${cycleId} pool=${poolId} period=${reportPeriod}`);
  } else {
    const existCycle = await db63.execute(sql110`
      SELECT id, cycle_status FROM growth_report_cycles
      WHERE swimming_pool_id = ${poolId}
        AND report_period = ${reportPeriod}
      LIMIT 1
    `);
    if (!existCycle.rows.length) {
      throw new Error(`CYCLE_LOOKUP_FAILED: pool=${poolId} period=${reportPeriod}`);
    }
    const row = existCycle.rows[0];
    cycleId = row.id;
    if (row.cycle_status !== "PENDING") {
      result.skipped++;
      console.log(`[gr-scheduler] CYCLE_SKIP (status=${row.cycle_status}): cycle=${cycleId}`);
      return;
    }
  }
  result.cycles_checked++;
  await db63.execute(sql110`
    UPDATE growth_report_cycles
    SET cycle_status = 'ACTIVE', updated_at = now()
    WHERE id = ${cycleId}
      AND cycle_status = 'PENDING'
  `);
  result.cycles_opened++;
  await writeSchedulerAudit(db63, cycleId, poolId, "PENDING", "ACTIVE", "MONTHLY_CYCLE_OPEN");
  const students = await db63.execute(sql110`
    SELECT id FROM students
    WHERE swimming_pool_id = ${poolId}
      AND deleted_at IS NULL
  `);
  let reportsCreated = 0;
  for (const s of students.rows) {
    await db63.execute(sql110`
      INSERT INTO growth_reports (
        student_id, swimming_pool_id, cycle_id, report_period,
        product_status, parent_input_status, snapshot_version,
        period_start, period_end
      ) VALUES (
        ${s.id}, ${poolId}, ${cycleId}, ${reportPeriod},
        'NOT_OPEN', 'NONE', 0,
        now()::date, now()::date
      )
      ON CONFLICT (student_id, cycle_id)
        WHERE cycle_id IS NOT NULL AND deleted_at IS NULL
      DO NOTHING
    `);
    reportsCreated++;
  }
  if (reportsCreated > 0) {
    console.log(`[gr-scheduler] REPORTS_ENSURED: cycle=${cycleId} pool=${poolId} students=${reportsCreated}`);
  }
  const openRes = await db63.execute(sql110`
    UPDATE growth_reports
    SET product_status = 'OPEN',
        parent_input_status = 'AVAILABLE',
        updated_at = now()
    WHERE cycle_id = ${cycleId}
      AND product_status = 'NOT_OPEN'
      AND deleted_at IS NULL
    RETURNING id
  `);
  const openedCount = openRes.rows.length;
  result.reports_opened += openedCount;
  if (openedCount > 0) {
    await writeSchedulerAudit(
      db63,
      cycleId,
      poolId,
      "NOT_OPEN",
      "OPEN",
      "MONTHLY_CYCLE_OPEN",
      { reports_opened: openedCount }
    );
    console.log(`[gr-scheduler] REPORTS_OPENED: cycle=${cycleId} count=${openedCount}`);
  }
}
async function closeCycleInput(db63, cycleId, poolId, result) {
  await db63.execute(sql110`
    UPDATE growth_report_cycles
    SET cycle_status = 'INPUT_CLOSED', updated_at = now()
    WHERE id = ${cycleId}
      AND cycle_status = 'ACTIVE'
  `);
  result.cycles_input_closed++;
  await writeSchedulerAudit(db63, cycleId, poolId, "ACTIVE", "INPUT_CLOSED", "PARENT_INPUT_WINDOW_CLOSED");
  await db63.execute(sql110`
    UPDATE growth_reports
    SET parent_input_status = 'CLOSED',
        parent_input_closed_at = now(),
        updated_at = now()
    WHERE cycle_id = ${cycleId}
      AND parent_input_status IN ('AVAILABLE', 'ANSWERED', 'NONE')
      AND deleted_at IS NULL
  `);
  console.log(`[gr-scheduler] PARENT_INPUT_CLOSED: cycle=${cycleId} pool=${poolId}`);
  const qaReports = await db63.execute(sql110`
    SELECT id FROM growth_reports
    WHERE cycle_id = ${cycleId}
      AND product_status = 'QUESTION_AVAILABLE'
      AND deleted_at IS NULL
  `);
  for (const row of qaReports.rows) {
    try {
      await transitionReportStatus({
        db: db63,
        reportId: row.id,
        toStatus: "READY_FOR_ANALYSIS",
        actorType: "system",
        actorId: null,
        reason: "PARENT_INPUT_WINDOW_CLOSED"
      });
      result.reports_ready_for_analysis++;
    } catch (err15) {
      console.warn(
        `[gr-scheduler] QUESTION_AVAILABLE\u2192READY_FOR_ANALYSIS \uC2E4\uD328: report=${row.id}:`,
        err15.message
      );
      result.errors.push({ cycle_id: cycleId, report_id: row.id, code: "QA_TRANSITION_FAILED", message: err15.message });
    }
  }
  if (qaReports.rows.length > 0) {
    console.log(
      `[gr-scheduler] QA_TO_READY: cycle=${cycleId} count=${result.reports_ready_for_analysis}`
    );
  }
}
async function writeSchedulerAudit(db63, entityId, poolId, fromStatus, toStatus, reason, context) {
  try {
    const vRes = await db63.execute(sql110`
      SELECT next_audit_version('growth_report_cycle', ${entityId}) AS v
    `);
    const version = vRes.rows[0]?.v ?? 1;
    await db63.execute(sql110`
      INSERT INTO audit_logs (
        entity_type, entity_id, entity_version,
        action, actor_type, actor_id, pool_id,
        before_data, after_data, reason,
        request_id, correlation_id, ip_hash
      ) VALUES (
        'growth_report_cycle', ${entityId}, ${version},
        'update', 'system', NULL, ${poolId},
        ${JSON.stringify({ status: fromStatus })}::jsonb,
        ${JSON.stringify({ status: toStatus, ...context ?? {} })}::jsonb,
        ${reason},
        NULL, NULL, NULL
      )
    `);
  } catch (auditErr) {
    console.warn("[gr-scheduler] audit \uAE30\uB85D \uC2E4\uD328:", auditErr.message);
  }
}
async function runGrowthReportScheduler(db63, now = /* @__PURE__ */ new Date()) {
  const runAt = now.toISOString();
  const result = emptyResult(runAt);
  const kst = getKSTDate(now);
  console.log(`[gr-scheduler] RUN: kst=${kst.isoDate} ${kst.hours}:${String(kst.minutes).padStart(2, "0")} KST`);
  let xPools;
  try {
    xPools = await getXEligiblePools(db63);
  } catch (err15) {
    console.error("[gr-scheduler] X-eligible pools \uC870\uD68C \uC2E4\uD328:", err15.message);
    result.errors.push({ code: "X_POOLS_FETCH_FAILED", message: err15.message });
    return result;
  }
  const currentTs = computeCycleTimestamps(kst.year, kst.month);
  const shouldOpenCurrentMonth = now.getTime() >= currentTs.parentInputOpenAt.getTime();
  if (shouldOpenCurrentMonth && xPools.length > 0) {
    for (const pool2 of xPools) {
      try {
        await openCycleForPool(db63, pool2.id, currentTs.reportPeriod, currentTs, result);
      } catch (err15) {
        console.error(`[gr-scheduler] OPEN \uC2E4\uD328: pool=${pool2.id}:`, err15.message);
        result.failed++;
        result.errors.push({ pool_id: pool2.id, code: "CYCLE_OPEN_FAILED", message: err15.message });
      }
    }
  } else {
    console.log(
      `[gr-scheduler] 25\uC77C \uBBF8\uB3C4\uB2EC (kst_day=${kst.day}): open skip`
    );
  }
  let pendingCycles;
  try {
    const pRes = await db63.execute(sql110`
      SELECT id, swimming_pool_id, report_period, parent_input_open_at
      FROM growth_report_cycles
      WHERE cycle_status = 'PENDING'
        AND parent_input_open_at <= ${now.toISOString()}
    `);
    pendingCycles = pRes.rows;
  } catch (err15) {
    console.error("[gr-scheduler] PENDING cycles \uC870\uD68C \uC2E4\uD328:", err15.message);
    result.errors.push({ code: "PENDING_CYCLES_FETCH_FAILED", message: err15.message });
    pendingCycles = [];
  }
  for (const cycle of pendingCycles) {
    if (cycle.report_period === currentTs.reportPeriod) continue;
    try {
      const ts = (() => {
        const [y, m] = cycle.report_period.split("-").map(Number);
        return computeCycleTimestamps(y, m);
      })();
      await openCycleForPool(db63, cycle.swimming_pool_id, cycle.report_period, ts, result);
    } catch (err15) {
      console.error(`[gr-scheduler] MISSED OPEN \uC2E4\uD328: cycle=${cycle.id}:`, err15.message);
      result.failed++;
      result.errors.push({ cycle_id: cycle.id, code: "MISSED_OPEN_FAILED", message: err15.message });
    }
  }
  let activeCycles;
  try {
    const aRes = await db63.execute(sql110`
      SELECT id, swimming_pool_id, parent_input_close_at
      FROM growth_report_cycles
      WHERE cycle_status = 'ACTIVE'
        AND parent_input_close_at <= ${now.toISOString()}
    `);
    activeCycles = aRes.rows;
  } catch (err15) {
    console.error("[gr-scheduler] ACTIVE cycles \uC870\uD68C \uC2E4\uD328:", err15.message);
    result.errors.push({ code: "ACTIVE_CYCLES_FETCH_FAILED", message: err15.message });
    activeCycles = [];
  }
  for (const cycle of activeCycles) {
    try {
      await closeCycleInput(db63, cycle.id, cycle.swimming_pool_id, result);
    } catch (err15) {
      console.error(`[gr-scheduler] CLOSE \uC2E4\uD328: cycle=${cycle.id}:`, err15.message);
      result.failed++;
      result.errors.push({ cycle_id: cycle.id, code: "CYCLE_CLOSE_FAILED", message: err15.message });
    }
  }
  console.log(
    `[gr-scheduler] DONE: cycles_created=${result.cycles_created} opened=${result.cycles_opened} input_closed=${result.cycles_input_closed} reports_opened=${result.reports_opened} ready=${result.reports_ready_for_analysis} failed=${result.failed}`
  );
  return result;
}
function startGrowthReportScheduler() {
  cron10.schedule("0 1 * * *", async () => {
    const locked = await acquireLock(SCHEDULER_LOCK, LOCK_TTL_SECONDS2);
    if (!locked) {
      console.log("[gr-scheduler] lock not acquired \u2014 other instance running");
      return;
    }
    try {
      const result = await runGrowthReportScheduler(superAdminDb88);
      await recordHeartbeat(SCHEDULER_LOCK, {
        ran: true,
        at: (/* @__PURE__ */ new Date()).toISOString(),
        cycles_opened: result.cycles_opened,
        cycles_input_closed: result.cycles_input_closed,
        failed: result.failed
      });
    } catch (err15) {
      console.error("[gr-scheduler] cron \uC2E4\uD589 \uC624\uB958:", err15.message);
    } finally {
      await releaseLock(SCHEDULER_LOCK);
    }
  }, { timezone: "Asia/Seoul" });
  setTimeout(async () => {
    const locked = await acquireLock(SCHEDULER_LOCK, LOCK_TTL_SECONDS2);
    if (!locked) return;
    try {
      console.log("[gr-scheduler] startup recovery run");
      await runGrowthReportScheduler(superAdminDb88);
    } catch (err15) {
      console.error("[gr-scheduler] startup recovery \uC624\uB958:", err15.message);
    } finally {
      await releaseLock(SCHEDULER_LOCK);
    }
  }, 3e4);
  console.log("[gr-scheduler] Growth Report Scheduler \uC2DC\uC791 (01:00 KST daily + 30s startup recovery)");
}

